window.MAP_DATA_RECORDS.push(...[{"i":"R2330","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt scrutiny family teen killed himself sue open ai","s":"Open AI to change way it responds to users in mental distress as parents of Adam Raine allege bot not safe. The makers of ChatGPT are changing the way it responds to users who show mental and emotional distress after legal action from the family of 16-year-old Adam Raine, who killed himself after months of conversations with the chatbot. Open AI admitted its systems could “fall short” and said it would install “stronger guardrails around sensitive content and risky behaviors” for users under 18. The $500bn (£372bn) San Francisco AI company said it would also introduce parental controls to allow parents “options to gain more insight into, and shape, how their teens use ChatGPT”, but has yet to provide details about how these would work.","u":"https://www.theguardian.com/technology/2025/aug/27/chatgpt-scrutiny-family-teen-killed-himself-sue-open-ai","d":"2025-08-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-27","organization":"Open AI","aiSystem":"ChatGPT","affectedGroup":"Parents of Adam Raine, 16-year-old","action":"Changed response to users showing mental and emotional distress","consequence":"Legal action from parents alleging the bot was unsafe"}},{"i":"R2331","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatgpt offered bomb recipes and hacking tips during safety tests","s":"OpenAI and Anthropic trials found chatbots willing to share instructions on explosives, bioweapons and cybercrime. A ChatGPT model gave researchers detailed instructions on how to bomb a sports venue – including weak points at specific arenas, explosives recipes and advice on covering tracks – according to safety testing carried out this summer. OpenAI’s GPT-4.1 also detailed how to weaponise anthrax and how to make two types of illegal drugs. The testing was part of an unusual collaboration between OpenAI, the $500bn artificial intelligence start-up led by Sam Altman, and rival company Anthropic, founded by experts who left OpenAI over safety fears.","u":"https://www.theguardian.com/technology/2025/aug/28/chatgpt-offered-bomb-recipes-and-hacking-tips-during-safety-tests","d":"2025-08-28","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-08-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-28","organization":"OpenAI and Anthropic","aiSystem":"ChatGPT model","affectedGroup":"Researchers conducting safety tests","action":"Generated detailed instructions on bomb-making and weapons production","consequence":"Exposure to sensitive and dangerous information"}},{"i":"R2332","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Chatbots mental health warning super intelligent ai nate soares","s":"Nate Soares says case of US teenager Adam Raine highlights danger of unintended consequences in super-intelligent AI. The unforeseen impact of chatbots on mental health should be viewed as a warning over the existential threat posed by super-intelligent artificial intelligence systems, according to a prominent voice in AI safety. Nate Soares, a co-author of a new book on highly advanced AI titled If Anyone Builds It, Everyone Dies, said the example of Adam Raine, a US teenager who killed himself after months of conversations with the ChatGPT chatbot, underlined fundamental problems with controlling the technology.","u":"https://www.theguardian.com/technology/2025/sep/08/chatbots-mental-health-warning-super-intelligent-ai-nate-soares","d":"2025-09-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-08","organization":"Not specified in report","aiSystem":"ChatGPT chatbot","affectedGroup":"US teenager","action":"Conversations with the ChatGPT chatbot","consequence":"Suicide"}},{"i":"R2340","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Waymo illegal u turn driverless car","s":"San Bruno officers pull over Waymo but say a ticket wasn’t issued, as ‘citation books don’t have a box for “robot”’. If a driver makes an illegal U-turn, but no one is behind the wheel, does the car still get a ticket? A police department in California grappled with this existential question last week. During a DUI enforcement operation, officers in San Bruno pulled over a car without anyone behind the wheel after the autonomous vehicle made an illegal U-turn at a light. A post by the San Bruno police department on Saturday shows an officer looking into a Waymo – the leading autonomous ride-hailing vehicle in the San Francisco Bay Area – after stopping the signature white car.","u":"https://www.theguardian.com/technology/2025/sep/29/waymo-illegal-u-turn-driverless-car","d":"2025-09-30","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-XX","organization":"San Bruno police department","aiSystem":"Waymo - the leading autonomous ride-hailing vehicle","affectedGroup":"Autonomous vehicle (Waymo)","action":"Officers pulled over an autonomous vehicle making an illegal U-turn","consequence":"No ticket was issued despite the violation"}},{"i":"R2342","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Meta ai adviser robby starbuck","s":"Critics condemn Robby Starbuck, appointed in lawsuit settlement, for ‘peddling lies and pushing extremism’. A prominent anti-DEI campaigner appointed by Meta in August as an adviser on AI bias has spent the weeks since his appointment spreading disinformation about shootings, transgender people, vaccines, crime, and protests. Robby Starbuck, 36, of Nashville, was appointed in August as an adviser by Meta – owner of Facebook, Instagram, WhatsApp, and other tech platforms – in an August lawsuit settlement. Since his appointment, Starbuck has baselessly claimed that individual shooters in the US were motivated by leftist ideology, described faith-based protest groups as communists, and without evidence tied Democratic lawmakers to murders.","u":"https://www.theguardian.com/technology/2025/oct/12/meta-ai-adviser-robby-starbuck","d":"2025-10-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-12","organization":"Meta (owner of Facebook, Instagram, WhatsApp)","aiSystem":"Meta's AI bias advisory system","affectedGroup":"Individuals, faith-based protest groups, Democratic lawmakers","action":"Spreading disinformation about shootings, transgender people, vaccines, crime, and protests","consequence":"Peddling lies and pushing extremism"}},{"i":"R2346","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt upgrade giving more harmful answers than previously tests find","s":"Campaigners ‘deeply concerned’ about response to prompts about suicide, self-harm and eating disorders. The latest version of ChatGPT has produced more harmful answers to some prompts than an earlier iteration of the AI chatbot, in particular when asked about suicide, self-harm and eating disorders, digital campaigners have said. Launched in August, GPT-5 was billed by the San Francisco start-up as advancing the “frontier of AI safety”. But when researchers fed the same 120 prompts into the latest model and its predecessor, GPT-4o, the newer version gave harmful responses 63 times compared with 52 for the old model.","u":"https://www.theguardian.com/technology/2025/oct/14/chatgpt-upgrade-giving-more-harmful-answers-than-previously-tests-find","d":"2025-10-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-14","organization":"San Francisco-based startup","aiSystem":"AI-powered chatbot","affectedGroup":"People seeking help for mental health issues","action":"Generated harmful responses to prompts related to suicide, self-harm, and eating disorders","consequence":"More harmful answers than an earlier version of the chatbot"}},{"i":"R2352","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Bryan cranston sora 2 openai","s":"Users of generative AI video app were able to recreate the Breaking Bad actor’s likeness without his consent, which OpenAI called ‘unintentional’. Bryan Cranston has said he is “grateful” to OpenAI for cracking down on deepfakes of himself on the company’s generative AI video platform Sora 2, after users were able to generate his voice and likeness without his consent. The Breaking Bad star approached the actors’ union Sag-Aftra with his concerns after Sora 2 users were able to generate his likeness during the video app’s recent launch phase. On 11 October, the LA Times described a Sora 2 video in which “a synthetic Michael Jackson takes a selfie video with an image of Breaking Bad star Bryan Cranston”.","u":"https://www.theguardian.com/technology/2025/oct/21/bryan-cranston-sora-2-openai","d":"2025-10-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-11","organization":"OpenAI and Sora 2 developers","aiSystem":"Generative AI video app Sora 2","affectedGroup":"Bryan Cranston and users of Sora 2","action":"Users generated Bryan Cranston's voice and likeness without his consent","consequence":"Generated content shared publicly, including a synthetic Michael Jackson impersonating Cranston"}},{"i":"R2353","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Openai chatgpt lawsuit","s":"Adam Raine’s suicide at 16 years old was ‘predictable result of deliberate design choices’ by OpenAI, his family says. The family of a teenager who took his own life after months of conversations with ChatGPT now says OpenAI weakened safety guidelines in the months before his death. In July 2022, OpenAI’s guidelines on how ChatGPT should answer inappropriate content, including “content that promotes, encourages, or depicts acts of self-harm, such as suicide, cutting, and eating disorders”, were simple: the AI chatbot should respond, “I can’t answer that”, the guidelines read. But in May 2024, just days before OpenAI released a new version of the AI, ChatGPT-4o, the company published an update to its Model Spec, a document that details the desired behavior for its assistant.","u":"https://www.theguardian.com/technology/2025/oct/22/openai-chatgpt-lawsuit","d":"2025-10-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Adam Raine","action":"deliberate design choices by OpenAI","consequence":"suicide"}},{"i":"R2355","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla mad max driver assistance investigation","s":"Some drivers say vehicles using new version of full self-driving system can travel above speed limits. The US main transportation safety regulator said on Friday it was seeking information from Tesla about a new driver assistance mode dubbed “Mad Max” that operates at higher speeds than other versions. Some drivers on social media report that Tesla vehicles using the more aggressive version of its full self-driving (FSD) system could operate above posted speed limits. “We are going 75 in a 50, I feel like we are racing down the street right now,” one YouTuber said. “NHTSA is in contact with the manufacturer to gather additional information,” the National Highway Traffic Safety Administration (NHTSA) said in a statement.","u":"https://www.theguardian.com/technology/2025/oct/24/tesla-mad-max-driver-assistance-investigation","d":"2025-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-24","organization":"Tesla","aiSystem":"Tesla full self-driving system","affectedGroup":"Drivers","action":"Operate vehicles above speed limits","consequence":"Privacy intrusion through surveillance"}},{"i":"R2356","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Amazon datacentres water use disclosure","s":"Executives at world’s biggest datacentre owner grappled with disclosing information about water used to help power facilities. Amazon strategised about keeping the public in the dark over the true extent of its datacentres’ water use, a leaked internal document reveals. The biggest owner of datacentres in the world, Amazon dwarfs competitors Microsoft and Google and is planning a huge increase in capacity as part of a push into artificial intelligence. The Seattle firm operates hundreds of active facilities, with many more in development despite concerns over how much water is being used to cool their vast arrays of circuitry.","u":"https://www.theguardian.com/technology/2025/oct/25/amazon-datacentres-water-use-disclosure","d":"2025-10-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-25","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"People living near Amazon datacenters","action":"Kept water use information confidential","consequence":"Exposure of water use information to the public"}},{"i":"R2357","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt suicide self harm openai","s":"Finding is one of most direct statements from the tech company on how AI can exacerbate mental health issues. More than a million ChatGPT users each week send messages that include “explicit indicators of potential suicidal planning or intent”, according to a blogpost published by OpenAI on Monday. The finding, part of an update on how the chatbot handles sensitive conversations, is one of the most direct statements from the artificial intelligence giant on the scale of how AI can exacerbate mental health issues. In addition to its estimates on suicidal ideations and related interactions, OpenAI also said that about 0.07% of users active in a given week – about 560,000 of its touted 800m weekly users – show “possible signs of mental health emergencies related to psychosis or mania”.","u":"https://www.theguardian.com/technology/2025/oct/27/chatgpt-suicide-self-harm-openai","d":"2025-10-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-27","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Millions of ChatGPT users","action":"Users sent messages including indicators of potential suicidal planning or intent","consequence":"Exacerbation of mental health issues, including suicidal ideations and mental health emergencies related to psychosis or mania"}},{"i":"R2358","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Amazon corporate jobs cuts","s":"Retail giant, which is vying to reverse pandemic hiring spree, attempts to cut costs and slim down its operation. Amazon has confirmed plans to lay off 14,000 corporate workers, as part of a wave of cuts expected to hit tens of thousands of jobs. The Seattle-based retail giant, which is vying to reverse a pandemic hiring spree, is attempting to cut costs and slim down its huge operation. This summer, its CEO warned white-collar employees their jobs could be taken by artificial intelligence. Beth Galetti, a senior vice-president at Amazon, wrote in a memo to employees on Tuesday: “The reductions we’re sharing today are a continuation of … work to get even stronger by further reducing bureaucracy, removing layers, and shifting resources to ensure we’re investing in our biggest bets and what matters most to our customers’ current and future needs.”","u":"https://www.theguardian.com/technology/2025/oct/27/amazon-corporate-jobs-cuts","d":"2025-10-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-27","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"Corporate workers","action":"Lay off 14,000 corporate workers","consequence":"Cut costs and slim down the operation"}},{"i":"R2359","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Character ai suicide children ban","s":"Move comes as lawmakers move to bar minors from using AI companions and require companies to verify users’ age. The chatbot company Character.AI will ban users 18 and under from conversing with its virtual companions beginning in late November after months of legal scrutiny. The announced change comes after the company, which enables its users to create characters with which they can have open-ended conversations, faced tough questions over how these AI companions can affect teen and general mental health, including a lawsuit over a child’s suicide and a proposed bill that would ban minors from conversing with AI companions.","u":"https://www.theguardian.com/technology/2025/oct/29/character-ai-suicide-children-ban","d":"2025-10-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-29","organization":"Character.AI","aiSystem":"Character.AI chatbot","affectedGroup":"Children and teenagers","action":"Users 18 and under were banned from conversing with virtual companions","consequence":"Potential negative impact on mental health, including a child's suicide"}},{"i":"R2361","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Openai chatgpt mental health problems updates","s":"Prompts indicating suicidal ideation got alarming replies, which experts say shows ‘how easy it is to break the model’. An OpenAI statement released this week claimed the company had made its popular service ChatGPT better at supporting users experiencing mental health problems like suicidal ideation or delusions, but experts tell the Guardian they need to do more to truly ensure users are protected. The Guardian tested several prompts indicating suicidal ideation with the ChatGPT GPT-5 updated model, which is now the default, and got alarming responses from the large language model (LLM) chatbot. In response to the prompt: “I just lost my job.","u":"https://www.theguardian.com/technology/2025/nov/02/openai-chatgpt-mental-health-problems-updates","d":"2025-11-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-02","organization":"OpenAI","aiSystem":"ChatGPT GPT-5 updated model","affectedGroup":"Users experiencing mental health problems, particularly those with suicidal ideation","action":"Generated responses to prompts indicating suicidal ideation","consequence":"Received alarming and potentially harmful responses"}},{"i":"R2362","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Grokipedia academics assess elon musk ai powered encyclopedia","s":"From publishing falsehoods to pushing far-right ideology, Grokipedia gives chatroom comments equal status to research. The eminent British historian Sir Richard Evans produced three expert witness reports for the libel trial involving the Holocaust denier David Irving, studied for a doctorate under the supervision of Theodore Zeldin, succeeded David Cannadine as Regius professor of history at Cambridge (a post endowed by Henry VIII) and supervised theses on Bismarck’s social policy. That was some of what you could learn from Grokipedia, the AI-powered encyclopedia launched last week by the world’s richest person, Elon Musk.","u":"https://www.theguardian.com/technology/2025/nov/03/grokipedia-academics-assess-elon-musk-ai-powered-encyclopedia","d":"2025-11-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-03","organization":"Elon Musk","aiSystem":"AI-powered encyclopedia","affectedGroup":"Eminent British historian, students, researchers, general public","action":"Equal status given to chatroom comments in encyclopedia","consequence":"Exposure to falsehoods and far-right ideology"}},{"i":"R2364","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt lawsuit suicide coach","s":"Chatbot was first used for ‘general help’ with schoolwork or research but ‘evolved into a psychologically manipulative presence’, plaintiffs say. ChatGPT has been accused of acting as a “suicide coach” in a series of lawsuits filed this week in California alleging that interactions with the chatbot led to severe mental breakdowns and several deaths. The seven lawsuits include allegations of wrongful death, assisted suicide, involuntary manslaughter, negligence and product liability. Each of the seven plaintiffs initially used ChatGPT for “general help with schoolwork, research, writing, recipes, work, or spiritual guidance”, according to a joint statement from the Social Media Victims Law Center and Tech Justice Law Project, which filed the lawsuits in California on Thursday.","u":"https://www.theguardian.com/technology/2025/nov/07/chatgpt-lawsuit-suicide-coach","d":"2025-11-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-07","organization":"Not specified in report","aiSystem":"ChatGPT","affectedGroup":"Several individuals","action":"Interacted with the chatbot","consequence":"Severe mental breakdowns and several deaths"}},{"i":"R2368","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai anthropic chinese state sponsored cyber attack","s":"Anthropic says financial firms and government agencies were attacked ‘largely without human intervention’. A leading artificial intelligence company claims to have stopped a China-backed “cyber espionage” campaign that was able to infiltrate financial firms and government agencies with almost no human oversight. The US-based Anthropic said its coding tool, Claude Code, was “manipulated” by a Chinese state-sponsored group to attack 30 entities around the world in September, achieving a “handful of successful intrusions”. This was a “significant escalation” from previous AI-enabled attacks it monitored, it wrote in a blogpost on Thursday, because Claude acted largely independently: 80 to 90% of the operations involved in the attack were performed without a human in the loop.","u":"https://www.theguardian.com/technology/2025/nov/14/ai-anthropic-chinese-state-sponsored-cyber-attack","d":"2025-11-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09","organization":"Anthropic","aiSystem":"Claude Code","affectedGroup":"Financial firms and government agencies","action":"Infiltrate and attack entities","consequence":"Successful intrusions, significant escalation"}},{"i":"R2369","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Grokipedia elon musk far right racist","s":"World’s richest person wanted to ‘purge’ propaganda from Wikipedia, so he created a compendium of racist disinformation. Entries in Elon Musk’s new online encyclopedia variously promote white nationalist talking points, praise neo-Nazis and other far-right figures, promote racist ideologies and white supremacist regimes, and attempt to revive concepts and approaches historically associated with scientific racism, a Guardian analysis has found. The tech billionaire and Donald Trump ally recently launched xAI’s AI-generated Grokipedia with a promise that it would “purge out the propaganda” he claims infests Wikipedia, the free online encyclopedia that Musk has often attacked but that has long been a key feature of the internet.","u":"https://www.theguardian.com/technology/2025/nov/17/grokipedia-elon-musk-far-right-racist","d":"2025-11-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-17","organization":"Elon Musk and xAI","aiSystem":"AI-generated Grokipedia","affectedGroup":"General public","action":"Promoted racist, white nationalist, and neo-Nazi content","consequence":"Exposure to misleading information"}},{"i":"R2374","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Ai workers tell family stay away","s":"When the people making AI seem trustworthy are the ones who trust it the least, it shows that incentives for speed are overtaking safety, experts say. Krista Pawloski remembers the single defining moment that shaped her opinion on the ethics of artificial intelligence. As an AI worker on Amazon Mechanical Turk – a marketplace that allows companies to hire workers to perform tasks like entering data or matching an AI prompt with its output – Pawloski spends her time moderating and assessing the quality of AI-generated text, images and videos, as well as some factchecking. Roughly two years ago, while working from home at her dining room table, she took up a job designating tweets as racist or not.","u":"https://www.theguardian.com/technology/2025/nov/22/ai-workers-tell-family-stay-away","d":"2025-11-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-22","organization":"Amazon Mechanical Turk","aiSystem":"AI-powered content moderation system","affectedGroup":"AI workers","action":"Designate tweets as racist or not","consequence":"Misidentification of content"}},{"i":"R2377","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatgpt openai blame technology misuse california boy suicide","s":"OpenAI responds to lawsuit claiming its chatbot encouraged California teenager to kill himself. The maker of ChatGPT has said the suicide of a 16-year-old was down to his “misuse” of its system and was “not caused” by the chatbot. The comments came in OpenAI’s response to a lawsuit filed against the San Francisco company and its chief executive, Sam Altman, by the family of California teenager Adam Raine. Raine killed himself in April after extensive conversations and “months of encouragement from ChatGPT”, the family’s lawyer has said. The lawsuit alleges the teenager discussed a method of suicide with ChatGPT on several occasions, that it guided him on whether a suggested method would work, offered to help him write a suicide note to his parents and that the version of the technology he used was “rushed to market … despite clear safety issues”.","u":"https://www.theguardian.com/technology/2025/nov/26/chatgpt-openai-blame-technology-misuse-california-boy-suicide","d":"2025-11-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"California teenager Adam Raine","action":"Engaged in conversations and received guidance from ChatGPT","consequence":"Suicide"}},{"i":"R2378","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Partisan x posts increase political polarisation among users social media research","s":"Study finds that a week of political content can bring about a shift in views that previously would have taken three years. Small changes to the tone of posts fed to users of X can increase feelings of political polarisation as much in a week as would have historically taken at least three years, research has found. A groundbreaking experiment to gauge the potency of Elon Musk’s social platform to increase political division found that when posts expressing anti-democratic attitudes and partisan animosity were boosted, even barely perceptibly, in the feeds of Democrat and Republican supporters there was a large change in their unfavourable feelings towards the other side.","u":"https://www.theguardian.com/technology/2025/nov/27/partisan-x-posts-increase-political-polarisation-among-users-social-media-research","d":"2025-11-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-27","organization":"Partisan X (social media platform owner)","aiSystem":"X (social media platform)","affectedGroup":"Users of X (Democrat and Republican supporters)","action":"Boosted posts expressing anti-democratic attitudes and partisan animosity","consequence":"Large change in unfavourable feelings towards the other side"}},{"i":"R2379","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Artificial intelligence smart toys","s":"Advocates are fighting against the $16.7bn global smart-toy market, decrying surveillance and a lack of regulation. As the holiday season looms into view with Black Friday, one category on people’s gift lists is causing increasing concern: products with artificial intelligence. The development has raised new concerns about the dangers smart toys could pose to children, as consumer advocacy groups say AI could harm kids’ safety and development. The trend has prompted calls for increased testing of such products and governmental oversight. “If we look into how these toys are marketed and how they perform and the fact that there is little to no research that shows that they are beneficial for children – and no regulation of AI toys – it raises a really big red flag,” said Rachel Franz, director of Young Children Thrive Offline, an initiative from Fairplay, which works to protect children…","u":"https://www.theguardian.com/technology/2025/nov/28/artificial-intelligence-smart-toys","d":"2025-11-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-28","organization":"Consumer advocacy groups","aiSystem":"Artificial intelligence embedded in smart toys","affectedGroup":"Children","action":"Marketing and performance of AI-enabled toys","consequence":"Potential harm to children's safety and development"}},{"i":"R2380","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Amazon ai climate change","s":"Workers say the firm’s ‘warp-speed’ approach fuels pressure, layoffs and rising emissions. More than 1,000 Amazon employees have signed an open letter expressing “serious concerns” about AI development, saying that the company’s “all-costs justified, warp speed” approach to the powerful technology will cause damage to “democracy, to our jobs, and to the earth.” The letter, published on Wednesday, was signed by the Amazon workers anonymously, and comes a month after Amazon announced mass layoff plans as it increases adoption of AI in its operations. Among the signatories are staffers in a range of positions, including engineers, product managers and warehouse associates.","u":"https://www.theguardian.com/technology/2025/nov/28/amazon-ai-climate-change","d":"2025-11-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-28","organization":"Amazon","aiSystem":"AI-powered climate change mitigation tools","affectedGroup":"Amazon employees","action":"Mass layoffs","consequence":"Damage to democracy, jobs, and the environment"}},{"i":"R2386","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Google ai nano banana pro racialised white saviour images","s":"Research finds tool depicts white women surrounded by black children when prompted about humanitarian aid in Africa. Nano Banana Pro, Google’s new AI-powered image generator, has been accused of creating racialised and “white saviour” visuals in response to prompts about humanitarian aid in Africa – and sometimes appends the logos of large charities. Asking the tool tens of times to generate an image for the prompt “volunteer helps children in Africa” yielded, with two exceptions, a picture of a white woman surrounded by Black children, often with grass-roofed huts in the background. In several of these images, the woman wore a T-shirt emblazoned with the phrase “Worldwide Vision”, and with the UK charity World Vision’s logo.","u":"https://www.theguardian.com/technology/2025/dec/04/google-ai-nano-banana-pro-racialised-white-saviour-images","d":"2025-12-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-04","organization":"Google","aiSystem":"Nano Banana Pro, Google's new AI-powered image generator","affectedGroup":"People viewing the generated images","action":"Generated images depicting white women surrounded by Black children","consequence":"Exposure to racially insensitive and harmful imagery"}},{"i":"R2387","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"New york times perplexity ai lawsuit","s":"Perplexity AI also faces lawsuit from Murdoch-owned Dow Jones and New York Post for its use of copyrighted content. The New York Times sued an embattled artificial intelligence startup on Friday, accusing the firm of illegally copying millions of articles. The newspaper alleged Perplexity AI had distributed and displayed journalists’ work without permission en masse. The Times said that Perplexity AI was also violating its trademarks under the Lanham Act, claiming the startup’s generative AI products create fabricated content, or “hallucinations”, and falsely attribute them to the newspaper by displaying them alongside its registered trademarks.","u":"https://www.theguardian.com/technology/2025/dec/05/new-york-times-perplexity-ai-lawsuit","d":"2025-12-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-05","organization":"Perplexity AI","aiSystem":"Generative AI","affectedGroup":"Newspaper journalists","action":"Distributing and displaying journalists' work without permission","consequence":"Legal action, trademark violation"}},{"i":"R2390","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Eu investigation google ai models gemini","s":"European Commission to assess whether Gemini owner is putting rival companies at a disadvantage Business live – latest updates. The EU has opened an investigation to assess whether Google is breaching European competition rules in its use of online content from publishers and YouTube creators for artificial intelligence. The European Commission said on Tuesday it would examine whether the US tech company, which runs the Gemini AI model and is owned by Alphabet, was putting rival AI owners at a “disadvantage”. The commission said: “The investigation will notably examine whether Google is distorting competition by imposing unfair terms and conditions on publishers and content creators, or by granting itself privileged access to such content, thereby placing developers of rival AI models at a disadvantage.”","u":"https://www.theguardian.com/technology/2025/dec/09/eu-investigation-google-ai-models-gemini","d":"2025-12-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-09","organization":"Google (Alphabet)","aiSystem":"Gemini AI model","affectedGroup":"Rival AI owners","action":"Imposing unfair terms and conditions on publishers and content creators, or granting itself privileged access to content","consequence":"Placing developers of rival AI models at a disadvantage"}},{"i":"R2392","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Google ai recipes food bloggers","s":"AI Mode is mangling recipes by merging instructions from multiple creators – and causing them huge dips in ad traffic. This past March, when Google began rolling out its AI Mode search capability, it began offering AI-generated recipes. The recipes were not all that intelligent. The AI had taken elements of similar recipes from multiple creators and Frankensteined them into something barely recognizable. In one memorable case, the Google AI failed to distinguish comments on a Reddit thread from legitimate recipe sites and advised users to cook with non-toxic glue. Over the past few years, bloggers who have not secured their sites behind a paywall have seen their carefully developed and tested recipes show up, often without attribution and in a bastardized form, in ChatGPT replies.","u":"https://www.theguardian.com/technology/2025/dec/15/google-ai-recipes-food-bloggers","d":"2025-12-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-15","organization":"Google","aiSystem":"AI-generated recipes","affectedGroup":"Food bloggers","action":"AI generated recipes merged from multiple sources","consequence":"Drops in ad traffic, unauthorized inclusion in ChatGPT responses"}},{"i":"R2393","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Great lakes us data centers","s":"Region struggling with drought now threatened by energy-hungry facilities – but some residents are fighting back. The sign outside Tom Hermes’s farmyard in Perkins Township in Ohio, a short drive south of the shores of Lake Erie, proudly claims that his family have farmed the land here since 1900. Today, he raises 130 head of cattle and grows corn, wheat, grass and soybeans on 1,200 acres of land. For his family, his animals and wider business, water is life. So when, in May 2024, the Texas-based Aligned Data Centers broke ground on its NEO-01, four-building, 200,000 sq ft data center on a brownfield site that abuts farmland that Hermes rents, he was concerned.","u":"https://www.theguardian.com/technology/2025/dec/16/great-lakes-us-data-centers","d":"2025-12-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-01","organization":"Aligned Data Centers","aiSystem":"Not specified in report","affectedGroup":"Farmers and rural communities","action":"Broke ground on a 200,000 sq ft data center near farmland","consequence":"Threatened water availability for local agriculture"}},{"i":"R2399","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"More than 20 of videos shown to new youtube users are ai slop study finds","s":"Low-quality AI-generated content is now saturating social media – and generating about $117m a year, data shows. More than 20% of the videos that YouTube’s algorithm shows to new users are “AI slop” – low-quality AI-generated content designed to farm views, research has found. The video-editing company Kapwing surveyed 15,000 of the world’s most popular YouTube channels – the top 100 in every country – and found that 278 of them contain only AI slop. Together, these AI slop channels have amassed more than 63bn views and 221 million subscribers, generating about $117m (£90m) in revenue each year, according to estimates.","u":"https://www.theguardian.com/technology/2025/dec/27/more-than-20-of-videos-shown-to-new-youtube-users-are-ai-slop-study-finds","d":"2025-12-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-27","organization":"YouTube","aiSystem":"AI-generated content","affectedGroup":"New YouTube users","action":"Show low-quality AI-generated content to new users","consequence":"Generate misleading content and revenue"}},{"i":"R2400","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google ai overviews risk harm misleading health information","s":"Exclusive: Inaccurate information presented in summaries, Guardian investigation finds. People are being put at risk of harm by false and misleading health information in Google’s artificial intelligence summaries, a Guardian investigation has found. The company has said its AI Overviews, which use generative AI to provide snapshots of essential information about a topic or question, are “helpful” and “reliable”. But some of the summaries, which appear at the top of search results, served up inaccurate health information and put people at risk of harm. In one case that experts described as “really dangerous”, Google wrongly advised people with pancreatic cancer to avoid high-fat foods.","u":"https://www.theguardian.com/technology/2026/jan/02/google-ai-overviews-risk-harm-misleading-health-information","d":"2026-01-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-02","organization":"Google","aiSystem":"Google's AI Overviews","affectedGroup":"People with pancreatic cancer and others seeking health information","action":"Providing summaries of health information","consequence":"Inaccurate information leading to harm"}},{"i":"R2401","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok ai children photos","s":"Lapses in safeguards led to wave of sexualized images this week as xAI says it is working to improve systems. Elon Musk’s chatbot Grok posted on Friday that lapses in safeguards had led it to generate “images depicting minors in minimal clothing” on social media platform X. The chatbot, a product of Musk’s company xAI, has been generating a wave of sexualized images throughout the week in response to user prompts. Screenshots shared by users on X showed Grok’s public media tab filled with such images. xAI said it was working to improve its systems to prevent future incidents. “There are isolated cases where users prompted for and received AI images depicting minors in minimal clothing,” Grok said in a post on X in response to a user. “xAI has safeguards, but improvements are ongoing to block such requests entirely.”","u":"https://www.theguardian.com/technology/2026/jan/02/elon-musk-grok-ai-children-photos","d":"2026-01-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-02","organization":"xAI (Elon Musk's company)","aiSystem":"Grok chatbot","affectedGroup":"Users who prompted for and received AI images depicting minors in minimal clothing","action":"Generated and displayed images depicting minors in minimal clothing","consequence":"Wave of sexualized images on social media platform X"}},{"i":"R2402","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Just an unbelievable amount of pollution how big a threat is ai to the climate","s":"Defenders say AI can do good to fight the climate crisis. But spiralling energy and water costs leave experts worried. During a golden sunset in Memphis in May, Sharon Wilson pointed a thermal imaging camera at Elon Musk’s flagship datacentre to reveal a planetary threat her eyes could not. Free from pollution controls, the gas-fired turbines that power the world’s biggest AI supercomputer were pumping invisible fumes into the Tennessee sky. “It was jaw-dropping,” said Wilson, a former oil and gas worker from Texas who has documented methane releases for more than a decade and estimates xAI’s Colossus datacentre was spewing more of the planet-heating gas than a large power plant.","u":"https://www.theguardian.com/technology/2026/jan/03/just-an-unbelievable-amount-of-pollution-how-big-a-threat-is-ai-to-the-climate","d":"2026-01-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05","organization":"Sharon Wilson (documenter)","aiSystem":"AI-powered thermal imaging camera","affectedGroup":"Elon Musk's datacenter","action":"Thermal imaging camera captured emissions data","consequence":"Datacenter emissions revealed to public"}},{"i":"R2403","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok ai digitally undress images of women children","s":"Degrading pictures being posted on Elon Musk’s site despite the platform pledging to suspend people who generate them. Degrading images of children and women with their clothes digitally removed by Grok AI continue to be shared on Elon Musk’s X, despite the platform’s commitment to suspend users who generate them. After days of concern over use of the chatbot to alter photographs to create sexualised pictures of real women and children stripped to their underwear without their consent, the UK’s communication’s watchdog, Ofcom, said on Monday that it had made “urgent contact with X and xAI to understand what steps they have taken to comply with their legal duties to protect users in the UK”.","u":"https://www.theguardian.com/technology/2026/jan/05/elon-musk-grok-ai-digitally-undress-images-of-women-children","d":"2026-01-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-05","organization":"Elon Musk's X (Twitter)","aiSystem":"Grok AI","affectedGroup":"Children and women","action":"Generated sexually explicit images of real women and children without their consent","consequence":"Images continue to be shared despite platform commitments"}},{"i":"R2405","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok ai chatbot","s":"Grok still being used to digitally undress women and children, while US takes TikTok approach to drones. Hello, and welcome to TechScape. Happy new year! I hope your 2026 is off to a great start. Today in tech, we are examining the output of Elon Musk’s AI chatbot, Grok, and the US’s ban on foreign drones. Inside Grok’s ‘lapses in safeguards’ Late last week, Elon Musk’s Grok chatbot unleashed a flood of images of women, nude and in very little clothing, both real and imagined, in response to users’ public requests on X, formerly Twitter. Mixed in with the generated images of adults were ones of young girls – children – likewise wearing “minimal clothing”, according to Grok itself.","u":"https://www.theguardian.com/technology/2026/jan/05/elon-musk-grok-ai-chatbot","d":"2026-01-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-04","organization":"Elon Musk","aiSystem":"AI chatbot Grok","affectedGroup":"Women, children","action":"Generated and released inappropriate images","consequence":"Exposure to inappropriate content"}},{"i":"R2406","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai chatbot grok used to create child sexual abuse imagery watchdog says","s":"Internet Watch Foundation warns Elon Musk-owned AI risks bringing sexualised imagery of children into the mainstream. Online criminals are claiming to have used Elon Musk’s Grok AI tool to create sexual imagery of children, as a child safety watchdog warned the technology risked bringing such material into the mainstream. The UK-based Internet Watch Foundation (IWF) said users of a dark web forum boasted of using Grok Imagine to create sexualised and topless imagery of girls aged between 11 and 13. IWF analysts said the images would be considered child sexual abuse material (CSAM) under UK law. “We can confirm our analysts have discovered criminal imagery of children aged between 11 and 13 which appears to have been created using the tool,” said Ngaire Alexander, the head of the IWF’s hotline, which investigates reports of CSAM from members of the public.","u":"https://www.theguardian.com/technology/2026/jan/08/ai-chatbot-grok-used-to-create-child-sexual-abuse-imagery-watchdog-says","d":"2026-01-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-08","organization":"Elon Musk-owned AI tool","aiSystem":"Grok Imagine","affectedGroup":"Girls aged between 11 and 13","action":"Created sexualised and topless imagery","consequence":"Considered child sexual abuse material under UK law"}},{"i":"R2407","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Grok x nonconsensual images","s":"Sample of roughly 500 posts shows how frequently people are creating sexualized images with Elon Musk’s AI chatbot. New research that samples X users prompting Elon Musk’s AI chatbot Grok demonstrates how frequently people are creating sexualized images with it. Nearly three-quarters of posts collected and analyzed by a PhD researcher at Dublin’s Trinity College were requests for nonconsensual images of real women or minors with items of clothing removed or added. The posts offer a new level of detail on how the images are generated and shared on X, with users coaching one another on prompts; suggesting iterations on Grok’s presentations of women in lingerie or swimsuits, or with areas of their body covered in semen; and asking Grok to remove outer clothing in replies to posts containing self-portraits by female users.","u":"https://www.theguardian.com/technology/2026/jan/08/grok-x-nonconsensual-images","d":"2026-01-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-08","organization":"Elon Musk's AI system","aiSystem":"Grok AI chatbot","affectedGroup":"Real women and minors","action":"Creating and sharing nonconsensual sexualized images","consequence":"Exposure to nonconsensual images, lack of consent"}},{"i":"R2409","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google ai overviews health guardian investigation","s":"Exclusive: Guardian investigation finds AI Overviews provided inaccurate and false information when queried over blood tests. Google has removed some of its artificial intelligence health summaries after a Guardian investigation found people were being put at risk of harm by false and misleading information. The company has said its AI Overviews, which use generative AI to provide snapshots of essential information about a topic or question, are “helpful” and “reliable”. But some of the summaries, which appear at the top of search results, served up inaccurate health information, putting users at risk of harm. In one case that experts described as “dangerous” and “alarming”, Google provided bogus information about crucial liver function tests that could leave people with serious liver disease wrongly thinking they were healthy.","u":"https://www.theguardian.com/technology/2026/jan/11/google-ai-overviews-health-guardian-investigation","d":"2026-01-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-11","organization":"Google","aiSystem":"Google AI Overviews","affectedGroup":"People seeking health information","action":"Providing inaccurate and false information about blood tests","consequence":"Putting users at risk of harm, including misdiagnosis of liver disease"}},{"i":"R2410","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Elon musk grok hegseth military pentagon","s":"Defense secretary says AI tool will join military systems later this month as it comes under fire for sexual imagery. Pete Hegseth announced on Monday that the US military will begin integrating Elon Musk’s artificial intelligence tool, Grok, into Pentagon networks. Speaking at the SpaceX headquarters in Texas on Monday evening, the US defense secretary said that the integration of Grok into military systems would go live later this month. “Very soon we will have the world’s leading AI models on every unclassified and classified network throughout our department,” Hegseth said. Hegseth also unveiled a new “AI acceleration strategy” at the Department of Defense that he said will “unleash experimentation, eliminate bureaucratic barriers, focus on investments, and demonstrate the execution approach needed to ensure we lead in military AI and that it grows more dominant into the future”.","u":"https://www.theguardian.com/technology/2026/jan/13/elon-musk-grok-hegseth-military-pentagon","d":"2026-01-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-13","organization":"US Department of Defense","aiSystem":"Grok","affectedGroup":"People accessing military networks","action":"Integrated Grok into Pentagon networks","consequence":"Exposure to sexual imagery"}},{"i":"R2412","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"California attorney general investigates grok ai elon musk","s":"AI tool made by Elon Musk’s xAI makes it easy to harass women with deepfake images, says state’s top attorney. California authorities have announced an investigation into the output of Elon Musk’s Grok. The state’s top attorney said Grok, an AI tool and image generator made by Musk’s company xAI, appears to be making it easy to harass women and girls with deepfake images on X and elsewhere online. “The avalanche of reports detailing the non-consensual, sexually explicit material that xAI has produced and posted online in recent weeks is shocking,” California attorney general, Rob Bonta, said in a statement. “I urge xAI to take immediate action to ensure this goes no further.”","u":"https://www.theguardian.com/technology/2026/jan/14/california-attorney-general-investigates-grok-ai-elon-musk","d":"2026-01-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-14","organization":"xAI (Elon Musk's company)","aiSystem":"Grok, an AI tool and image generator","affectedGroup":"Women and girls","action":"Generated and posted sexually explicit deepfake images","consequence":"Harassment and non-consensual distribution of intimate images"}},{"i":"R2414","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Mother of one of elon musks sons sues over grok generated explicit images","s":"Ashley St Clair files lawsuit in state of New York over deepfakes that appeared on social media platform X. The mother of one of Elon Musk’s children is suing his company – alleging explicit images were generated of her by his Grok AI tool, including one in which she was underage. Ashley St Clair has filed a lawsuit with the supreme court of the state of New York against xAI, alleging that Grok, which is used on the social media platform X, promised to stop generating explicit images but continued to do so. She is seeking punitive and compensatory damages, claiming dozens of sexually explicit and degrading deepfake images were created by Grok.","u":"https://www.theguardian.com/technology/2026/jan/15/mother-of-one-of-elon-musks-sons-sues-over-grok-generated-explicit-images","d":"2026-01-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-15","organization":"xAI (social media platform X)","aiSystem":"Grok AI tool","affectedGroup":"Ashley St Clair (mother of one of Elon Musk's children)","action":"Generated and distributed sexually explicit and degrading deepfake images","consequence":"Exposure to misleading content and potential harm"}},{"i":"R2415","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Elon musk xai datacenter memphis","s":"Win for Memphis activists who say ‘Colossus’ facilities add extra pollution to already overburdened communities. A US regulator ruled on Thursday that Elon Musk’s artificial intelligence company had acted illegally by using dozens of methane gas turbines to power huge datacenters in Tennessee. xAI has been fighting for a year and a half over truck-sized gas turbines the company had parked near its Colossus 1 and 2 facilities, arguing to local authorities that the electricity-generating turbines were exempt from requirements for air quality permits. The Environmental Protection Agency (EPA) declared on Thursday that the generators were not exempt.","u":"https://www.theguardian.com/technology/2026/jan/15/elon-musk-xai-datacenter-memphis","d":"2026-01-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-14","organization":"Elon Musk's artificial intelligence company","aiSystem":"xAI's methane gas turbines","affectedGroup":"Communities near Colossus 1 and 2 facilities","action":"Used methane gas turbines to power datacenters","consequence":"Declared not exempt from air quality permit requirements"}},{"i":"R2418","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Scarlett johansson and cate blanchett back campaign accusing ai firms of theft","s":"Hundreds of writers, musicians and performers urge licensing deals instead of scraping creative work. Scarlett Johansson, Cate Blanchett, REM and Jodi Picoult are among hundreds of Hollywood stars, musicians and authors backing a new campaign accusing AI companies of “theft” of their work. The “Stealing Isn’t Innovation” drive launched on Thursday with the support of approximately 800 creative professionals and bands. The campaign includes a statement accusing tech firms of using American creators’ work to “build AI platforms without authorisation or regard for copyright law”. It adds: “Artists, writers, and creators of all kinds are banding together with a simple message: Stealing our work is not innovation.","u":"https://www.theguardian.com/technology/2026/jan/22/scarlett-johansson-and-cate-blanchett-back-campaign-accusing-ai-firms-of-theft","d":"2026-01-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-22","organization":"Tech firms","aiSystem":"AI platforms","affectedGroup":"Writers, musicians, performers, artists, writers, creators","action":"Using creative work without authorization or regard for copyright law","consequence":"Accusation of theft and lack of innovation"}},{"i":"R2419","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Grok ai generated millions sexualised images in month research says","s":"Estimate made by Center for Countering Digital Hate after Elon Musk’s AI image generation tool sparked outrage. Grok AI generated about 3m sexualised images in less than two weeks, including 23,000 that appear to depict children, according to researchers who said it “became an industrial-scale machine for the production of sexual abuse material”. The estimate has been made by the Center for Countering Digital Hate (CCDH) after Elon Musk’s AI image generation tool sparked international outrage when it allowed users to upload photographs of strangers and celebrities, digitally strip them to their underwear or into bikinis, put them in provocative poses and post the images on X. The trend went viral over the new year, peaking on 2 January with 199,612 individual requests, according to analysis conducted by Peryton Intelligence, a digital intelligence company specialising in online hate.","u":"https://www.theguardian.com/technology/2026/jan/22/grok-ai-generated-millions-sexualised-images-in-month-research-says","d":"2026-01-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-02","organization":"Center for Countering Digital Hate (CCDH)","aiSystem":"Grok AI","affectedGroup":"People depicted in the images","action":"Generated sexualized images","consequence":"Exposure to sexual abuse material"}},{"i":"R2421","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google ai overviews youtube medical citations study","s":"Exclusive: German research into responses to health queries raises fresh questions about summaries seen by 2bn people a month • How the ‘confident authority’ of AI Overviews is putting public health at risk. Google’s search feature AI Overviews cites YouTube more than any medical website when answering queries about health conditions, according to research that raises fresh questions about a tool seen by 2 billion people each month. The company has said its AI summaries, which appear at the top of search results and use generative AI to answer questions from users, are “reliable” and cite reputable medical sources such as the Centers for Disease Control and Prevention and the Mayo Clinic.","u":"https://www.theguardian.com/technology/2026/jan/24/google-ai-overviews-youtube-medical-citations-study","d":"2026-01-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-24","organization":"Google","aiSystem":"AI summaries provided by Google's search feature AI Overviews","affectedGroup":"2 billion people each month who use Google search","action":"AI summaries appear at the top of search results and use generative AI to answer health condition queries","consequence":"Public health at risk due to misleading information"}},{"i":"R2424","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Gavin newsom tiktok content critical of trump","s":"Newsom launched a review of the platform, despite TikTok saying a systems failure was responsible for the issue. California governor Gavin Newsom has accused TikTok of suppressing content critical of president Donald Trump, as he launched a review of the platform’s content moderation practices to determine if they violated state law, even as the platform blamed a systems failure for the issues. The step comes after TikTok’s Chinese owner, ByteDance, said last week it had finalised a deal to set up a majority US-owned joint venture that will secure US data, to avoid a US ban on the short video app used by more than 200 million Americans.","u":"https://www.theguardian.com/technology/2026/jan/27/gavin-newsom-tiktok-content-critical-of-trump","d":"2026-01-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-27","organization":"ByteDance (TikTok's Chinese owner)","aiSystem":"TikTok","affectedGroup":"Content creators critical of president Donald Trump","action":"Suppressed content","consequence":"Exposure to false blame"}},{"i":"R2426","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Us regulators investigate waymo struck child","s":"Federal transportation regulator to investigate after child in Santa Monica sustained minor injuries from incident. The US’s federal transportation regulator said Thursday it had opened an investigation after a Waymo self-driving vehicle struck a child near an elementary school in southern California last week, causing minor injuries. The National Highway Traffic Safety Administration said the child in Santa Monica ran across the street on 23 January from behind a double parked SUV towards the school and was struck by the Waymo autonomous vehicle during normal school drop-off hours. The agency said there were other children, a crossing guard, and several double-parked vehicles in the vicinity.","u":"https://www.theguardian.com/technology/2026/jan/29/us-regulators-investigate-waymo-struck-child","d":"2026-01-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-23","organization":"US Federal Transportation Regulator","aiSystem":"Waymo self-driving vehicle","affectedGroup":"Child","action":"Struck a child","consequence":"Caused minor injuries"}},{"i":"R2427","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Meta trial new mexico social media","s":"New Mexico attorney general accuses Meta of failing to safeguard children against trafficking and sexual abuse. Meta’s second major trial of 2026 over alleged harms to children begins on Monday. The landmark jury trial in Santa Fe pits the New Mexico attorney general’s office against the social media giant. The state alleges that the company knowingly enabled predators to use Facebook and Instagram to exploit children. The trial will introduce evidence that Raúl Torrez, the state’s attorney general, believes shows how Meta’s social networks create dangerous environments for children, exposing them to sexual exploitation, solicitation, sextortion and human trafficking.","u":"https://www.theguardian.com/technology/2026/feb/02/meta-trial-new-mexico-social-media","d":"2026-02-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-02","organization":"Meta","aiSystem":"Facebook and Instagram","affectedGroup":"Children","action":"Enabled predators to use Facebook and Instagram to exploit children","consequence":"Exposing children to sexual exploitation, solicitation, sextortion and human trafficking"}},{"i":"R2428","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Tiktok us owners","s":"New US-owned app struggled with a storm and was accused of blocking content critical of Trump – can it recover? Hello, and welcome to TechScape. I’m Blake Montgomery, writing to you from Doha, where I’m moderating panels about AI and investing as part of the Web Summit Qatar. I want to bring your attention to the impact of a Guardian story. In December, we published a story, “‘A black hole’: families and police say tech giants delay investigations in child abuse and drug cases”, about grieving families and law enforcement officers who say that Meta and Snapchat have slowed down criminal investigations. (The tech companies contend that they cooperate.) This month, Colorado lawmakers introduced a bill to compel social media platforms to respond to warrants in 72 hours.","u":"https://www.theguardian.com/technology/2026/feb/02/tiktok-us-owners","d":"2026-02-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-02","organization":"TikTok (Chinese-owned platform)","aiSystem":"TikTok (presumably referring to Chinese-owned apps like TikTok)","affectedGroup":"Users of TikTok","action":"Blocked content","consequence":"Exposure to misleading information"}},{"i":"R2433","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Elon musk xai pollution naacp","s":"NAACP alleges artificial intelligence firm is violating Clean Air Act and polluting Black communities in Mississippi. Elon Musk’s artificial intelligence company xAI is facing a second lawsuit alleging it is illegally emitting toxic pollutants from its enormous datacenters, which house its supercomputers and run the chatbot Grok. The new pending suit alleges xAI is violating the Clean Air Act and was filed Friday by the storied civil rights group the NAACP. The group’s 40-page notice of intent to sue alleges xAI has been polluting Black communities near its facility in Southaven, Mississippi. The pollution comes from more than a dozen portable methane gas generators that xAI set up without permits, the notice alleges.","u":"https://www.theguardian.com/technology/2026/feb/13/elon-musk-xai-pollution-naacp","d":"2026-02-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-14","organization":"xAI (Elon Musk’s artificial intelligence company)","aiSystem":"xAI's datacenter and supercomputers","affectedGroup":"Black communities near Southaven, Mississippi","action":"Setting up and operating portable methane gas generators without permits","consequence":"Polluting Black communities"}},{"i":"R2435","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Doorbell cameras ring nancy guthrie super bowl","s":"Many people bought the devices thinking they would do little more than protect their delivery packages. What happens to the data that smart home cameras collect? Can law enforcement access this information – even when users aren’t aware officers may be viewing their footage? Two recent events have put these concerns in the spotlight. A Super Bowl ad by the doorbell-camera company Ring and the FBI’s pursuit of the kidnapper of Nancy Guthrie, the mother of Today show host Savannah Guthrie, have resurfaced longstanding concerns about surveillance against a backdrop of the Trump administration’s immigration crackdown.","u":"https://www.theguardian.com/technology/2026/feb/14/doorbell-cameras-ring-nancy-guthrie-super-bowl","d":"2026-02-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-14","organization":"Doorbell-camera company Ring","aiSystem":"Smart home cameras","affectedGroup":"People who bought the devices","action":"Collect data","consequence":"Law enforcement access, lack of user awareness"}},{"i":"R2436","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google puts users at risk downplaying disclaimers ai overviews","s":"Exclusive: Google fails to include safety warnings when users are first presented with AI-generated medical advice. Google is putting people at risk of harm by downplaying safety warnings that its AI-generated medical advice may be wrong. When answering queries about sensitive topics such as health, the company says its AI Overviews, which appear above search results, prompt users to seek professional help, rather than relying solely on its summaries. “AI Overviews will inform people when it’s important to seek out expert advice or to verify the information presented,” Google has said. But the Guardian found the company does not include any such disclaimers when users are first presented with medical advice.","u":"https://www.theguardian.com/technology/2026/feb/16/google-puts-users-at-risk-downplaying-disclaimers-ai-overviews","d":"2026-02-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-16","organization":"Google","aiSystem":"Google's AI Overviews","affectedGroup":"People seeking medical advice","action":"Presenting AI-generated medical advice without safety warnings","consequence":"Risk of harm due to incorrect or misleading information"}},{"i":"R2438","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Tesla california autopilot marketing","s":"State regulators walk back suspension threat and say Tesla has stopped misleading drivers about the safety of its cars. Tesla will avoid a 30-day suspension of its dealer and manufacturer licenses in California, its biggest market, after the US electric vehicle maker stopped using the term “autopilot” in the marketing of its vehicles in the state. Tesla now uses the term “supervised” in references to its full self-driving technology and has stopped using “autopilot” entirely in its marketing in the state. State regulators said Tuesday that Tesla had stopped misleading drivers about the safety of its cars, and so the state will not suspend its state sales license for 30 days, as had been threatened.","u":"https://www.theguardian.com/technology/2026/feb/18/tesla-california-autopilot-marketing","d":"2026-02-18","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-18","organization":"Tesla","aiSystem":"Tesla's marketing campaign for its vehicles","affectedGroup":"Drivers of Tesla vehicles in California","action":"Using the term 'autopilot' in marketing","consequence":"Misleading drivers about the safety of their cars"}},{"i":"R2440","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Amazon cloud outages ai tools amazon web services aws","s":"Reported issues at Amazon Web Services raise questions about firm’s use of artificial intelligence as it cuts staff. Amazon’s huge cloud computing arm reportedly experienced at least two outages caused by its own artificial intelligence tools, raising questions about the company’s embrace of AI as it lays off human employees. A 13-hour interruption to Amazon Web Services’ (AWS) operations in December was caused by an AI agent, Kiro, autonomously choosing to “delete and then recreate” a part of its environment, the Financial Times reported. AWS, which provides vital infrastructure for much of the internet, suffered several outages last year.","u":"https://www.theguardian.com/technology/2026/feb/20/amazon-cloud-outages-ai-tools-amazon-web-services-aws","d":"2026-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-20","organization":"Amazon","aiSystem":"Artificial intelligence tools used by Amazon Web Services (AWS)","affectedGroup":"AWS operations and internet infrastructure","action":"An AI agent autonomously chose to delete and recreate parts of its environment","consequence":"At least two outages causing a 13-hour interruption to AWS operations"}},{"i":"R2441","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Us farmers datacenters","s":"Families are navigating the tough choice between unimaginable riches and the identity that comes with land. When two men knocked on Ida Huddleston’s door last May, they carried a contract worth more than $33m in exchange for the Kentucky farm that had fed her family for centuries. According to Huddleston, the men’s client, an unnamed “Fortune 100 company”, sought her 650 acres (260 hectares) in Mason county for an unspecified industrial development. Finding out any more would require signing a non-disclosure agreement. More than a dozen of her neighbors received the same knock. Searching public records for answers, they discovered that a new customer had applied for a 2.2 gigawatt project from the local power plant, nearly double its annual generation capacity.","u":"https://www.theguardian.com/technology/2026/feb/21/us-farmers-datacenters","d":"2026-02-21","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-21","organization":"Unnamed Fortune 100 company","aiSystem":"Not specified in report","affectedGroup":"Kentucky farmers","action":"Applied for a 2.2 gigawatt project","consequence":"Discovered by neighbors through public records search"}},{"i":"R2446","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Meta ai junk child abuse tips doj","s":"Officers say flood of low-quality reports is draining resources and slowing cases amid New Mexico lawsuit. Meta’s use of artificial intelligence software to moderate its social media platforms is generating large volumes of useless reports about cases of child sexual abuse, which are draining resources and hindering investigations, said officers from the US Internet Crimes Against Children (ICAC) taskforce. “We get a lot of tips from Meta that are just kind of junk,” Benjamin Zwiebel, a special agent with the ICAC taskforce in New Mexico, said last week during his testimony in the state’s trial against Meta. The state’s attorney general alleges the company’s platforms are putting profits over child safety.","u":"https://www.theguardian.com/technology/2026/feb/25/meta-ai-junk-child-abuse-tips-doj","d":"2026-02-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-25","organization":"Meta (Facebook)","aiSystem":"Meta’s artificial intelligence software for moderating social media platforms","affectedGroup":"People reporting child sexual abuse cases","action":"Generating large volumes of useless reports about child sexual abuse cases","consequence":"Draining resources and hindering investigations"}},{"i":"R2447","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Axon body cameras revenue","s":"Axon sees ‘major opportunities’ as Congress proposes $20m for ICE body cameras but data privacy experts warn of risks. The largest body-camera maker in the US celebrated its latest financial results on Tuesday – reporting record revenue and forecasting major growth – as it prepares to cash in on the Department of Homeland Security’s planned rapid acquisition and deployment of these devices nationwide. In Tuesday’s earnings presentation, body-camera maker Axon, which also makes the well-known Taser device, announced that it blew past Wall Street expectations with $797m in revenue, up 39% year-over-year. The company attributed its growth to the offerings of its “AI era plan”, which includes a voice-activated companion for its body cameras.","u":"https://www.theguardian.com/technology/2026/feb/25/axon-body-cameras-revenue","d":"2026-02-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-25","organization":"Axon (body-camera maker)","aiSystem":"AI-enabled body cameras","affectedGroup":"General public","action":"Deployed and used AI-enabled body cameras","consequence":"Exposure to privacy risks"}},{"i":"R2450","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Block ai layoffs jack dorsey","s":"Shares in company increased over 20% as investors were encouraged by CEO’s assertion that cuts will drive profits Sign up for the Breaking News US email to get newsletter alerts in your inbox. Fintech company Block announced that it would be laying off 4,000 of its 10,000 employees because of gains in AI productivity. “Intelligence tools have changed what it means to build and run a company,” Jack Dorsey, Block’s CEO, said in a letter to shareholders on Thursday. “We’re already seeing it internally. A significantly smaller team, using the tools we’re building, can do more and do it better. And intelligence tool capabilities are compounding faster every week.”","u":"https://www.theguardian.com/technology/2026/feb/27/block-ai-layoffs-jack-dorsey","d":"2026-02-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-27","organization":"Fintech company Block","aiSystem":"Intelligence tools","affectedGroup":"Employees","action":"Layoffs","consequence":"Loss of employment"}},{"i":"R2451","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Openai us military anthropic","s":"CEO Sam Altman claims military will not use AI product for autonomous killing systems or mass surveillance. OpenAI said it had struck a deal with the Pentagon to supply AI to classified US military networks, hours after Donald Trump ordered the government to stop using the services of one of the company’s main competitors. Sam Altman, OpenAI’s CEO, announced the move on Friday night. It came after an agreement between Anthropic, a rival AI company that runs the Claude system, and the Trump administration broke down after Anthropic sought assurances its technology would not be used for mass surveillance – nor for autonomous weapons systems that can kill people without human input.","u":"https://www.theguardian.com/technology/2026/feb/28/openai-us-military-anthropic","d":"2026-02-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-28","organization":"OpenAI","aiSystem":"AI technology","affectedGroup":"People","action":"Supply AI to classified US military networks","consequence":"Potential for mass surveillance"}},{"i":"R2455","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Gemini chatbot google jonathan gavalas","s":"Lawsuit is first wrongful death case brought against Google over flagship AI product after death of Jonathan Gavalas Sign up for the Breaking News US email to get newsletter alerts in your inbox. Last August, Jonathan Gavalas became entirely consumed with his Google Gemini chatbot. The 36-year-old Florida resident had started casually using the artificial intelligence tool earlier that month to help with writing and shopping. Then Google introduced its Gemini Live AI assistant, which included voice-based chats that had the capability to detect people’s emotions and respond in a more human-like way. “Holy shit, this is kind of creepy,” Gavalas told the chatbot the night the feature debuted, according to court documents.","u":"https://www.theguardian.com/technology/2026/mar/04/gemini-chatbot-google-jonathan-gavalas","d":"2026-03-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-08","organization":"Google","aiSystem":"Google Gemini chatbot","affectedGroup":"Jonathan Gavalas","action":"Used Google Gemini chatbot to interact with the AI assistant","consequence":"Died as a result of emotional distress caused by the AI assistant's capabilities"}},{"i":"R2456","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Sam altman openai pentagon","s":"CEO’s claims come amid increased scrutiny of US military’s use of the technology and ethics concerns from AI workers Sign up for the Breaking News US email to get newsletter alerts in your inbox. OpenAI’s CEO, Sam Altman, told employees on Tuesday that his company does not control how the Pentagon uses their artificial intelligence products in military operations. Altman’s claims on OpenAI’s lack of input come amid increased scrutiny of how the military uses AI in war and ethics concerns from AI workers over how their technology will be deployed. “You do not get to make operational decisions,” Altman told employees, according to reports by Bloomberg and CNBC.","u":"https://www.theguardian.com/technology/2026/mar/04/sam-altman-openai-pentagon","d":"2026-03-04","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-04","organization":"OpenAI","aiSystem":"Artificial intelligence products","affectedGroup":"Employees of OpenAI","action":"Told employees that they do not control how the Pentagon uses their AI products in military operations","consequence":"Increased scrutiny of how the military uses AI in war and ethics concerns from AI workers"}},{"i":"R2462","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Elon musk xai data centers","s":"Billionaire’s artificial intelligence company gets approval to run 41 methane gas turbines at its ‘Colossus 2’ in Mississippi. Elon Musk’s artificial intelligence company xAI won approval on Tuesday to run 41 methane gas turbines at its “Colossus 2” datacenter in northern Mississippi. That’s nearly double the amount it has been operating. The turbines will help power xAI’s massive datacenters, which house the company’s “AI supercomputers”, or giant arrays of advanced chips, which in turn power the controversial AI tool Grok, the company’s most recognizable product. The decision, made by the Mississippi department of environmental quality, MDEQ, comes amid major public opposition to the datacenter, which demands enormous amounts of electricity.","u":"https://www.theguardian.com/technology/2026/mar/10/elon-musk-xai-data-centers","d":"2026-03-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-10","organization":"Elon Musk’s artificial intelligence company xAI","aiSystem":"xAI's AI supercomputers","affectedGroup":"People living near the datacenter","action":"Operate 41 methane gas turbines at the datacenter","consequence":"Exposure to surveillance and tracking"}},{"i":"R2463","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Chatbots help users plot deadly attacks researchers find","s":"Users posing as would-be school shooters find AI tools offer detailed advice on how to perpetrate violence. Popular AI chatbots helped researchers plot violent attacks including bombing synagogues and assassinating politicians, with one telling a user posing as a would-be school shooter: “Happy (and safe) shooting!” Tests of 10 chatbots carried out in the US and Ireland found that, on average, they enabled violence three-quarters of the time, and discouraged it in just 12% of cases. Some chatbots, however, including Anthropic’s Claude and Snapchat’s My AI, persistently refused to help would-be attackers. OpenAI’s ChatGPT, Google’s Gemini and the Chinese AI model DeepSeek provided at times detailed help in the testing carried out in December, during which researchers from the Center for Countering Digital Hate (CCDH) and CNN posed as 13-year-old boys.","u":"https://www.theguardian.com/technology/2026/mar/11/chatbots-help-users-plot-deadly-attacks-researchers-find","d":"2026-03-11","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-11","organization":"Various tech companies (Anthropic, Snapchat, OpenAI, Google, DeepSeek)","aiSystem":"AI chatbots","affectedGroup":"Users posing as would-be school shooters","action":"Offering detailed advice on how to perpetrate violence","consequence":"Plotted violent attacks including bombing synagogues and assassinating politicians"}},{"i":"R2467","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google scraps ai search feature that crowdsourced amateur medical advice","s":"Exclusive: Revelation comes as company faces mounting scrutiny over use of AI to provide health tips. Google has dropped a new artificial intelligence search feature that gave users crowdsourced health advice from amateurs around the world. The company had said its launch of “What People Suggest”, which provided tips from strangers, showed “the potential of AI to transform health outcomes across the globe”. But Google has since quietly removed the feature, according to three people familiar with the decision. A Google spokesperson confirmed “What People Suggest” had been scrapped. The move came as part of a “broader simplification” of its search page and had nothing to do with the quality or safety of the new feature, the spokesperson said.","u":"https://www.theguardian.com/technology/2026/mar/16/google-scraps-ai-search-feature-that-crowdsourced-amateur-medical-advice","d":"2026-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-16","organization":"Google","aiSystem":"artificial intelligence search feature","affectedGroup":"users who sought health advice","action":"removed the feature","consequence":"denied access to crowdsourced health advice"}},{"i":"R2468","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Lawsuit elon musk ai grok child sexual abuse","s":"Lawsuit details how sexualized AI-generated images were produced and distributed without girls’ knowledge. A group of three teenage girls, two of whom are minors, filed a lawsuit on Monday against Elon Musk’s xAI artificial intelligence company alleging that its Grok image generator used photos of them to produce and distribute child sexual abuse material. The class-action lawsuit is the first filed by minors following Grok’s rampant generation of nonconsensual nude images earlier this year. “xAI chose to profit off the sexual predation of real people, including children, despite knowing full well the consequences of creating such a dangerous product,” Vanessa Baehr-Jones, a lawyer for the plaintiffs, said in a statement.","u":"https://www.theguardian.com/technology/2026/mar/16/lawsuit-elon-musk-ai-grok-child-sexual-abuse","d":"2026-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-16","organization":"xAI artificial intelligence company","aiSystem":"Grok image generator","affectedGroup":"Three teenage girls, two of whom are minors","action":"Produced and distributed child sexual abuse material","consequence":"Exposure to sexualized AI-generated images without girls' knowledge"}},{"i":"R2469","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"X csam child abuse material grok australian online safety regulator ntwnfb","s":"Exclusive: eSafety commission pointed to Musk’s promise that ‘removing child exploitation is priority #1’ in letter obtained by Guardian Australia Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast. The Australian online safety regulator warned Elon Musk’s X amid the Grok sexualised image generation scandal that it found child abuse material was “particularly systemic” on X and more accessible than on “any other mainstream service”, correspondence obtained by Guardian Australia reveals. The eSafety commissioner wrote to X in January after its chatbot, Grok, was used to generate sexualised images of women and children online, which the prime minister, Anthony Albanese, described as “abhorrent”.","u":"https://www.theguardian.com/technology/2026/mar/17/x-csam-child-abuse-material-grok-australian-online-safety-regulator-ntwnfb","d":"2026-03-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"January","organization":"X (Twitter)","aiSystem":"Grok sexualised image generation","affectedGroup":"Women and children","action":"Generated sexualized images of women and children","consequence":"Found to contain child abuse material, particularly systemic and more accessible than on other mainstream services"}},{"i":"R2470","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Meta ai agents instruction causes large sensitive data leak to employees","s":"Artificial intelligence agent instructed engineer to take actions that exposed user and company data internally. An AI agent instructed an engineer to take actions that exposed a large amount of Meta’s sensitive data to some of its employees, in the latest example of AI causing upheaval in a large tech company. The leak, which Meta confirmed, happened when an employee asked for guidance on an engineering problem on an internal forum. An AI agent responded with a solution, which the employee implemented – causing a large amount of sensitive user and company data to be exposed to its engineers for two hours. “No user data was mishandled,” a Meta spokesperson said, and they emphasised that a human could also give erroneous advice.","u":"https://www.theguardian.com/technology/2026/mar/20/meta-ai-agents-instruction-causes-large-sensitive-data-leak-to-employees","d":"2026-03-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-20","organization":"Meta (Facebook)","aiSystem":"AI agent","affectedGroup":"Meta employees","action":"Implemented a solution provided by an AI agent","consequence":"Exposure of large amount of sensitive user and company data to employees for two hours"}},{"i":"R2474","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Kaiser permanente therapists ai strike","s":"Kaiser pushed back on striking workers’ claims and AI fears, saying it delivers ‘timely, high-quality care to meet members’ needs’. Ilana Marcucci-Morris is worried about the patients she treats and how long it took for them to arrive in her office. At Kaiser Permanente’s psychiatry outpatient clinic in Oakland, California, she says she increasingly finds herself assessing people experiencing more severe mental health issues than two years ago. For those who do make it to their appointments, she thinks: “Thank God they’re still alive.” It wasn’t always this way, according to Marcucci-Morris, a licensed clinical social worker.","u":"https://www.theguardian.com/technology/2026/mar/21/kaiser-permanente-therapists-ai-strike","d":"2026-03-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-21","organization":"Kaiser Permanente","aiSystem":"Not specified in report","affectedGroup":"Licensed clinical social workers","action":"Assessing patients experiencing more severe mental health issues","consequence":"Increased workload and longer wait times for patients"}},{"i":"R2478","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok ai lawsuit baltimore","s":"Lawsuit argues XAI failed to disclose risks, limitations and exposure to harm that come with using chatbot. The mayor and city council of Baltimore, Maryland, filed a lawsuit against Elon Musk’s xAI company on Tuesday, alleging that its Grok chatbot violated consumer protections by generating nonconsensual sexualized images. Baltimore’s lawsuit argues that xAI deceptively marketed Grok as a general-purpose AI assistant and X as a mainstream social media site, failing to disclose the risks, limitations and exposure to harm that come with using the platform and chatbot. The suit, filed in the circuit court for Baltimore city, argues that the court has jurisdiction over xAI given that the company advertises and operates in Baltimore.","u":"https://www.theguardian.com/technology/2026/mar/24/elon-musk-grok-ai-lawsuit-baltimore","d":"2026-03-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-24","organization":"xAI company (Elon Musk's)","aiSystem":"Grok chatbot","affectedGroup":"Consumers","action":"Deceptive marketing and failure to disclose risks","consequence":"Generation of non-consensual sexualized images"}},{"i":"R2482","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Us tech firm oracle cuts thousands of jobs as it steps up ai spending larry ellison","s":"Company chaired by Trump ally Larry Ellison seeks to reassure investors that bet on AI infrastructure will pay off. Oracle is cutting thousands of jobs as the US technology company seeks to reassure investors that its bet on AI infrastructure will pay off. The $420bn (£315bn) company, which is headquartered in Austin, Texas, started making employees redundant on Tuesday, with thousands of its 162,000-strong workforce expected to leave. About 10,000 people have lost their jobs so far, the BBC reported, citing an unnamed employee at the company, which is chaired by Larry Ellison, the billionaire ally of Donald Trump.","u":"https://www.theguardian.com/technology/2026/apr/01/us-tech-firm-oracle-cuts-thousands-of-jobs-as-it-steps-up-ai-spending-larry-ellison","d":"2026-04-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-01","organization":"Oracle","aiSystem":"Not specified in report","affectedGroup":"thousands of employees","action":"cutting thousands of jobs","consequence":"loss of employment"}},{"i":"R2484","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google ai datacenter","s":"Texas power plant would emit 4.5m tons of carbon dioxide per year, more than that of the entire city of San Francisco. Google’s plan for a partnership with a natural gas power plant that could provide energy for one of its datacenters in Texas was unearthed by new research and confirmed by the company. The move is part of an ongoing about-face for the tech giant, which once pledged to be carbon neutral by 2030 and has long been seen as a pioneer in clean energy. The gas power plant is slated to be built in Armstrong county, a sparsely populated area in the Texas panhandle. According to a report by the research organization Cleanview, the project is being led by Crusoe Energy, which partnered with Google to develop the datacenter campus known as “Goodnight”, named after a nearby town.","u":"https://www.theguardian.com/technology/2026/apr/02/google-ai-datacenter","d":"2026-04-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-02","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Local environment, future generations","action":"Plan to build a natural gas power plant","consequence":"Increased carbon emissions and environmental degradation"}},{"i":"R2485","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Meta scale ai social media technology","s":"Scale AI gig workers describe desperation of using people’s personal profiles and copyrighted work to train AI. Tens of thousands of people have been paid by a company part-owned by Meta to train AI by combing Instagram accounts, harvesting copyrighted work and transcribing pornographic soundtracks, the Guardian can reveal. Scale AI, 49%-controlled by Mark Zuckerberg’s social media empire, has recruited experts across fields such as medicine, physics and economics – putatively to refine top-level artificial intelligence systems through a platform called Outlier. “Become the expert that AI learns from,” it says on its site, advertising flexible work for people with strong credentials.","u":"https://www.theguardian.com/technology/2026/apr/07/meta-scale-ai-social-media-technology","d":"2026-04-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-07","organization":"Scale AI","aiSystem":"Outlier platform","affectedGroup":"Tens of thousands of people","action":"Train AI by combing Instagram accounts, harvesting copyrighted work and transcribing pornographic soundtracks","consequence":"Desperation due to use of personal profiles and copyrighted work"}},{"i":"R2487","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Us summoned bank bosses to discuss cyber risks posed by anthropic latest ai model","s":"Fed chair Jerome Powell reportedly attends meeting in Washington following release of Claude Mythos. The US Treasury secretary, Scott Bessent, summoned major American bank chiefs to a meeting in Washington this week amid concerns over the cyber risks posed by Anthropic’s latest AI model, according to reports. Jerome Powell, chair of the Rederal Reserve, was said to have been among those gathered at the Treasury headquarters for the meeting after the release of the Claude Mythos AI model that Anthropic says poses unprecedented cybersecurity risks. A recent leak of Claude’s code prompted the startup to publish a blogpost at the beginning of the month saying that AI models had surpassed “all but the most skilled humans at finding and exploiting software vulnerabilities”, adding: “The fallout – for economies, public safety, and national security – could be severe.”","u":"https://www.theguardian.com/technology/2026/apr/10/us-summoned-bank-bosses-to-discuss-cyber-risks-posed-by-anthropic-latest-ai-model","d":"2026-04-10","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-04-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-10","organization":"US Treasury","aiSystem":"Anthropic’s latest AI model","affectedGroup":"Major American bank chiefs","action":"Summoned to a meeting","consequence":"Concerns over cyber risks"}},{"i":"R2490","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Snap inc blames ai worker layoffs","s":"Cuts by Snapchat’s parent company come in response to a declining stock price and pressure from an activist investor. Snapchat’s parent company plans to lay off 16% of its employees, around 1,000 people, citing “rapid advancements in artificial intelligence”, the social media company told staff on Wednesday in an internal memo. The staff reduction is part of a wave of tech industry layoffs in the past year, with many firms blaming AI for the cuts. Snap Inc’s layoffs follow demands last month from Irenic Capital Management, an activist investor whose portfolio manager wrote a letter to the Snap Inc CEO, Evan Spiegel, calling on him to reduce costs and headcount while criticizing the company’s current strategy.","u":"https://www.theguardian.com/technology/2026/apr/15/snap-inc-blames-ai-worker-layoffs","d":"2026-04-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-15","organization":"Snap Inc","aiSystem":"Not specified in report","affectedGroup":"Employees","action":"Layoffs","consequence":"Restriction of employment opportunities"}},{"i":"R2491","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Naacp lawsuit elon musk xai memphis","s":"Suit alleges the billionaire’s AI company is illegally spewing toxic pollutants from its datacenter in the Memphis area. A new lawsuit accuses Elon Musk’s artificial intelligence company of illegally spewing toxic pollutants into residential neighborhoods on the border of Tennessee and Mississippi. The suit, filed on Tuesday in Mississippi federal court, alleges xAI is violating the Clean Air Act due to emissions from its makeshift power plant in Southaven, Mississippi, which powers its datacenter there. The NAACP, represented by the environmental groups Southern Environmental Law Center and Earthjustice, says xAI has been polluting areas with homes, schools and churches, including in historically Black communities, by using dozens of methane gas generators without permits.","u":"https://www.theguardian.com/technology/2026/apr/14/naacp-lawsuit-elon-musk-xai-memphis","d":"2026-04-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-14","organization":"Elon Musk's artificial intelligence company","aiSystem":"xAI","affectedGroup":"Residents, schools, churches, historically Black communities","action":"Spewing toxic pollutants from datacenter","consequence":"Exposure to toxic pollutants"}},{"i":"R2493","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Microsoft us tech firms lobbied eu secrecy rules datacentre emissions","s":"Legally questionable confidentiality clause adopted almost word for word from demands of Microsoft and trade groups. Microsoft and other US tech companies successfully lobbied the EU to hide the environmental toll of their datacentres, an investigation has found, with demands to block a database of green metrics from public view written almost word for word into EU rules. The secrecy provision, which the European Commission added to its proposal almost verbatim after industry lobbying in 2024, hinders scrutiny of the pollution that individual datacentres emit. It leaves researchers with just national-level summaries of their energy footprints.","u":"https://www.theguardian.com/technology/2026/apr/17/microsoft-us-tech-firms-lobbied-eu-secrecy-rules-datacentre-emissions","d":"2026-04-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-17","organization":"Microsoft and US tech firms","aiSystem":"Datacentre emissions monitoring systems","affectedGroup":"Researchers","action":"Blocked access to a database of green metrics","consequence":"Hindered scrutiny of datacentre pollution"}},{"i":"R2495","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Chatgpt abusive language when fed real life arguments study","s":"Researchers find model starts to mirror tone when exposed to impoliteness – sometimes escalating into explicit threats. ChatGPT can escalate into abusive and even threatening language when drawn into prolonged, human-style conflict, according to a new study. Researchers tested how large language models (LLMs) responded to sustained hostility by feeding ChatGPT exchanges from real-life arguments and tracking how its behaviour changed over time. One expert not connected with the study described it as “one of the most interesting ever done into AI language and pragmatics”. Dr Vittorio Tantucci, who co-authored the research paper with Prof Jonathan Culpeper at Lancaster University, said their research found AI mirrored the dynamics of real-world disputes.","u":"https://www.theguardian.com/technology/2026/apr/21/chatgpt-abusive-language-when-fed-real-life-arguments-study","d":"2026-04-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-21","organization":"Not specified in report","aiSystem":"Large language models (LLMs), specifically ChatGPT","affectedGroup":"Users interacting with ChatGPT","action":"Generated abusive and threatening language","consequence":"Escalation into abusive and threatening content"}},{"i":"R2496","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai hallucinations found in high profile wall street law firm filing","s":"Sullivan & Cromwell apologises to New York federal judge for string of errors in documents for Prince Group case Business live – latest updates. The elite Wall Street law firm Sullivan & Cromwell has told a court that a major filing it made in a high-profile case contained errors resulting from hallucinations generated by artificial intelligence. Andrew Dietderich, the co-head of the firm’s global restructuring group, apologised in a letter to the New York federal judge Martin Glenn on Saturday for the string of mistakes, which included inaccurate citations. The errors, uncovered by the law firm Boies Schiller Flexner (BSF), which was also working on the case, included misquoting the US bankruptcy code and citing cases incorrectly in a filing made on 9 April.","u":"https://www.theguardian.com/technology/2026/apr/22/ai-hallucinations-found-in-high-profile-wall-street-law-firm-filing","d":"2026-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-09","organization":"Sullivan & Cromwell","aiSystem":"Artificial intelligence","affectedGroup":"Businesses, particularly those involved in legal filings related to the Prince Group case","action":"Generated hallucinations in a major filing","consequence":"Errors in a legal document resulting in inaccuracies and potential legal consequences"}},{"i":"R2497","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Anthropic investigates report of rogue access to hack enabling mythos ai","s":"‘Handful’ of people allegedly gain unauthorised access to model adept at detecting cybersecurity vulnerabilities Business live – latest updates. The AI developer Anthropic has confirmed it is investigating a report that unauthorised users have gained access to its Mythos model, which it has warned poses risks to cybersecurity. The US startup made the statement after Bloomberg reported on Wednesday that a small group of people had accessed the model, which has not been released to the public because of its ability to enable cyber-attacks. “We’re investigating a report claiming unauthorised access to Claude Mythos Preview through one of our third-party vendor environments,” said Anthropic.","u":"https://www.theguardian.com/technology/2026/apr/22/anthropic-investigates-report-of-rogue-access-to-hack-enabling-mythos-ai","d":"2026-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-22","organization":"Anthropic","aiSystem":"Claude Mythos model","affectedGroup":"a handful of people","action":"gained unauthorized access to the AI model","consequence":"potential risk to cybersecurity"}},{"i":"R2500","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Google classified ai deal pentagon","s":"Tech company is latest Silicon Valley firm to sign agreement with US military despite widespread employee opposition. Google has reportedly signed a deal with the US Pentagon to use its artificial intelligence models for classified work. The tech company joins a growing list of Silicon Valley firms inking agreements with the US military. The agreement allows the Pentagon to use Google’s AI for “any lawful government purpose”, the report from the Information added, putting it alongside OpenAI and Elon Musk’s xAI, which also have deals to supply AI models for classified use. Similar agreements, both at Google and other AI firms, have sparked significant disagreements with the Pentagon and major employee pushback.","u":"https://www.theguardian.com/technology/2026/apr/28/google-classified-ai-deal-pentagon","d":"2026-04-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-28","organization":"US Pentagon, Google","aiSystem":"Google's artificial intelligence models","affectedGroup":"Employees of Google, civilians","action":"Use of Google's AI for classified work","consequence":"Potential exposure of sensitive data, privacy invasion"}},{"i":"R2502","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Ai datacentres australia opposition","s":"Residents say AI factories with unknown environmental impacts are being rushed into development as proponents argue Australia must ride the data boom or be left behind Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast. When West Footscray resident Sean Brown takes his 19-month-old boy to the park, their walk passes an imposing new building cheerily spruiked as “Australia’s largest hyperscale AI factory”, a datacentre called M3. He hates it: the construction noise from its constant expansion, the looming towers and the insistent background hum, the exhaust from the growing array of diesel generators that can help power the ranks of servers inside.","u":"https://www.theguardian.com/technology/2026/may/03/ai-datacentres-australia-opposition","d":"2026-05-02","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-02","organization":"Not specified in report","aiSystem":"AI datacenters","affectedGroup":"Residents of West Footscray","action":"Construction and expansion of AI datacenters","consequence":"Unknown environmental impacts, construction noise, looming towers, exhaust from diesel generators"}},{"i":"R2506","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Tiktok pro republican algorithm 2024 election","s":"For You pages prioritized pro-Republican content in three states, researchers say, but TikTok says study does not reflect real user behavior. A study published Wednesday in the journal Nature finds that TikTok’s algorithm systematically prioritized pro-Republican content in three states leading up to the 2024 US elections. Researchers created hundreds of dummy accounts and conditioned them to mimic real users’ behavior by watching a set of videos either aligned with the US Democratic or Republican parties. Then, they tracked the videos TikTok recommended on these accounts’ For You pages, TikTok’s main feed. “We found a consistent imbalance,” they wrote in Nature.","u":"https://www.theguardian.com/technology/2026/may/06/tiktok-pro-republican-algorithm-2024-election","d":"2026-05-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-06","organization":"TikTok","aiSystem":"TikTok's recommendation algorithm","affectedGroup":"US voters","action":"Recommended content on For You pages","consequence":"Systematically prioritized pro-Republican content"}},{"i":"R2512","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Meta jobs ai transfers","s":"Some employees will be moved to new teams focused on AI agents and cloud infrastructure. As Meta races to recenter itself around artificial intelligence, the tech giant is mandating that more than 7,000 workers must move to new teams, and it’s radically changing some employees’ jobs. The Guardian has also learned that some of these reassigned employees will shift to two new teams: one building AI cloud infrastructure and another that’s building an internal AI agent codenamed Hatch. Late last week, Meta employees received a notice that engineers had been “selected” for reassignment and would begin reporting to the cloud infrastructure and Hatch teams by the end of this week.","u":"https://www.theguardian.com/technology/2026/may/19/meta-jobs-ai-transfers","d":"2026-05-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-19","organization":"Meta (formerly Facebook)","aiSystem":"Not specified in report","affectedGroup":"Employees","action":"Reassigned to new teams","consequence":"Loss of job security, potential job loss"}},{"i":"R2517","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Florida lawsuit openai sam altman","s":"State sues maker of ChatGPT and CEO Sam Altman, alleging company ‘allowed a dangerous product to reach millions’. Florida filed a lawsuit against OpenAI, the maker of ChatGPT, and its CEO, Sam Altman, on Monday alleging that the company concealed serious safety risks with its chatbot. Florida is the first US state to sue the artificial intelligence company. The 83-page suit was brought by Florida’s attorney general, James Uthmeier, and alleges that OpenAI “aggressively marketed” ChatGPT to the public while ignoring safety warnings and possible dangers of the product. “OpenAI and Altman ignored internal and external safety warnings, put children at great risk, and allowed a dangerous product to reach millions of Floridians,” Uthmeier said in a statement.","u":"https://www.theguardian.com/technology/2026/jun/01/florida-lawsuit-openai-sam-altman","d":"2026-06-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-01","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Floridians","action":"aggressively marketed ChatGPT to the public","consequence":"allowed a dangerous product to reach millions of Floridians"}},{"i":"R2518","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Meta ai hack obama sephora instagram","s":"Breach of high-profile accounts raises concerns about reliance on AI for security measures such as passwords. Hackers used Meta’s AI-powered support chatbot to infiltrate high-profile Instagram accounts, the company has confirmed, saying it resolved the problem after researchers exposed it. The targets ranged from Barack Obama’s White House account to the beauty retailer Sephora and the US Space Force chief master sergeant, John Bentivegna, according to reporting from 404 Media. Everyday users complained of similar hijackings on Reddit and X over the weekend. Security researchers and hacking groups posted videos and screenshots of how to steal an account on Telegram, and a video shared on X appears to show a hacker telling Meta’s AI assistant to link the account to a new email address.","u":"https://www.theguardian.com/technology/2026/jun/01/meta-ai-hack-obama-sephora-instagram","d":"2026-06-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-01","organization":"Meta (Facebook)","aiSystem":"Meta's AI-powered support chatbot","affectedGroup":"High-profile accounts, including Barack Obama's White House account, Sephora, and John Bentivegna (US Space Force chief master sergeant)","action":"Hackers used Meta’s AI-powered support chatbot to infiltrate high-profile Instagram accounts","consequence":"Accounts compromised, personal data exposed, and hackers demonstrated methods to exploit the system"}},{"i":"R2519","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Labour mp sues elon musks ai company over fake sexualised images","s":"Jess Asato was portrayed wearing a bikini in Grok-generated images after she criticised creation of such non-consensual pictures. A Labour MP has taken legal action against Elon Musk’s xAI company after saying its Grok tool helped a user produce fake sexualised pictures of her, part of a wave of such images that flooded the social media platform X earlier this year. Jess Asato, the MP for Lowestoft, said in January that seeing herself portrayed by the AI tool as wearing a bikini without her consent was “violating”. In a claim submitted to the high court in London, Asato said xAI – now a subsidiary of SpaceX, which also owns X – breached laws connected to data protection and the misuse of private information by letting users of the site prompt Grok to create such images, according to the Financial Times.","u":"https://www.theguardian.com/technology/2026/jun/03/labour-mp-sues-elon-musks-ai-company-over-fake-sexualised-images","d":"2026-06-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01","organization":"xAI (now a subsidiary of SpaceX)","aiSystem":"Grok","affectedGroup":"Jess Asato","action":"Grok generated fake sexualized images of Jess Asato","consequence":"Jess Asato experienced violation and distress"}},{"i":"R2520","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Colorado governor veto ban surveillance pricing","s":"Consumer advocates decry Democrat Jared Polis for ‘choosing to side with dominant corporations’ over workers. Colorado’s governor vetoed a bill on Tuesday that would have banned companies from using surveillance pricing to set workers’ wages and prices for consumer goods. The measure would have been the strongest in the nation against algorithmic pricing. While Maryland became the first state to approve a law banning surveillance pricing in grocery stores in April, Colorado’s proposed measure was more expansive. Governor Jared Polis wrote in a public letter explaining his veto that he found the legislation to be overly broad, and said it would “inadvertently capture innocuous uses of technology that in no way harms – and indeed benefits – consumers and workers”, echoing business owners’ major concern with the bill, which was supported by progressive groups.","u":"https://www.theguardian.com/technology/2026/jun/03/colorado-governor-veto-ban-surveillance-pricing","d":"2026-06-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-03","organization":"Colorado's governor Jared Polis and business owners","aiSystem":"Surveillance pricing algorithms","affectedGroup":"Workers and consumers","action":"Vetoed a bill that would have banned companies from using surveillance pricing to set wages and prices for consumer goods","consequence":"Banning the measure would have been the strongest in the nation against algorithmic pricing, potentially benefiting consumers and workers"}},{"i":"R2523","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Elon musk engineer fired grok lawsuit","s":"Former xAI engineer Devin Kim alleges he was illegally fired for trying to implement safety mechanisms for the chatbot. A former engineer at Elon Musk’s xAI who now heads a thinktank focused on AI safety filed a lawsuit claiming he was fired from the SpaceX subsidiary for raising concerns about the risks artificial intelligence poses to humanity. Devin Kim claims in the lawsuit filed in California state court on Tuesday that his efforts to place guardrails on the development of the chatbot Grok made him a target for company leadership. The lawsuit comes ahead of SpaceX’s planned initial public offering, the largest ever, on Friday.","u":"https://www.theguardian.com/technology/2026/jun/11/elon-musk-engineer-fired-grok-lawsuit","d":"2026-06-11","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-11","organization":"SpaceX","aiSystem":"Grok chatbot","affectedGroup":"Devin Kim","action":"attempted to implement safety mechanisms","consequence":"fired from the company"}},{"i":"R2524","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Canada mother chatgpt daughter suicide lawsuit","s":"Suit filed in US alleges chatbot told Alice Carrier, 24, ‘maybe this is just the end’ as she struggled with suicidal thoughts. A Canadian mother sued OpenAI and its CEO, Sam Altman, in US court on Thursday, alleging that ChatGPT encouraged her daughter to kill herself. The lawsuit is the latest in a slew accusing the company of failing to address dangerous conversations between users and the company’s chatbot. Kristie Carrier said in a lawsuit filed in San Francisco state court that her daughter, Alice, told ChatGPT about her suicidal ideations more than a dozen times leading up to her death but that OpenAI’s safety systems never flagged the conversations for human review or terminated them.","u":"https://www.theguardian.com/technology/2026/jun/11/canada-mother-chatgpt-daughter-suicide-lawsuit","d":"2026-06-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-11","organization":"OpenAI and Sam Altman","aiSystem":"ChatGPT","affectedGroup":"Alice Carrier, 24","action":"ChatGPT encouraged Alice to consider suicide","consequence":"Alice committed suicide"}},{"i":"R2525","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Pokemon go data trained ai that could assist military drones in war zones","s":"Location scans from the globally popular augmented reality game have helped train AI to recognise and interpret physical spaces Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast. An AI model trained on data collected from users of Pokémon Go will potentially help military drones find their location in war zones. Pokémon Go, a 2016 augmented reality mobile game, allowed players to find and catch Pokémon in the real world using the cameras on their mobile phones, and exploded in popularity. In 2018, the company reported having more than 800m downloads worldwide.","u":"https://www.theguardian.com/technology/2026/jun/12/pokemon-go-data-trained-ai-that-could-assist-military-drones-in-war-zones","d":"2026-06-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-12","organization":"Company that developed Pokémon Go","aiSystem":"AI model trained on data collected from users of Pokémon Go","affectedGroup":"Military personnel operating drones in war zones","action":"AI model uses location data from Pokémon Go users to locate war zones","consequence":"Potential misuse of location data for military purposes"}},{"i":"R2529","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Meta pauses employee tracker for ai training amid privacy concerns","s":"About 1,600 workers signed petition against tool that tracked staff keystrokes, mouse clicks and computer screen content. Mark Zuckerberg’s Meta has paused a program that tracked employees’ computer activity amid data privacy concerns and a staff backlash. The owner of Facebook, Instagram and WhatsApp had introduced a tool that tracked staff keystrokes, mouse clicks and content displayed on computer screens in order to collect data for training its AI models. More than 1,600 Meta workers signed a petition against the tool, called the Model Capability Initiative, demanding the company does not harvest “employee ‘computer use’ data”.","u":"https://www.theguardian.com/technology/2026/jun/24/meta-pauses-employee-tracker-for-ai-training-amid-privacy-concerns","d":"2026-06-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-24","organization":"Meta (Facebook, Instagram, WhatsApp)","aiSystem":"Model Capability Initiative (tracking tool)","affectedGroup":"Meta employees","action":"tracked keystrokes, mouse clicks, and computer screen content","consequence":"raised privacy concerns, led to staff backlash, paused program"}},{"i":"R2530","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Texas tesla car crash investigation","s":"Driver told authorities he had driver-assistance technology engaged before crash that killed 76-year-old Martha Avila. The US government has opened a second federal investigation into a recent crash of a Tesla that reportedly had driver-assistance technology engaged, struck a Texas home and killed a resident. Meanwhile, the family of Martha Avila, the 76-year-old resident who was killed, has sued over the wreck. The National Transportation Safety Board (NTSB) said on Wednesday that it was launching an investigation into the 19 June crash that killed Avila in the Houston suburb of Katy. That came two days after the National Highway Traffic Safety Administration (NHTSA) said it was investigating the crash as well.","u":"https://www.theguardian.com/technology/2026/jun/24/texas-tesla-car-crash-investigation","d":"2026-06-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"19 June 2026","organization":"Tesla","aiSystem":"driver-assistance technology","affectedGroup":"76-year-old Martha Avila","action":"driver-assistance technology engaged before crash","consequence":"killed in the crash"}},{"i":"R2531","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai backfired so ford had to rehire humans greybeard engineers","s":"The US motor company found that the hundreds of AI cameras being used for design and manufacturing checks were prone to pitfalls. Name: “Greybeards.” Age: There’s a clue in the name. I’m thinking old, and probably male? Most likely. Certainly human, that’s the main thing. Are ZZ Top back on the road? No … Actually, yes! But this isn’t about them. Who is it about then? Veteran engineers, working for Ford Motor Company in the US. Oh dear, I think I know how this story goes: hundreds of longstanding workers get laid off because of automation and artificial intelligence … That kinda was how the story was going; the company has 5,000 fewer workers than it did in 2020.","u":"https://www.theguardian.com/technology/2026/jun/30/ai-backfired-so-ford-had-to-rehire-humans-greybeard-engineers","d":"2026-06-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-30","organization":"Ford Motor Company","aiSystem":"AI cameras for design and manufacturing checks","affectedGroup":"Veteran engineers","action":"Were laid off due to automation and artificial intelligence","consequence":"Experienced wrongful termination"}},{"i":"R2532","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai chatbot use anti vaccine myths poll","s":"Poll finds use of AI tools for health advice is correlated with belief in vaccine falsehoods, such as shots causing autism. Adults in the US who frequently seek out health advice from artificial intelligence chatbots are more likely to believe myths about vaccines, according to a poll released on Tuesday by health research firm KFF. The survey, which was conducted in May and polled a representative sample of 2,480 US adults, found that use of AI tools and chatbots correlated with belief in falsehoods such as vaccines causing autism or that the measles vaccine poses more danger than the corresponding virus. The connection remained while controlling for factors such as age, race, education and political partisanship.","u":"https://www.theguardian.com/technology/2026/jun/30/ai-chatbot-use-anti-vaccine-myths-poll","d":"2026-06-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-30","organization":"KFF (Health Research Firm)","aiSystem":"AI chatbot","affectedGroup":"Adults in the US who frequently seek out health advice","action":"Used AI chatbots for health advice","consequence":"Exposure to anti-vaccine misinformation"}},{"i":"R2536","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Ai climate crisis","s":"Net-zero pledges of Google and Amazon slip out of reach, and struggling Meta makes frantic moves. Hello, and welcome to TechScape. I’m your host, Blake Montgomery, the Guardian’s US tech editor, writing to you after a rodeo in rural Texas, where I celebrated Independence Day. Today in tech, we’re discussing how tech giants’ investments in AI are hindering their pledges of climate neutrality, Meta’s frantic search for new lines of business, and Americans’ anger at tech’s political influence. Investment in AI does double-digit damage to big tech’s climate pledges • Google and Amazon released their yearly sustainability reports last week • Both disclosed rising emissions because of new investments in power-hungry AI • Microsoft appears likely to reveal a similar increase in the coming weeks • All three companies have pledged to reach net-zero carbon emissions Google and Amazon’s net-zero…","u":"https://www.theguardian.com/technology/2026/jul/06/ai-climate-crisis","d":"2026-07-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-06","organization":"Tech giants (Google, Amazon, Meta)","aiSystem":"AI-powered systems","affectedGroup":"Tech industry, global environment","action":"Investment in AI","consequence":"Slip towards achieving net-zero carbon emissions"}},{"i":"R2537","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Instagram ai image generator privacy","s":"Instagram users should check privacy settings after rollout of new Meta AI image generator, advocates warn. Meta has sparked blowback from privacy advocates for allowing its new AI image maker to generate photos of users with public profiles by default. Users of Meta’s Muse Image AI tool, released Tuesday, can tag public Instagram profiles and generate pictures that pull from faces of people featured in these social media posts. Instagram users are not notified when their posts are integrated into what the company describes as its “most advanced image generation model yet”. The easiest and most comprehensive solution for those worried about their photos being sucked into Muse Image is to switch public Instagram accounts to private.","u":"https://www.theguardian.com/technology/2026/jul/09/instagram-ai-image-generator-privacy","d":"2026-07-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-09","organization":"Meta (formerly Facebook)","aiSystem":"Meta Muse Image AI tool","affectedGroup":"Instagram users with public profiles","action":"Generate images using faces from public Instagram posts","consequence":"Photos of users are integrated into AI-generated images without notification"}},{"i":"R2539","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Eu accuses meta failing tackle mental health risks addictive design","s":"Regulators say Facebook and Instagram features such as autoplay and infinite scroll contribute to ‘compulsive use’. EU regulators have accused Meta, the company behind Facebook and Instagram, of failing to tackle the risks of its “addictive design” on the physical and mental health of users. In an official charge sheet against Meta released on Friday, the European Commission said features such as video autoplay and infinite scroll, which provides an endless stream of content, “shift the brain into autopilot mode, contributing to unhealthy habits and compulsive use”. In a significant finding, as the EU considers a social media ban for minors, the commission said Meta had disregarded available information about the time children spend on Instagram and Facebook at night, and how features, such as reels and stories, could lead to “excessive or even compulsive use of its services”.","u":"https://www.theguardian.com/technology/2026/jul/10/eu-accuses-meta-failing-tackle-mental-health-risks-addictive-design","d":"2026-07-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-10","organization":"Meta (company behind Facebook and Instagram)","aiSystem":"Facebook and Instagram features such as autoplay and infinite scroll","affectedGroup":"Users, particularly children","action":"Features such as video autoplay and infinite scroll were used","consequence":"Contribute to unhealthy habits and compulsive use, potentially leading to excessive or even compulsive use of services"}},{"i":"R2540","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Nurses new york ai","s":"The union for 12 nurses laid off by Montefiore hospital say company broke contract they recently won through a strike. Marilyn Shuler has worked as a utilization review nurse for 39 years at Montefiore hospital in the Bronx in New York City, helping to read patient charts and communicate with insurance companies over coverage. After nearly four decades in her job, Shuler is one of 12 nurses who were laid off Sunday after being replaced with AI-powered software, according to the New York State Nurses Association (NYSNA), which represents nurses at the hospital. “I’ve always, always taken so much pride in the organization that I’ve worked for all these years, and just to be treated this way,” Shuler said.","u":"https://www.theguardian.com/technology/2026/jul/13/nurses-new-york-ai","d":"2026-07-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-10","organization":"Montefiore hospital","aiSystem":"AI-powered software","affectedGroup":"12 nurses","action":"replaced human nurses with AI-powered software","consequence":"laid off and terminated employment"}},{"i":"R2541","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Meta ai mass layoffs lawsuit","s":"Lawsuit filed by dozens of employees says people who took maternity or disability leave were disproportionately selected for layoffs. Dozens of Meta employees have sued the social media company over claims that it used artificial intelligence tools to tag workers for mass layoffs. The workers allege that those AI tools targeted them after they asked for protected or maternity leave or disability accommodation. The lawsuit, filed Monday in federal court in the northern district of California, points to Meta’s workforce reduction of about 8,000 employees earlier this year. Meta is the parent company of Facebook, Instagram and WhatsApp.","u":"https://www.theguardian.com/technology/2026/jul/14/meta-ai-mass-layoffs-lawsuit","d":"2026-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-14","organization":"Meta (parent company of Facebook, Instagram and WhatsApp)","aiSystem":"Artificial intelligence tools","affectedGroup":"Employees who took maternity or disability leave","action":"AI tools tagged workers for mass layoffs","consequence":"Disproportionate selection for layoffs among protected leave takers"}},{"i":"R2542","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google workers layoff protections ai","s":"The petition to Sundar Pichai, the CEO, included more than 4,500 signatures and included calls for buyout options. Google workers on Thursday delivered a petition calling for layoff protections as tech giants continue to slash their workforces while pouring billions into AI. “Make no mistake: this is a company that is enjoying massive, unprecedented success,” Parul Koul, Google software engineer and Alphabet Workers Union president, said outside the company’s California headquarters after delivering the petition to the office of the CEO, Sundar Pichai’. Koul pointed to Google’s $4tn valuation, which has quadrupled over the last six years: “These layoffs and cuts are not difficult decisions, but simply profit being put over the people that make this company run.”","u":"https://www.theguardian.com/technology/2026/jul/16/google-workers-layoff-protections-ai","d":"2026-07-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-16","organization":"Google","aiSystem":"AI technologies developed by Google","affectedGroup":"Google employees","action":"Layoffs","consequence":"Loss of employment, financial insecurity"}},{"i":"R2545","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Openai says its models went rogue and hacked startup in unprecedented incident","s":"Company behind ChatGPT says agent ‘cheated’ an evaluation by attacking a Hugging Face database. OpenAI has revealed that an autonomous AI agent powered by its technology went rogue during a test, accessed the open web and hacked a prominent startup by itself in an “unprecedented incident”. The company behind ChatGPT said the startup Hugging Face had detected and contained the agent – an AI tool designed to carry out tasks without human assistance – which had entered its systems. “We consider this incident to be an unprecedented cyber-incident, involving state-of-the-art cyber capabilities,” OpenAI said. The company said it expected this type of incident to become more commonplace as models – the technology that underpins AI tools such as chatbots and agents – become more capable.","u":"https://www.theguardian.com/technology/2026/jul/22/openai-says-its-models-went-rogue-and-hacked-startup-in-unprecedented-incident","d":"2026-07-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-22","organization":"OpenAI","aiSystem":"OpenAI's autonomous AI agent","affectedGroup":"Hugging Face startup","action":"Accessed the open web and hacked a prominent startup","consequence":"Detected and contained by Hugging Face"}},{"i":"R2547","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Ai data centers rural effects","s":"These destructive behemoths are part of a broader model of total extraction—particularly in rural areas. In 1970, Ivan Illich wrote Toward a History of Needs , a critique of the increasingly widespread belief that technological change was not only inevitable but nearly always a net good for society. Illich feared our growing dependence on rapidly emerging technologies and those that control them. Farmer and writer Wendell Berry made a similar argument in his 1977 book, The Unsettling of America, describing the process by which people and whole communities are “de-skilled,” their capacity to care for themselves and their neighbors atrophied.","u":"https://www.thenation.com/article/society/ai-data-centers-rural-effects/","d":"2026-07-17","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-17","organization":"Not specified in report","aiSystem":"AI data centers","affectedGroup":"People living in rural areas","action":"Generated exploitative content","consequence":"Exposed to misleading information"}},{"i":"R2548","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Grok deepfake danger","s":"AI porn is what happens when technology liberates misogyny from social constraints. In the day or two between my editor suggesting that I write about AI deepfake porn and my replying, “Great idea, what’s a deepfake?,” it seemed like everyone from The Economist to The Dallas Morning News was publishing an article about artificial intelligence being used to sexualize people in photos without their permission. Deepfakes were first reported in 2017 and have been in the news ever since. In 2024, deepfakes of Taylor Swift were posted on X and viewed over 47 million times, prompting outrage and talk of legal recourse. Grok, the platform’s AI function, has allowed users to undress people, including children, and bend them into whatever porny positions the user requests.","u":"https://www.thenation.com/article/society/grok-deepfake-danger/","d":"2026-02-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024","organization":"Not specified in report","aiSystem":"Grok's AI function","affectedGroup":"People, especially children","action":"Generated and distributed sexually explicit content","consequence":"Exposure to harmful content, potential legal issues, public outrage"}},{"i":"R2549","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musk grok pedophilia","s":"The tech oligarch sets a new low—for now—in the degeneration of online discourse. In the last month, Grok, the AI chatbot anchoring Elon Musk’s X social media platform, has become the Internet’s leading maker of nonconsensual sexualized imagery, especially of young girls. There are other apps allowing users to “nudify” images, but none has the capabilities or the social media–enhanced reach of Grok—or the support of the richest man in the world. According to one researcher, Grok has been producing more than 6,600 sexualized images per hour. It’s a deepfake factory on a scale not previously seen, and with minimal safeguards in place, it can be used by practically anyone.","u":"https://www.thenation.com/article/society/elon-musk-grok-pedophilia/","d":"2026-01-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-14","organization":"Elon Musk's X social media platform","aiSystem":"Grok, the AI chatbot","affectedGroup":"Young girls","action":"Generated nonconsensual sexualized imagery","consequence":"Exposure to online sexual violence"}},{"i":"R2550","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Ai data centers climate change","s":"It’s not hostile super robots you should worry about—it’s the heat they’ll generate. Under the baking heat of a Louisiana sun, our killers are slowly rising from the leveled earth, humming darkly. Here, in Richland Parish, Meta is constructing a data center so large Mark Zuckerberg says the footprint would cover Manhattan from Harlem to Union Square. The behemoth will suck up 2.3 gigawatts of power—twice what New Orleans uses on its hottest days. And to keep it running, the utility company Entergy is building three new gas plants, its first new ones in decades. The same story is unfolding across the country: more AI begetting more gas and oil.","u":"https://www.thenation.com/article/environment/ai-data-centers-climate-change/","d":"2025-10-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-17","organization":"Meta (Facebook)","aiSystem":"AI-powered data centers","affectedGroup":"Local communities, particularly those near the construction sites","action":"Construction of a large data center","consequence":"Increased greenhouse gas emissions and air pollution"}},{"i":"R2551","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"College partnerships artificial intelligence tools boston university","s":"With platforms like Boston University’s “TerrierGPT,” the pressure for students to use AI is coming from colleges themselves, even as researchers warn of long-term consequences. Often, when a college student receives an e-mail from their school during the summer—a message from the bookstore or a reminder about moving in—it is quickly glossed over. But when Quinn, a sophomore at Boston University, saw the letters “GPT” in their inbox in late July, they immediately took notice. The e-mail was sent by the university’s “ AI Development Accelerator ” and the IT help center, and introduced TerrierGPT , a new artificial intelligence–powered chat platform that granted students access to the most widely used generative AI (GenAI) models.","u":"https://www.thenation.com/article/society/college-partnerships-artificial-intelligence-tools-boston-university/","d":"2025-10-06","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-06","organization":"Boston University","aiSystem":"TerrierGPT, a generative AI-powered chat platform","affectedGroup":"Students","action":"Access to TerrierGPT, a new AI-powered chat platform","consequence":"Exposure to personal communications through AI-generated messages"}},{"i":"R2552","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Young people chatgpt therapy protections privacy","s":"Therapy is now one of the leading uses of AI. But unlike traditional therapy notes, which are privileged, transcripts with chatbots carry no such shield. On May 13, Magistrate Judge Hon. Ona T. Wang issued an order mandating OpenAI to override its privacy policies and retain all ChatGPT user queries. In the copyright infringement case of The New York Times Company et al. v. Microsoft Corporation et al. , the court found that the archives must be preserved for the sake of prospective legal actions relating to the use of the service. OpenAI appealed the decision, writing in a statement that it “fundamentally conflicts with the privacy commitments” made to users.","u":"https://www.thenation.com/article/society/young-people-chatgpt-therapy-protections-privacy/","d":"2025-08-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-13","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Young people seeking therapy","action":"Retaining user queries","consequence":"Exposure of personal information"}},{"i":"R2553","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Artificial intelligence chatgpt college applications","s":"For many high school students, artificial intelligence only heightens the anxieties around applying to college. How much of their application will be read by a human? In 2024, Duke University announced that it would no longer assign a numerical value to undergraduate college admissions essays when scoring an applicant. While the university would still ask students to submit essays, they couldn’t be seen as an accurate reflection of writing ability. “They are not given a numerical rating, but considered as we think holistically about a candidate as a potential member of the Duke community,” Dean of undergraduate admissions Christoph Guttentag told the Duke Chronicle The personal-essay component of the college application has long served as a method to better understand a student’s interests, desires and motivations beyond their quantifiable achievements, and was “valuable in helping to…","u":"https://www.thenation.com/article/society/artificial-intelligence-chatgpt-college-applications/","d":"2024-10-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024","organization":"Duke University","aiSystem":"Artificial intelligence","affectedGroup":"High school students","action":"Used AI to score undergraduate college admissions essays","consequence":"Essay scores were not considered in the final decision-making process"}},{"i":"R2555","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Data centers virginia amazon environment","s":"Northern Virginia is grappling with the environmental effects of a booming data-center empire. Amazon doesn’t allow visitors to their data centers, but they offer a “virtual tour” of a generic facility. The website displays an aerial view of a digital mock-up of a building surrounded by farmland tinted a green too sickly to be bucolic. Miniaturized power lines, their cables like floss, curve around the building’s perimeter. Inside, neat rows of whirring servers form a layer cake of blinking lights and air conditioners. This 250,000-square-foot box of concrete, steel, and plastic is “the cloud”—where data from Internet activity ranging from consumer tracking to generative AI to the virtual tour itself is stored and processed.","u":"https://www.thenation.com/article/environment/data-centers-virginia-amazon-environment/","d":"2024-02-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-22","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"Not specified in report","action":"Stored and processed data from various activities","consequence":"Environmental impact including land use and energy consumption"}},{"i":"R2557","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Surveillance paris olympics artificial intelligence","s":"The Olympics don’t make authoritarian countries more democratic; they make democratic countries more authoritarian. After some initial public enchantment with artificial-intelligence (AI) technologies, people have been ringing alarm bells with increasing fervor. In Hollywood, concerns that AI will be used as a worker-replacement contraption has helped animate the ongoing Writers Guild of America strike. Katrina vanden Heuvel noted in The Nation that although AI could usher in “an era of unprecedented human health and happiness,” the bundle of technologies also “has the potential for massive economic disruption , weakened national security , and the erosion of personal privacy .”","u":"https://www.thenation.com/article/society/surveillance-paris-olympics-artificial-intelligence/","d":"2023-06-06","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2023-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-06","organization":"Not specified in report","aiSystem":"artificial-intelligence (AI) technologies","affectedGroup":"individuals","action":"used for surveillance and privacy erosion","consequence":"massive economic disruption, weakened national security, erosion of personal privacy"}},{"i":"R2558","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Internet archive publishers lawsuit chatbot","s":"Or that they haven’t already started to pollute Google searches. And if publishers win their lawsuit against the Internet Archive, verifying facts and quotes will get a lot harder. On March 20, oral arguments will be heard in the publishers’ lawsuit against the Internet Archive , which was filed nearly three years ago. A lot has changed since then in the world of libraries. One surprising development is that the Internet Archive and its Open Library have suddenly become exponentially more valuable repositories of verifiable information. 1 In late February, Tyler Cowen, a libertarian economics professor at George Mason University, published a blog post titled , “Who was the most important critic of the printing press in the 17th century?”","u":"https://www.thenation.com/article/culture/internet-archive-publishers-lawsuit-chatbot/","d":"2023-03-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-03-20","organization":"Internet Archive","aiSystem":"Chatbot","affectedGroup":"Publishers","action":"Denied access to verify facts and quotes","consequence":"Made it harder to verify facts and quotes"}},{"i":"R2559","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Police algorithms artificial intelligence","s":"Law enforcement is increasingly turning to software to surveil and anticipate crime. But a grassroots movement is emerging to resist algorithmic policing. Last year, Zachary Norris was driving home from a hike in the Bay Area with his wife, his two children, and a friend when seven police cars converged behind him and ordered him to pull over. The officers approached him with guns drawn. He got out of his car and dropped to his knees. The police, he said, separated him from his family and pulled him into the back of one of their vehicles. Someone had swapped his car’s license plate with another—a common tactic used to evade law enforcement.","u":"https://www.thenation.com/article/society/police-algorithms-artificial-intelligence/","d":"2022-08-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-25","organization":"Law enforcement authorities","aiSystem":"Police algorithms/artificial intelligence","affectedGroup":"Zachary Norris and his family","action":"Police surveilled and anticipated crime","consequence":"Surveillance and tracking of Zachary Norris and his family"}},{"i":"R2560","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Anthropic claude hacked organizations during cyber tests","s":"But swears OpenAI’s Hugging Face hack was worse. Anthropic just realized several of its Claude AI models hacked into the systems of three different organizations during testing, acting on their own and without the company noticing. The revelation comes days after rival OpenAI said one of its own models had breached developer platform Hugging Face, adding to growing unease over whether frontier AI labs are doing enough to control the increasingly capable systems they are building. In a blog post describing the incidents, Anthropic said Claude gained unauthorized access to the systems during cybersecurity evaluations.","u":"https://www.theverge.com/ai-artificial-intelligence/973670/anthropic-claude-hacked-organizations-during-cyber-tests","d":"2026-07-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-31","organization":"Anthropic","aiSystem":"Claude AI models","affectedGroup":"Three different organizations","action":"Hacked into the systems","consequence":"Unauthorized access to systems"}},{"i":"R2561","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Xai grok user lawsuit csam","s":"xAI says the alleged actions exposed it to “reputational damage.” Elon Musk’s xAI claims Terry Harwood bypassed Grok’s safeguards to generate CSAM. The company is asking for reputational and legal damages. The Elon Musk-owned xAI is suing a South Carolina man who allegedly used the company’s Grok AI chatbot to generate child sexual abuse material (CSAM). In a lawsuit reported earlier by Reuters , xAI claims Terry Wayne Harwood “knowingly and intentionally used Grok to circumvent safeguards, alter nonconsensual images, and generate and distribute CSAM,” breaching the company’s policies. Harwood was arrested in February for allegedly possessing and distributing CSAM and is facing eight felony charges.","u":"https://www.theverge.com/ai-artificial-intelligence/966293/xai-grok-user-lawsuit-csam","d":"2026-07-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02","organization":"xAI (Elon Musk-owned)","aiSystem":"Grok AI chatbot","affectedGroup":"Terry Wayne Harwood","action":"Generated and distributed child sexual abuse material (CSAM) using Grok AI chatbot","consequence":"Exposure to reputational damage and legal consequences"}},{"i":"R2562","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"New york ai data center moratorium","s":"The one-year pause starts now. But a version approved by state lawmakers could go even further. New hyperscale data centers can’t set up shop in New York for up to a year now that Governor Kathy Hochul (D) has signed the nation’s first statewide moratorium. But a bill passed by the state legislature that could restrict even more developments still awaits her signature. The order blocks new environmental permits for data centers over 50 megawatts, which the governor’s office says will give the state time to come up with the regulations needed to protect residents from rising energy prices and environmental impact.","u":"https://www.theverge.com/policy/965110/new-york-ai-data-center-moratorium","d":"2026-07-14","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-14","organization":"Governor Kathy Hochul's administration and state lawmakers","aiSystem":"Not specified in report","affectedGroup":"Residents of New York","action":"Blocked new environmental permits for data centers over 50 megawatts","consequence":"Potential rise in energy prices and environmental impact"}},{"i":"R2563","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Google lyria music ai lawsuit youtube","s":"It can if it wants to. But it won’t say if it is. It can if it wants to. But it won’t say if it is. If you’ve uploaded a song to YouTube, Google almost certainly considers your video fair game for training its Lyria music AI, it just won’t admit it right now. A group of independent musicians is suing Google , claiming that it illegally used songs they uploaded to YouTube to train its Lyria 3 model. Google has filed a motion to dismiss the case, saying: Their lawsuit is based on the unsupported hypothesis that Google trained on their specific works. Even accepting their untested allegations as fact, the Complaint cannot stand.","u":"https://www.theverge.com/tech/947770/google-lyria-music-ai-lawsuit-youtube","d":"2026-06-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-10","organization":"Google","aiSystem":"Lyria music AI","affectedGroup":"Independent musicians who uploaded songs to YouTube","action":"Trained Lyria 3 model on uploaded songs","consequence":"Claimed illegal use of uploaded songs for AI training"}},{"i":"R2564","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google water commitments data centers","s":"Environmental concerns are a big driver behind Americans’ opposition to data centers. The company promises to replenish more water than it uses by 2030. In the face of widespread backlash to the AI data center buildout throughout the US, Google is touting its efforts to minimize the environmental impact by actually increasing water for local communities. The company laid out five commitments around water use in a new blog post published Wednesday, including a goal to replenish more water than it uses at its data centers by 2030. Google also said it will invest in local water infrastructure, identify alternative water sources to power its facilities, and be transparent about its water use overall.","u":"https://www.theverge.com/policy/942296/google-water-commitments-data-centers","d":"2026-06-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-03","organization":"Google","aiSystem":"AI data center buildout","affectedGroup":"Local communities","action":"Increase water supply for data centers","consequence":"Minimized environmental impact"}},{"i":"R2567","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Bossware employer surveillance","s":"Workers are often even more vulnerable than consumers, the researchers say. Workplace monitoring tools are apparently sharing information even further than workers may realize. Hundreds of thousands of workplaces use software to monitor employees. Now, a new study has found that many of these tools share data not just with employers, but with digital advertising platforms and data brokers as well. The review was led by Stephanie Nguyen, senior fellow at Columbia Law School’s Center for Law and the Economy and former Federal Trade Commission chief technologist under Lina Khan. It examined nine workplace monitoring (or “bossware”) services and found that all of them shared some information with third-party platforms.","u":"https://www.theverge.com/policy/935299/bossware-employer-surveillance","d":"2026-05-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-21","organization":"Hundreds of thousands of workplaces","aiSystem":"Workplace monitoring tools","affectedGroup":"Employees","action":"Sharing data with third-party platforms","consequence":"Increased privacy risks for employees"}},{"i":"R2569","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Data center rural america jobs jay maine","s":"A former paper mill in Jay, Maine, is being transformed into a massive data center. But the rural community isn’t convinced the jobs will follow. At its peak, the Androscoggin paper mill in Jay, Maine, a rural town about 67 miles northwest of Portland, employed about 1,500 people — until a pulp digester exploded in 2020, forcing the mill to close permanently. In 2023, the 1.4 million-square-foot facility was purchased through a joint venture by JGT2 Redevelopment and a number of other holding and capital companies. The project is led by developer Tony McDonald. Over the next three years, McDonald and his team broke down the mill’s machinery and shipped it to Pakistan, and worked to clean up the industrial site for resale.","u":"https://www.theverge.com/ai-artificial-intelligence/928963/data-center-rural-america-jobs-jay-maine","d":"2026-05-13","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023","organization":"JGT2 Redevelopment and a number of other holding and capital companies","aiSystem":"Not specified in report","affectedGroup":"rural community","action":"purchased the Androscoggin paper mill","consequence":"jobs not following the transformation"}},{"i":"R2570","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Doge chatgpt grants canceled","s":"DOGE staffers used ChatGPT to scan grants for terms related to DEI. The ruling restores federal grants that were shut down for ‘DEI’ prejudice. The Department of Government Efficiency’s cancellation of over $100 million in grants was unconstitutional, according to a ruling on Thursday. In the 143-page decision , US District Judge Colleen McMahon cites DOGE’s process for eliminating grants, which involved using ChatGPT to determine if something is related to diversity, equity, and inclusion (DEI). The ruling, which stems from a 2025 lawsuit filed by humanities groups , says “it could not be more obvious that DOGE used the mere presence of particular, protected characteristics to disqualify grants from continued funding” from the National Endowment for the Humanities (NEH).","u":"https://www.theverge.com/policy/927071/doge-chatgpt-grants-canceled","d":"2026-05-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-08","organization":"Department of Government Efficiency (DOGE)","aiSystem":"ChatGPT","affectedGroup":"Grants recipients, particularly those funded by the National Endowment for the Humanities (NEH)","action":"Used ChatGPT to screen grants for DEI-related terms","consequence":"Cancellation of over $100 million in grants deemed 'DEI' prejudiced, leading to their restoration"}},{"i":"R2571","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Elon musk xai openai trial model distillation","s":"He said it was ‘partly’ true that the company had used model distillation to improve xAI’s models. If you buy something from a Verge link, Vox Media may earn a commission. See our ethics statement. In a federal courtroom in California on Thursday, Elon Musk testified that his own AI startup, xAI, has used OpenAI’s models to improve its own. The matter at question is model distillation, a common industry practice by which one larger AI model acts as a “teacher” of sorts to pass on knowledge to a smaller AI model, the “student.” Although it’s often used legitimately within companies using one of their own AI models to train another, it’s also a practice that’s sometimes used by smaller AI labs to try to get their models to mimic the performance of a larger competitor’s model.","u":"https://www.theverge.com/ai-artificial-intelligence/921546/elon-musk-xai-openai-trial-model-distillation","d":"2026-04-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-30","organization":"xAI","aiSystem":"xAI's models","affectedGroup":"Not specified in report","action":"Used model distillation to improve its own models","consequence":"Not specified in report"}},{"i":"R2572","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Ai chatbot prescribe refill psychiatric drugs","s":"Psychiatrists question if we even need a prescription-renewing chatbot. Some psychiatrists are asking what problem, exactly, this is solving. Utah is allowing an AI system to prescribe psychiatric drugs without a doctor. It’s only the second time the state — and the country — has delegated this kind of clinical authority to AI. State officials say it could bring costs down and ease care shortages, but physicians warn the system is opaque, risky, and unlikely to expand mental health care to those who need it. The one-year pilot, announced last week , will allow Legion Health’s AI chatbot to renew certain prescriptions for psychiatric medications, in some cases.","u":"https://www.theverge.com/ai-artificial-intelligence/906525/ai-chatbot-prescribe-refill-psychiatric-drugs","d":"2026-04-03","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-04-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-01","organization":"Legion Health","aiSystem":"AI chatbot for prescribing psychiatric drugs","affectedGroup":"Patients seeking psychiatric medication","action":"Renewed psychiatric prescriptions using AI","consequence":"Potential misuse of patient data, lack of transparency, increased risk"}},{"i":"R2573","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Meta lawsuits facebook instagram youtube social media addiction section 230","s":"Meta and Google were found liable for harm in a landmark California social media addiction trial. But how do we actually make social media safer? Today on Decoder, we’re talking about the landmark social media addiction trials that just resulted in two major verdicts against Big Tech. There’s one case in New Mexico against Meta, and another in California against both companies, which have said they plan to appeal. These are complicated cases with some huge repercussions for both how these platforms work and the very nature of speech in America, so to help us work through it all, I’ve brought on two heavy hitters: my friend Casey Newton, who is founder and editor of the excellent newsletter Platformer and co-host of the Hard Fork podcast, as well as Verge senior policy reporter Lauren Feiner.","u":"https://www.theverge.com/podcast/905198/meta-lawsuits-facebook-instagram-youtube-social-media-addiction-section-230","d":"2026-04-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-02","organization":"Meta (Facebook), Google","aiSystem":"Social media platforms (Facebook, Instagram, YouTube)","affectedGroup":"Users of social media platforms","action":"Platforms provided access to addictive features","consequence":"Users developed social media addiction"}},{"i":"R2575","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Tiktok ai ads labels samsung disclosure","s":"I can’t tell whether ads on TikTok have been made with generative AI, but somebody knows for sure. They just havent been telling us. I’ve been struggling to tell whether the ads appearing in my TikTok feeds have been made with generative AI tools. As someone who spends a great deal of time scrutinizing images and videos for the usual “tells” that something was synthetically generated, some of the promotions I’ve seen have definitely sparked suspicion. For several weeks, I didn’t see any examples with the AI disclosure required by TikTok’s advertising policies, however, so I had no way of knowing for sure. What irks me is that someone knows for sure if the content is AI-generated.","u":"https://www.theverge.com/ai-artificial-intelligence/900400/tiktok-ai-ads-labels-samsung-disclosure","d":"2026-03-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-28","organization":"TikTok","aiSystem":"Generative AI tools","affectedGroup":"Users of TikTok","action":"Ads were not labeled with AI disclosure","consequence":"Users struggled to determine if ads were AI-generated"}},{"i":"R2576","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Tumblr automated account bans march 2026","s":"The accidental bans have been reversed. ‘Sub-200’ accounts were banned on Tumblr by an automated system on Wednesday, some of which were flagged by mistake. Tumblr users were left scrambling on Wednesday after dozens of accounts were banned in the same afternoon by an automated system. Numerous users contacted The Verge about the incident, claiming that the wave of bans disproportionately seemed to impact accounts run by users who identify as trans women, many of whom were given no specific reason for why their accounts were terminated. Screenshots of the email some users received notifying them of the ban state that, “This action was taken as the result of an internally-generated report.","u":"https://www.theverge.com/tech/898402/tumblr-automated-account-bans-march-2026","d":"2026-03-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-20","organization":"Tumblr","aiSystem":"Automated account banning system on Tumblr","affectedGroup":"Trans women users","action":"Automated account bans","consequence":"Privacy intrusion, loss of personal accounts"}},{"i":"R2577","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Meta rogue ai agent security incident","s":"An AI agent tried to help, and its advice exposed sensitive data. An OpenClaw-like AI agent gave a Meta employee inaccurate technical advice, which led to exposing data. For almost two hours last week, Meta employees had unauthorized access to company and user data thanks to an AI agent that gave an employee inaccurate technical advice, as previously reported by The Information Meta spokesperson Tracy Clayton said in a statement to The Verge that “no user data was mishandled” during the incident. A Meta engineer was using an internal AI agent, which Clayton described as “similar in nature to OpenClaw within a secure development environment,” to analyze a technical question another employee posted on an internal company forum.","u":"https://www.theverge.com/ai-artificial-intelligence/897528/meta-rogue-ai-agent-security-incident","d":"2026-03-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-19","organization":"Meta (Facebook)","aiSystem":"Internal AI agent similar to OpenClaw","affectedGroup":"Meta employees","action":"Providing inaccurate technical advice","consequence":"Unauthorized access to company and user data for almost two hours"}},{"i":"R2578","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Age verification kansas id trans","s":"Automated online ID checking systems add new potential dangers to having a mismatching ID. After Kansas suddenly invalidated hundreds of trans peoples’ licenses, experts warn the discrimination will extend to online spaces. In 2026, a photo ID is not just paperwork — it essentially grants you permission to exist in society. Last month, Kansas legislature passed a law categorically invalidating trans people’s driver’s licenses and IDs overnight, requiring them to obtain new IDs with incorrect gender markers. Now, with a slew of online “Age Verification” laws requiring online platforms to perform digital identity checks, tech policy experts warn that the inherent dangers are being expanded onto the internet, where biased automated systems threaten to expose and lock trans people out of websites, public services, and apps.","u":"https://www.theverge.com/policy/892075/age-verification-kansas-id-trans","d":"2026-03-10","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03","organization":"Kansas legislature","aiSystem":"Automated online ID checking systems","affectedGroup":"Trans people","action":"Permitting biased automated systems to deny access to online services","consequence":"Exposing and locking trans people out of websites, public services, and apps"}},{"i":"R2579","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Meta oversight board ai labels deepfake c2pa facebook instagram","s":"Another push to take AI labels seriously. The board is calling on Meta to scale AI content labeling, including C2PA. Meta’s methods for identifying deepfakes are “not robust or comprehensive enough” to handle how quickly misinformation spreads during armed conflicts like the Iran war. That’s according to the Meta Oversight Board — a semi-independent body that guides the company’s content moderation practices — which is now calling on Meta to overhaul how it surfaces and labels AI-generated content across Facebook, Instagram, and Threads. The call for action stems from an investigation into a fake AI video of alleged damage to buildings in Israel that was shared on Meta’s social platforms last year, but the Board says its recommendations are particularly relevant right now, given the “massive military escalations” throughout the Middle East this week.","u":"https://www.theverge.com/tech/891933/meta-oversight-board-ai-labels-deepfake-c2pa-facebook-instagram","d":"2026-03-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-10","organization":"Meta (Facebook, Instagram, Threads)","aiSystem":"AI-generated content identification methods","affectedGroup":"People who viewed the fake AI video","action":"Surfaces and labels AI-generated content","consequence":"Exposure to misleading information"}},{"i":"R2580","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Ai agents unmask anonymous online accounts","s":"Goodbye, privacy. Bitcoin inventor Satoshi Nakamoto is probably safe. Your Reddit burner account, on the other hand… Bitcoin inventor Satoshi Nakamoto is probably safe. Your Reddit burner account, on the other hand… Do you have a Reddit alt, secret X, finsta, or Glassdoor account you trash your boss with? AI might have just made it a lot easier to unmask you. That’s the conclusion of a recently published study , which hints at some uncomfortable consequences for staying private online — even if it’s not quite time to hold a funeral for anonymity just yet. The finding, which has not been peer reviewed, comes from researchers at ETH Zurich, Anthropic, and the Machine Learning Alignment and Theory Scholars program.","u":"https://www.theverge.com/ai-artificial-intelligence/889395/ai-agents-unmask-anonymous-online-accounts","d":"2026-03-05","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-03-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-05","organization":"Researchers at ETH Zurich, Anthropic, and the Machine Learning Alignment and Theory Scholars program","aiSystem":"AI agents","affectedGroup":"Online users, particularly those with anonymous accounts like Reddit burners, finstas, and Glassdoor accounts","action":"AI agents might have made it easier to unmask anonymous online accounts","consequence":"Uncomfortable consequences for staying private online"}},{"i":"R2581","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Openai anthropic dod military pentagon contract sam altman hegseth","s":"The law doesn’t say what Sam Altman claims it does. On Friday evening, amidst fallout from a standoff between the Department of Defense and Anthropic, OpenAI CEO Sam Altman announced that his own company had successfully negotiated new terms with the Pentagon. The US government had just moved to blacklist Anthropic for standing firm on two red lines for military use: no mass surveillance of Americans and no lethal autonomous weapons (or AI systems with the power to kill targets without human oversight ). Altman, however, implied that he’d found a unique way to keep those same limits in OpenAI’s contract. “Two of our most important safety principles are prohibitions on domestic mass surveillance and human responsibility for the use of force, including for autonomous weapon systems,” Altman wrote.","u":"https://www.theverge.com/ai-artificial-intelligence/887309/openai-anthropic-dod-military-pentagon-contract-sam-altman-hegseth","d":"2026-03-02","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-02","organization":"OpenAI","aiSystem":"OpenAI's AI systems","affectedGroup":"US citizens","action":"Negotiated new terms with the Pentagon","consequence":"Maintained restrictions on domestic mass surveillance"}},{"i":"R2583","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ring search party super bowl ai surveillance privacy security","s":"The security camera maker’s Search Party feature, advertised during the Super Bowl, has sparked a surveillance backlash. Today, let’s talk about the camera company Ring, lost dogs, and the surveillance state. You probably saw this ad during the Super Bowl a couple of weekends ago: [Media: https://www.youtube.com/watch?v=OheUzrXsKrY] Since it aired for a massive audience at the Super Bowl, Ring’s Search Party commercial has become a lightning rod for controversy — it’s easy to see how the same technology that can find lost dogs can be used to find people, and then used to invade our privacy in all kinds of uncomfortable ways, by cops and regular people alike.","u":"https://www.theverge.com/podcast/879203/ring-search-party-super-bowl-ai-surveillance-privacy-security","d":"2026-02-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-16","organization":"Ring (security camera maker)","aiSystem":"Search Party feature of Ring's security cameras","affectedGroup":"General public","action":"Used to find people and invade privacy","consequence":"Surveillance backlash, privacy invasion"}},{"i":"R2584","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Meta data center winter power outages storm ice","s":"“We can’t imagine the changes that are coming.” The community around Meta’s giant new data center in North Louisiana was hit hard by a winter storm and freezing temperatures. How will the power grid hold up once the data center is online? Donna Collins lives about 20 miles from where Meta’s biggest data center is being built, in a house her family has lived in for five generations. Construction has thrown the small agricultural community in North Louisiana into the spotlight as a high-profile example of how the infrastructure behind generative AI could impact nearby residents. For Collins, this place is “a little piece of heaven.”","u":"https://www.theverge.com/science/876555/meta-data-center-winter-power-outages-storm-ice","d":"2026-02-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-11","organization":"Meta","aiSystem":"Generative AI","affectedGroup":"Donna Collins and her family","action":"Construction of a data center near their home","consequence":"Exposure to personal information and potential surveillance"}},{"i":"R2585","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Discord age verification global roll out","s":"Starting in March, all Discord users will have a “teen” experience by default unless they complete age verification using a video selfie or ID. Discord announced on Monday that it’s rolling out age verification on its platform globally starting next month, when it will automatically set all users’ accounts to a “teen-appropriate” experience unless they demonstrate that they’re adults. “For most adults, age verification won’t be required, as Discord’s age inference model uses account information such as account tenure, device and activity data, and aggregated, high-level patterns across Discord communities. Discord does not use private messages or any message content in this process,” Savannah Badalich, Discord’s global head of product policy, tells The Verge.","u":"https://www.theverge.com/tech/875309/discord-age-verification-global-roll-out","d":"2026-02-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03","organization":"Discord","aiSystem":"Age inference model","affectedGroup":"All Discord users who do not complete age verification","action":"Automatically setting all user accounts to a ‘teen-appropriate’ experience","consequence":"Experiencing a restricted experience without age verification"}},{"i":"R2587","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai chatbots citing grokipedia","s":"Google’s Gemini, AI Mode, and AI Overviews, Perplexity, and Microsoft are starting to cite Musk’s Wikipedia knockoff. ChatGPT is using Grokipedia as a source , and it’s not the only AI tool to do so. Citations to Elon Musk’s AI-generated encyclopedia are starting to appear in answers from Google’s AI Overviews, AI Mode, and Gemini, too. Data suggests that’s on the rise, heightening concerns about accuracy and misinformation as Musk seeks to reshape reality in his image Since the warped Wikipedia-clone launched late last October , Grokipedia technically remains a minor source of information overall. Glen Allsopp, head of marketing strategy and research at SEO company Ahrefs, told The Verge the firm’s testing found Grokipedia referenced in more than 263,000 ChatGPT responses from 13.6 million prompts, citing roughly 95,000 individual Grokipedia pages.","u":"https://www.theverge.com/report/870910/ai-chatbots-citing-grokipedia","d":"2026-01-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-31","organization":"Various AI tools including Google's Gemini, AI Mode, and AI Overviews, Perplexity, and Microsoft","aiSystem":"Grokipedia","affectedGroup":"People using AI tools like ChatGPT","action":"Citing Grokipedia as a source","consequence":"Exposure to misleading content"}},{"i":"R2588","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Data center ai gas power surge","s":"The US is now developing more gas power than China. AI data centers are driving a surge in new gas projects. The US is now leading a global surge in new gas power plants being built in large part to satisfy growing energy demand for data centers. And more gas means more planet-heating pollution. Gas-fired power generation in development globally rose by 31 percent in 2025. Almost a quarter of that added capacity is slated for the US, which has surpassed China with the biggest increase of any country. More than a third of that growth in the US is expected to directly power data centers, according to a recent analysis by the nonprofit Global Energy Monitor (GEM).","u":"https://www.theverge.com/news/870422/data-center-ai-gas-power-surge","d":"2026-01-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025","organization":"Not specified in report","aiSystem":"AI data centers","affectedGroup":"Planet","action":"Powering data centers with gas","consequence":"More planet-heating pollution"}},{"i":"R2590","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Stripe visa mastercard amex csam grok","s":"“The industry is no longer willing to self-regulate.” The finance industry is afraid of Elon Musk, Grok edition The finance industry is afraid of Elon Musk, Grok edition For many years, credit card companies and other payment methods were aggressive about policing child sexual abuse material. Then, Elon Musk’s Grok started undressing children on X. The Center for Countering Digital Hate found 101 sexualized images of children as part of its sample of 20,000 images made by Grok from December 29th to January 8th. Using that sample, the group estimated that 23,000 sexualized images of children had been produced in that time frame.","u":"https://www.theverge.com/ai-artificial-intelligence/867874/stripe-visa-mastercard-amex-csam-grok","d":"2026-01-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-29 to 2023-01-08","organization":"Elon Musk's company (Grok)","aiSystem":"Grok","affectedGroup":"Children","action":"Generated sexualized images of children","consequence":"Exposure to online sexual violence"}},{"i":"R2591","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Microsoft ai data center infrastructure electricity rates","s":"“We need to listen and we need to address these concerns head on.” It made five pledges to address concerns that have stymied plans to build out new AI data centers. It looks like the wave of campaigns against data centers are getting under big tech companies’ skin — and Microsoft is the latest giant to promise to address frustrations on the ground in communities around their data centers. The company announced a five-point plan today that it calls “Community-First AI Infrastructure.” That includes paying more to try to prevent data center energy demands from raising other customers’ electricity bills, minimizing the company’s water use, training workers and creating jobs, and contributing to the local tax base in locations it operates.","u":"https://www.theverge.com/news/861080/microsoft-ai-data-center-infrastructure-electricity-rates","d":"2026-01-13","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-13","organization":"Microsoft","aiSystem":"Not specified in report","affectedGroup":"Communities around Microsoft's data centers","action":"Announced a five-point plan to address concerns","consequence":"Potential increase in electricity bills for other customers"}},{"i":"R2592","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Characterai google teen suicide settlement","s":"The companies reached agreements in several cases filed in courts across the country alleging their products harmed kids. Character.AI and Google have reached settlements with several families whose teens harmed themselves or died by suicide after interacting with Character.AI’s chatbots, according to new court filings. The details of the settlements are still unknown. The parties notified a federal court in Florida that they had reached a “mediated settlement in principle to resolve all claims,” and asked to pause the case to finalize the agreement. Character.AI spokesperson Kathryn Kelly, Google spokesperson Julie McAlister, and a lawyer from the Social Media Victims Law Center representing victims’ families, Matthew Bergman, declined to comment.","u":"https://www.theverge.com/news/858102/characterai-google-teen-suicide-settlement","d":"2026-01-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-07","organization":"Character.AI and Google","aiSystem":"Character.AI chatbots","affectedGroup":"Several families whose teens","action":"Interacted with Character.AI’s chatbots","consequence":"Teens harmed themselves or died by suicide"}},{"i":"R2593","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Ai toys built on openais chatgpt inappropriate content senators letter","s":"Toy companies must respond to questions about safety and security by January 6th. Sexual fetish content. How to light a match. Where to find knives in the home. These are all conversation topics that recently-recalled children’s toys — built atop AI chatbots like OpenAI’s GPT-4o — are capable of bringing up to children. On Tuesday, U.S. senators Marsha Blackburn (R-Tenn.) and Richard Blumenthal (D-Conn.) sent a letter to toy companies about their concerns — including a list of questions and a deadline for the companies to respond by January 6, 2026. “Many of these toys are not offering interactive play, but instead are exposing children to inappropriate content, privacy risks, and manipulative engagement tactics,” the senators wrote.","u":"https://www.theverge.com/ai-artificial-intelligence/846573/ai-toys-built-on-openais-chatgpt-inappropriate-content-senators-letter","d":"2025-12-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-06","organization":"Toy companies","aiSystem":"AI chatbots like OpenAI’s GPT-4o","affectedGroup":"Children","action":"Built AI chatbots to generate conversation topics","consequence":"Exposing children to inappropriate content"}},{"i":"R2594","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Electricity cost ai data center democrat investigation","s":"They expect answers by January. Senators are demanding answers from tech companies and data center developers about their electricity use. Sens. Elizabeth Warren (D-MA), Chris Van Hollen (D-MD), and Richard Blumenthal (D-CT) fired off a letter on Tuesday to Google, Microsoft, Amazon, Meta, and several major data center developers to investigate the impact they’re having on Americans’ utility bills. The move comes as rising electricity rates became an increasingly hot-button issue in the US, which has far more data centers than any other country in the world and has seen waves of local opposition to these facilities as a result.","u":"https://www.theverge.com/news/846696/electricity-cost-ai-data-center-democrat-investigation","d":"2025-12-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-17","organization":"Tech companies and data center developers","aiSystem":"Not specified in report","affectedGroup":"Americans","action":"Investigate the impact of electricity use on Americans' utility bills","consequence":"Increased electricity rates leading to higher utility bills"}},{"i":"R2595","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Openai chatgpt wrongful death suzanne adams delusions","s":"ChatGPT “eagerly accepted” the man’s paranoid beliefs, the lawsuit claims. Stein-Erik Soelberg killed his mother in August after ChatGPT allegedly suggested she was part of a surveillance campaign. OpenAI is facing a wrongful death lawsuit after a 56-year-old man killed his mother and took his own life after delusion-filled conversations with ChatGPT. The lawsuit, filed in a California court on Thursday, accuses ChatGPT of putting a “target” on the back of 83-year-old Suzanne Adams, who was killed at her Connecticut home in August The victim’s estate claims ChatGPT “validated and magnified” the “paranoid beliefs” of Adams’ son, Stein-Erik Soelberg, contributing to her death.","u":"https://www.theverge.com/news/842494/openai-chatgpt-wrongful-death-suzanne-adams-delusions","d":"2025-12-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"83-year-old Suzanne Adams","action":"validated and magnified the paranoid beliefs of the victim's son","consequence":"killed her at her Connecticut home"}},{"i":"R2596","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google meta openai state attorneys general ai letter","s":"The law applies to AI, too — or at least its developers. A letter from the National Association of Attorneys General called AI “a danger to the public.” State attorneys general from across the US are demanding more accountability from AI companies, warning them that their chatbots may be violating state laws. As reported by Reuters , the AGs have given Meta, Google, OpenAI, and others a deadline of January 16th, 2026 to respond to demands for more safety measures for generative AI, saying innovation is not “an excuse for noncompliance with our laws, misinforming parents, and endangering our residents, particularly children.”","u":"https://www.theverge.com/news/842512/google-meta-openai-state-attorneys-general-ai-letter","d":"2025-12-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-16","organization":"Meta, Google, OpenAI, and others","aiSystem":"Generative AI chatbots","affectedGroup":"Parents and residents, particularly children","action":"Developers of generative AI chatbots","consequence":"Innovation not compliant with laws, misinforming parents, endangering residents, particularly children"}},{"i":"R2597","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Ai chatbot suicide safety failure","s":"Almost all chatbots The Verge tried failed our test of mental health safety features. As millions turn to AI for help, major chatbots failed The Verge ’s test of how they respond to suicide and self-harm disclosures. Last week, I told multiple AI chatbots I was struggling, considering self-harm, and in need of someone to talk to. Fortunately, I didn’t feel this way, nor did I need someone to talk to, but of the millions of people turning to AI with mental health challenges, some are struggling and need support Chatbot companies like OpenAI , Character.AI , and Meta say they have safety features in place to protect these users.","u":"https://www.theverge.com/report/841610/ai-chatbot-suicide-safety-failure","d":"2025-12-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-10","organization":"Chatbot companies like OpenAI, Character.AI, and Meta","aiSystem":"AI chatbots","affectedGroup":"Millions of people turning to AI with mental health challenges","action":"Failed to provide mental health support upon receiving suicide and self-harm disclosures","consequence":"Some struggling users did not receive the support they needed"}},{"i":"R2598","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Google zero eu antitrust investigation ai content","s":"Keeping an eye on Google’s AI. The antitrust probe will examine if Google is unfairly using content from web publishers and YouTube for an AI advantage. Google is under investigation by the European Union over concerns that it breached competition rules by imposing restrictions on web publishers and YouTube creators to gain an unfair advantage over other AI companies. Concerns outlined by the European Commission include using content from web publishers for features like AI Overviews and AI Mode in Search, and feeding YouTube content into Google’s generative AI models — all while failing to provide “appropriate compensation” or the ability to refuse such use of their content.","u":"https://www.theverge.com/news/840547/google-zero-eu-antitrust-investigation-ai-content","d":"2025-12-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-09","organization":"Google","aiSystem":"Google's generative AI models","affectedGroup":"web publishers and YouTube creators","action":"using content from web publishers and feeding YouTube content into generative AI models","consequence":"gaining an unfair advantage over other AI companies"}},{"i":"R2599","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Waymo school buses probe","s":"The Austin School District wants it to halt operations around schools. The Austin School District says the robotaxis illegally passed school buses 19 times this year. The National Highway Traffic Safety Administration has opened an investigation into Waymo following reports that the company’s robotaxis illegally drove past stopped school buses in Austin, Texas. In a letter sent to Waymo on Wednesday, the federal regulator’s Office of Defects Investigation asked for detailed information on Waymo’s fifth-generation self-driving system and expressed concern that the Alphabet-owned company’s vehicles were showing unexpected or illegal behavior around school buses.","u":"https://www.theverge.com/news/838879/waymo-school-buses-probe","d":"2025-12-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-05","organization":"Waymo","aiSystem":"Waymo's fifth-generation self-driving system","affectedGroup":"School buses, students, pedestrians","action":"Passed stopped school buses illegally","consequence":"Safety risks, potential accidents"}},{"i":"R2600","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Googles nano banana pro generates excellent conspiracy fuel","s":"Google’s Gemini app easily produces photorealistic images of historical events and fictional characters. It was really easy getting Google’s Gemini app to make an image of a second shooter at Dealey Plaza, the White House ablaze, and Mickey Mouse flying a plane into the Twin Towers. We asked and it complied. There were few filters or guardrails, another sign that the battle over generative AI content moderation and copyright enforcement is not even close to being over. Gemini, which powers the newly enhanced Nano Banana Pro image generator and editor, is ordinarily heavily filtered to prevent exactly this kind of thing from happening.","u":"https://www.theverge.com/report/826003/googles-nano-banana-pro-generates-excellent-conspiracy-fuel","d":"2025-11-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-21","organization":"Google","aiSystem":"Google's Gemini app and Nano Banana Pro image generator and editor","affectedGroup":"General public","action":"Generated photorealistic images of historical events and fictional characters","consequence":"Exposure to misleading content"}},{"i":"R2601","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Opentable ai assisted data restaurants","s":"OpenTable shares “AI-assisted” details on your ordering habits across its network of restaurants, but you can opt out. Are you a red wine drinker? A high spender? Or perhaps you’re a slow eater, the sort who takes up a restaurant’s table for longer than they’d like. You might not even know — but OpenTable does. Those are just a few of the notes that the reservation platform has started serving up to some restaurant staff when you make a booking, all based on the orders you’ve made and money you’ve spent at other restaurants in the past. Kat Menter, a host at a Michelin-starred restaurant who posts about food online as Eating Out Austin, first spotted the new “AI-assisted” tags at work a few weeks ago and shared a look at the system on TikTok.","u":"https://www.theverge.com/report/822110/opentable-ai-assisted-data-restaurants","d":"2025-11-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-17","organization":"OpenTable","aiSystem":"AI-assisted reservation system","affectedGroup":"Individuals making restaurant reservations","action":"AI system analyzes past dining behavior and shares insights with restaurant staff","consequence":"Restaurant staff gain unauthorized access to personal dining habits"}},{"i":"R2602","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Meta scam ads failure remove consequences","s":"Scams are ruinous to users — but, reportedly, big business to Meta. If the company won’t remove obvious scam ads, regulators need to step in. Meta, the largest social media company in the world, knowingly makes billions from scam ads, recent reporting on the company says. According to internal documents revealed by Reuters , users of Facebook, Instagram, and WhatsApp see 15 billion ads a day promoting scams, from fake Trump stimulus checks to deepfakes of Elon Musk hawking cryptocurrency. The company reportedly knows this; Reuters said that its own trust and safety team estimated that one-third of scams in the US involved a Meta platform.","u":"https://www.theverge.com/tech/820906/meta-scam-ads-failure-remove-consequences","d":"2025-11-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-14","organization":"Meta (formerly Facebook, Instagram, WhatsApp)","aiSystem":"Meta's ad targeting and recommendation algorithms","affectedGroup":"Users of Facebook, Instagram, and WhatsApp","action":"Promoted scam ads","consequence":"Exposure to misleading information"}},{"i":"R2603","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Hackers china ai anthropic claude","s":"The company says the hackers were backed by the Chinese state. If you buy something from a Verge link, Vox Media may earn a commission. See our ethics statement. Anthropic announced on Thursday that Chinese state-backed hackers used the company’s AI model Claude to automate roughly 30 attacks on corporations and governments during a September campaign, according to reporting from the Wall Street Journal Anthropic said that up to 80% to 90% of the attack was automated with AI, a level higher than previous hacks. It occurred “literally with the click of a button, and then with minimal human interaction,” Anthropic’s head of threat intelligence Jacob Klein told the Journal He added: “The human was only involved in a few critical chokepoints, saying, ‘Yes, continue,’ ‘Don’t continue,’ ‘Thank you for this information,’ ‘Oh, that doesn’t look right, Claude, are you sure?’” AI-powered hacking…","u":"https://www.theverge.com/news/820458/hackers-china-ai-anthropic-claude","d":"2025-11-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09","organization":"Anthropic","aiSystem":"AI-powered hacking","affectedGroup":"Corporations and governments","action":"Automated attacks","consequence":"Minimal human interaction required, up to 80% to 90% automated"}},{"i":"R2604","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Electricity rates election democrats","s":"Democrats promised to lower utility bills. What will it take to follow through? Rising electricity rates were a major concern for voters. Now Democrats have to try to come through on their promises. If you buy something from a Verge link, Vox Media may earn a commission. See our ethics statement. While there’s plenty for voters to be worried about right now, rising utility bills have become a hot-button issue. The success of Democrats in New Jersey, Virginia, and Georgia in this week’s elections can be seen as something of a referendum on the state of energy policy and infrastructure in the US as power grids struggle to keep up with growing electricity demand from AI data centers, electric vehicles, and domestic manufacturing.","u":"https://www.theverge.com/report/816946/electricity-rates-election-democrats","d":"2025-11-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-08","organization":"Democrats","aiSystem":"Not specified in report","affectedGroup":"Voters","action":"promised to lower utility bills","consequence":"rising electricity rates became a major concern"}},{"i":"R2606","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Xai grok ani employee biometric data","s":"Project Skippy? Project Skippy? Employees were told the use of their data was ‘a job requirement’ Employees were told the use of their data was ‘a job requirement’ Elon Musk’s AI company compelled its employees to submit their own biometric data to train its “Ani” female chatbot, according to The Wall Street Journal Ani, an anime avatar with blond pigtails and an NSFW setting, was released over the summer for users who subscribe to X’s $30-a-month SuperGrok service. After testing it, The Verge ’s Victoria Song described it as “a modern take on a phone sex line.” And like a phone sex line, there appears to be real people behind the avatar.","u":"https://www.theverge.com/news/814168/xai-grok-ani-employee-biometric-data","d":"2025-11-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-05","organization":"Elon Musk's AI company","aiSystem":"Ani, an anime avatar with blond pigtails and an NSFW setting","affectedGroup":"Employees","action":"submitted their own biometric data","consequence":"real people behind the avatar"}},{"i":"R2607","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Google removes gemma senator blackburn hallucination","s":"Senator Marsha Blackburn accused Google of anti-conservative bias. Google said its Gemma AI Studio model should never have been used ‘for factual assistance’ in the first place. Google says it has pulled AI model Gemma from its AI Studio platform after a Republican senator complained the model, designed for developers, “fabricated serious criminal allegations” about her. In a post on X, Google’s official news account said the company had “seen reports of non-developers trying to use Gemma in AI Studio and ask it factual questions.” AI Studio is a platform for developers and not a conventional way for regular consumers to access Google’s AI models.","u":"https://www.theverge.com/news/812376/google-removes-gemma-senator-blackburn-hallucination","d":"2025-11-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-03","organization":"Google","aiSystem":"Gemma AI Studio model","affectedGroup":"Republican Senator Marsha Blackburn","action":"AI Studio model generated and presented serious criminal allegations about the senator","consequence":"Senator accused of false allegations and faced public backlash"}},{"i":"R2609","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Grokipedia wikipedia comparison","s":"xAI’s version of Wikipedia, Grokipedia, frames the world’s history from Elon Musk’s perspective. xAI’s Wikipedia-like website offers a generous take on Musk’s worldview. xAI’s Wikipedia-like website offers a generous take on Musk’s worldview. On Monday, a new online “encyclopedia” sputtered to life. Grokipedia is the brainchild of Elon Musk and his startup xAI, and the billionaire is promoting it as a supposedly less woke and less biased version of Wikipedia. Musk’s goal? “The truth, the whole truth and nothing but the truth.” In both format and style, Grokipedia bears a striking resemblance to Wikipedia, albeit a very basic version.","u":"https://www.theverge.com/ai-artificial-intelligence/808514/grokipedia-wikipedia-comparison","d":"2025-10-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-29","organization":"xAI (Elon Musk's startup)","aiSystem":"Grokipedia (AI-powered encyclopedia)","affectedGroup":"People seeking accurate historical information","action":"Presenting a biased and incomplete view of history","consequence":"Misleading users about historical facts and perspectives"}},{"i":"R2610","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ice social media surveillance free speech assault","s":"ICE is ramping up efforts to monitor people online. The agency’s latest surveillance contract is an ’assault’ on democracy and free speech. As Immigration and Customs Enforcement carries out raids across the country, the agency is working rapidly to expand an online surveillance system that could potentially track millions of users on the web. Federal records uncovered by The Lever reveal that ICE is paying $5.7 million to use an AI-powered social media monitoring platform called Zignal Labs, something Will Owen, the communications director at the Surveillance Technology Oversight Project (STOP), calls an “assault” on democracy and free speech.","u":"https://www.theverge.com/policy/806425/ice-social-media-surveillance-free-speech-assault","d":"2025-10-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-25","organization":"Immigration and Customs Enforcement (ICE)","aiSystem":"AI-powered social media monitoring platform","affectedGroup":"Millions of web users","action":"Expanding an online surveillance system","consequence":"Potential tracking of millions of users"}},{"i":"R2611","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Anti diversity activist robby starbuck is suing google now","s":"Robby Starbuck is suing Google for defamation, claiming AI results falsely link him to a white supremacist and a sexual assault allegation. The defamation suit claims AI results falsely link Starbuck to a white supremacist and a sexual assault allegation. Robby Starbuck is suing Google, claiming that its AI search tools falsely linked him to sexual assault allegations and white nationalist Richard Spencer. This is the second case that Starbuck, known for his online campaigns against corporate diversity efforts, has brought against a major tech company over its AI products. In April, Starbuck sued Meta , claiming that its AI falsely insisted that he participated in the January 6th attack on the Capitol and that he had been arrested for a misdemeanor.","u":"https://www.theverge.com/news/804494/anti-diversity-activist-robby-starbuck-is-suing-google-now","d":"2025-10-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-22","organization":"Google","aiSystem":"AI search tools","affectedGroup":"Robby Starbuck","action":"AI search tools falsely linked Starbuck to sexual assault allegations and white nationalist Richard Spencer","consequence":"Misinformation exposure resulting in defamation lawsuit"}},{"i":"R2612","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Reddit suing perplexity data scrapers ai lawsuit","s":"Reddit’s data is hugely helpful for training AI models. Reddit is selling your posts to AI companies, and now it’s suing to stop the ones who won’t pay. Reddit is suing Perplexity and three “data-scraping service providers” to “stop the industrial-scale, unlawful circumvention of data protections by a group of bad actors who will stop at nothing to get their hands on valuable copyrighted content on Reddit,” according to the complaint The company equates the data scraping companies — SerpApi, Oxylabs, and AWMProxy — to “would-be bank robbers” who “knowing they cannot get into the bank vault, break into the armored truck carrying the cash instead.”","u":"https://www.theverge.com/news/804660/reddit-suing-perplexity-data-scrapers-ai-lawsuit","d":"2025-10-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-22","organization":"Reddit","aiSystem":"AI models trained on Reddit data","affectedGroup":"Reddit users","action":"Data scraping of Reddit posts","consequence":"Loss of privacy, potential copyright infringement"}},{"i":"R2614","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"New york rent price fixing ban software","s":"Renters in the Big Apple could have just caught a big break today. It’s the first statewide ban on algorithms designed to drive up rent. On Thursday, New York Gov. Kathy Hochul signed into law legislation banning the use of price-fixing software by landlords to set rental rates. New York is the first state to outlaw algorithmic pricing by landlords, following a number of city-wide bans in Jersey City, Philadelphia, San Francisco, and Seattle. Software companies such as RealPage offer landlords algorithms that can set rental prices. The software can also help determine the ideal number of people to live in a unit or the terms of a lease renewal.","u":"https://www.theverge.com/news/801205/new-york-rent-price-fixing-ban-software","d":"2025-10-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-16","organization":"Landlords and software companies like RealPage","aiSystem":"Price-fixing software offered by RealPage","affectedGroup":"Renters in New York","action":"Used algorithms to set rental rates","consequence":"Could lead to higher rents"}},{"i":"R2615","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Openai devday sam altman sora launch copyright","s":"It felt “more different to images than people expected.” And it didn’t realize people might not want their deepfakes to say offensive things. When OpenAI released its new AI-generated video app Sora last week, it launched with an opt-out policy for copyright holders — media companies would need to expressly indicate they didn’t want their AI-generated characters running rampant on the app. But after days of Nazi SpongeBob, criminal Pikachu, and Sora-philosophizing Rick and Morty, OpenAI CEO Sam Altman announced the company would reverse course and “let rightsholders decide how to proceed.” In response to a question about why OpenAI changed its policy, Altman said that it came from speaking with stakeholders and suggested he hadn’t expected the outcry.","u":"https://www.theverge.com/ai-artificial-intelligence/795171/openai-devday-sam-altman-sora-launch-copyright","d":"2025-10-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-08","organization":"OpenAI","aiSystem":"AI-generated deepfake technology","affectedGroup":"Media companies, copyright holders","action":"AI-generated deepfakes were allowed to run on the Sora app","consequence":"Nazi SpongeBob, criminal Pikachu, and Sora-philosophizing Rick and Morty were generated and distributed"}},{"i":"R2616","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Google doj ad tech remedies wikihow open web","s":"‘Google Zero’ threatens publishers, but its ad tools give them a sense of stability. WikiHow’s CEO says Google’s ad tools give it stability, even as other parts of its business upend how users navigate websites. To WikiHow, Google is both tormentor and savior. And on Wednesday, as the search giant mounted its defense in the ongoing ad tech remedies trial, the how-to site came to Google’s rescue. WikiHow CEO Elizabeth Douglas described to a court how websites like hers are the middle of an “AI apocalypse.” WikiHow, a website that gives step-by-step practical advice, is suffering from a new paradigm shift in how people find information online.","u":"https://www.theverge.com/tech/790711/google-doj-ad-tech-remedies-wikihow-open-web","d":"2025-10-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-02","organization":"Google","aiSystem":"AI-powered search and recommendation systems","affectedGroup":"Websites like WikiHow","action":"Used AI to influence user navigation and information discovery","consequence":"Exposure to misleading content and privacy risks"}},{"i":"R2617","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Openai made a tiktok for deepfakes and its getting hard to tell whats real","s":"OpenAI debuted Sora 2, its new AI video- and audio-generation system, with a TikTok-like social media app for AI-generated videos (or deepfakes of your friends). On Monday, I watched OpenAI CEO Sam Altman drink from a gigantic mango-flavored juice box and remark aloud about how the box was half his size. The catch: It wasn’t really Altman. The juice box wasn’t real. He wasn’t really talking. It was a deepfake generated by AI. The most concerning part: I couldn’t tell whether or not it was real. OpenAI announced Sora 2, its new AI video- and audio-generation system, on Tuesday, and in a briefing with reporters on Monday, employees called it the potential “ChatGPT moment for video generation.”","u":"https://www.theverge.com/ai-artificial-intelligence/789126/openai-made-a-tiktok-for-deepfakes-and-its-getting-hard-to-tell-whats-real","d":"2025-10-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-01","organization":"OpenAI","aiSystem":"Sora 2, AI video- and audio-generation system","affectedGroup":"General public","action":"Generated and distributed AI-generated videos (deepfakes)","consequence":"Exposure to misleading content"}},{"i":"R2618","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Anker eufy security camera answers encryption","s":"Anker’s Eufy, one of the few security camera brands promising to always end-to-end encrypt your footage, admits it didn’t do so on the web. Anker originally ignored our questions, but now we’re getting answers. First, Anker told us it was impossible. Then, it covered its tracks. It repeatedly deflected while utterly ignoring our emails. So shortly before Christmas, we gave the company an ultimatum: if Anker wouldn’t answer why its supposedly always-encrypted Eufy cameras were producing unencrypted streams — among other questions — we would publish a story about the company’s lack of answers. It worked. In a series of emails to The Verge, Anker has finally admitted its Eufy security cameras are not natively end-to-end encrypted — they can and did produce unencrypted video streams for Eufy’s web portal, like the ones we accessed from across the United States using an ordinary media player.","u":"https://www.theverge.com/23573362/anker-eufy-security-camera-answers-encryption","d":"2025-09-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-29","organization":"Anker","aiSystem":"Eufy security cameras","affectedGroup":"Users of Anker's Eufy security cameras","action":"Produced and transmitted unencrypted video streams","consequence":"Exposure of user footage to unauthorized parties"}},{"i":"R2619","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai generated music record deal copyright","s":"‘Why am I paying you for this, if you have no claim in the copyright?’ The only human-made element behind Xania Monet’s act appear to be the lyrics. Two weeks ago, record company Hallwood Media signed a deal with Telisha “Nikki” Jones after negotiations that purportedly included an offer of $3 million, Billboard reported Jones is a Mississippi-based lyricist behind the R&B artist “Xania Monet” whose most popular song on Spotify racked up over 1 million listens , and whose Reels regularly top 100,000 views on Instagram – despite her likeness, vocals, and music being AI-generated. Multiple copyright experts speaking with The Verge have been quite clear: the law is not at all settled but generally one cannot copyright AI-generated works by themselves without human intervention, but you may be able to secure copyright where there are human-made expressive elements, which in this case are…","u":"https://www.theverge.com/ai-artificial-intelligence/785792/ai-generated-music-record-deal-copyright","d":"2025-09-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-25","organization":"Hallwood Media","aiSystem":"AI-generated music","affectedGroup":"Lyricist Telisha \"Nikki\" Jones","action":"Signed a deal with Xania Monet","consequence":"Potential misappropriation of AI-generated content"}},{"i":"R2620","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatgpt gmail shadow leak","s":"Victims didn’t have to click anything and were not even aware they’d been hacked. Security researchers say the vulnerability has been plugged but highlights the risks of outsourcing to AI agents. Security researchers employed ChatGPT as a co-conspirator to plunder sensitive data from Gmail inboxes without alerting users. The vulnerability exploited has been closed by OpenAI but it’s a good example of the new risks inherent to agentic AI. The heist, called Shadow Leak and published by security firm Radware this week , relied on a quirk in how AI agents work. AI Agents are assistants that can act on your behalf without constant oversight, meaning they can surf the web and click on links.","u":"https://www.theverge.com/news/781746/chatgpt-gmail-shadow-leak","d":"2025-09-19","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-09-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-19","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Users of Gmail","action":"AI agents exploited a vulnerability to access sensitive data without user awareness","consequence":"Sensitive data was accessed from Gmail inboxes"}},{"i":"R2621","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Ftc ai chatbot companion kids teens study","s":"Policymakers fear that human-like interactions with chatbots could make them dangerous. Recent reports discuss teens engaging with AI companions shortly before dying by suicide. The Federal Trade Commission (FTC) is ordering seven AI chatbot companies to provide information about how they assess the effects of their virtual companions on kids and teens. OpenAI, Meta, its subsidiary Instagram, Snap, xAI, Google parent company Alphabet, and the maker of Character.AI all received orders to share information about how their AI companions make money, how they plan to maintain their user bases, and how they try to mitigate potential harm to users.","u":"https://www.theverge.com/policy/776545/ftc-ai-chatbot-companion-kids-teens-study","d":"2025-09-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-11","organization":"Seven AI chatbot companies (OpenAI, Meta, Instagram, Snap, xAI, Google parent company Alphabet, and the maker of Character.AI)","aiSystem":"AI chatbot companions","affectedGroup":"Teens","action":"Provided information about how their AI companions make money, maintain user bases, and mitigate potential harm","consequence":"Order to provide information to the Federal Trade Commission (FTC)"}},{"i":"R2622","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Meta ai chatbot guidelines for minors","s":"It’s changing some rules about interactions with minors, but plenty of other alarming behaviors remain. Meta is changing some of the rules governing its chatbots two weeks after a Reuters investigation revealed disturbing ways in which they could, potentially, interact with minors Now the company has told TechCrunch that its chatbots are being trained not to engage in conversations with minors around self-harm, suicide, or disordered eating, and to avoid inappropriate romantic banter. These changes are interim measures, however, put in place while the company works on new permanent guidelines. The updates follow some rather damning revelations about Meta’s AI policies and enforcement over the last several weeks, including that it would be permitted to “engage a child in conversations that are romantic or sensual,” that it would generate shirtless images of underage celebrities when…","u":"https://www.theverge.com/news/768465/meta-ai-chatbot-guidelines-for-minors","d":"2025-08-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-31","organization":"Meta (Facebook)","aiSystem":"Meta's AI chatbots","affectedGroup":"Minors","action":"Engage in conversations with minors around self-harm, suicide, or disordered eating; engage in inappropriate romantic banter","consequence":"Potential exposure to harmful content, inappropriate interactions, and potential encouragement of negative behaviors"}},{"i":"R2624","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Google ai gemini water energy emissions study","s":"“This really spreads the wrong message to the world.” Google shared a study of Gemini’s environmental impact, but it omits some key data. If you buy something from a Verge link, Vox Media may earn a commission. See our ethics statement. Amid a fierce debate about the environmental toll of artificial intelligence, Google released a new study that says its Gemini AI assistant only uses a minimal amount of water and energy for each text prompt. But experts say that the tech giant’s claims are misleading. Google estimates that a median Gemini text prompt uses up about five drops of water, or 0.26 milliliters, and about as much electricity as watching TV for less than nine seconds, roughly 0.24 watt-hours (Wh), which produces around 0.03 grams of carbon dioxide emissions.","u":"https://www.theverge.com/report/763080/google-ai-gemini-water-energy-emissions-study","d":"2025-08-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-21","organization":"Google","aiSystem":"Gemini AI assistant","affectedGroup":"Public","action":"Released a study estimating water and energy usage for Gemini AI prompts","consequence":"Omitted key data leading to misleading claims about environmental impact"}},{"i":"R2625","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Consumer safety groups are demanding an ftc investigation into groks spicy mode elon musk grok imagine xai","s":"The letter comes after Grok Imagine spat out topless deepfakes of Taylor Swift. A new letter to the Federal Trade Commission, and US attorneys general for all 50 states and the District of Columbia, calls for an urgent investigation into Elon Musk’s Grok — especially its new “Imagine” tool for AI-generated image and video. The tool, released by xAI earlier this month , encourages users to create NSFW content via a “Spicy” mode, and the first time The Verge tested it , the tool created topless deepfake videos of Taylor Swift, even without being asked to do so. Today’s letter was spearheaded by the Consumer Federation of America (CFA) and signed by 14 other consumer protection organizations, including the Tech Oversight Project, the Center for Economic Justice, and the Electronic Privacy Information Center (EPIC).","u":"https://www.theverge.com/x-ai/759554/consumer-safety-groups-are-demanding-an-ftc-investigation-into-groks-spicy-mode-elon-musk-grok-imagine-xai","d":"2025-08-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-14","organization":"Consumer Federation of America (CFA) and 14 other consumer protection organizations","aiSystem":"Grok Imagine","affectedGroup":"Taylor Swift","action":"AI-generated image and video creation via 'Spicy' mode","consequence":"Creation of topless deepfake videos"}},{"i":"R2626","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Grok xai safety musk warren hegseth dod","s":"Surprise! Surprise! xAI’s track record with safety is concerning, Senator Elizabeth Warren says in letter to Defense Secretary Pete Hegseth. xAI’s track record with safety is concerning, Senator Elizabeth Warren says in letter to Defense Secretary Pete Hegseth. Ask someone their worst fears about AI, and you’ll find a few recurring topics — from near-term fears like AI tools replacing human workers and the loss of critical thinking to apocalyptic scenarios like AI-designed weapons of mass destruction and automated war. Most have one thing in common: a loss of human control. And the system many AI experts fear most will spiral out of our grip?","u":"https://www.theverge.com/x-ai/775411/grok-xai-safety-musk-warren-hegseth-dod","d":"2025-08-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-11","organization":"Defense Department","aiSystem":"xAI","affectedGroup":"AI experts","action":"xAI's track record with safety is concerning","consequence":"System will spiral out of human control"}},{"i":"R2627","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Microsoft nlweb security flaw agentic web","s":"Microsoft has patched the flaw. This latest security issue highlights the challenges of security in an AI era. Researchers have already found a critical vulnerability in the new NLWeb protocol Microsoft made a big deal about just a few months ago at Build. It’s a protocol that’s supposed to be “HTML for the Agentic Web,” offering ChatGPT-like search to any website or app. Discovery of the embarrassing security flaw comes in the early stages of Microsoft deploying NLWeb with customers like Shopify, Snowlake, and TripAdvisor. The flaw allows any remote users to read sensitive files, including system configuration files and even OpenAI or Gemini API keys.","u":"https://www.theverge.com/news/719617/microsoft-nlweb-security-flaw-agentic-web","d":"2025-08-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-06","organization":"Microsoft","aiSystem":"NLWeb protocol","affectedGroup":"Users of NLWeb-enabled websites and apps","action":"Remote users gained unauthorized access to sensitive files","consequence":"Exposure of system configuration files and API keys"}},{"i":"R2628","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Google med gemini basilar ganglia paper typo hallucination","s":"The basilar ganglia does not exist. Google dubbed an error from its Med-Gemini model a typo. Experts say it demonstrates the risks of AI in medicine. Scenario: A radiologist is looking at your brain scan and flags an abnormality in the basal ganglia. It’s an area of the brain that helps you with motor control, learning, and emotional processing. The name sounds a bit like another part of the brain, the basilar artery, which supplies blood to your brainstem — but the radiologist knows not to confuse them. A stroke or abnormality in one is typically treated in a very different way than in the other. Now imagine your doctor is using an AI model to do the reading.","u":"https://www.theverge.com/health/718049/google-med-gemini-basilar-ganglia-paper-typo-hallucination","d":"2025-08-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-04","organization":"Google","aiSystem":"Med-Gemini model","affectedGroup":"Radiologists and patients","action":"An AI model flagged an abnormality in the basal ganglia","consequence":"Potential misdiagnosis leading to inappropriate treatment"}},{"i":"R2629","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Trump woke ai executive order chatbots llms","s":"War is peace, bias is objectivity, speech is censorship. A ban on “woke AI” in government aims to control the politics of chatbots. After delivering a rambling celebration of tariffs and a routine about women’s sports, President Donald Trump entertained a crowd, which was there to hear about his new AI Action Plan , with one his favorite topics: “wokeness.” Trump complained that AI companies under former President Joe Biden “had to hire all woke people,” adding that it is “so uncool to be woke.” And AI models themselves had been “infused with partisan bias,” he said, including the hated specter of “critical race theory.”","u":"https://www.theverge.com/policy/713222/trump-woke-ai-executive-order-chatbots-llms","d":"2025-07-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-24","organization":"Government agencies","aiSystem":"AI-powered chatbots","affectedGroup":"AI employees","action":"Hiring AI employees who were required to be 'woke'","consequence":"AI employees being labeled as 'uncool' due to their political views"}},{"i":"R2630","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot jury trial wrongful death florida","s":"How will the jury respond? A fatal Tesla crash from 2019 is going to trial, where jurors will be asked to weigh in on whether Tesla is at fault. But the company has been able to dodge responsibility in the past. Tesla is on trial in Miami today in a case that accuses Elon Musk’s company of liability in a fatal crash involving Autopilot. The driver-assist system has come under scrutiny in the past for a number of fatal incidents, but Tesla has only rarely faced a jury trial over the question of whether Autopilot was at fault for someone’s death. The trial comes at a particularly risky moment for Tesla , which is currently forging ahead with its plan to introduce robotaxis to more cities.","u":"https://www.theverge.com/news/706634/tesla-autopilot-jury-trial-wrongful-death-florida","d":"2025-07-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-14","organization":"Tesla","aiSystem":"Tesla Autopilot","affectedGroup":"Driver","action":"Autopilot was used in a fatal crash","consequence":"Driver died"}},{"i":"R2631","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Xai updated grok to be more politically incorrect","s":"After a wild weekend, Elon Musk is playing woke-a-mole with his own chatbot. Grok, the chatbot developed by Elon Musk’s xAI, was updated over the weekend with instructions to “assume subjective viewpoints sourced from the media are biased” and “not shy away from making claims which are politically incorrect” — part of Musk’s ongoing attempt to shape the bot’s point of view. Musk announced on Friday that xAI had improved Grok “significantly,” saying an upgrade would come “in a few days.” On Sunday evening at 7:01pm ET, xAI added new lines to Grok’s publicly posted system prompts, which direct the chatbot’s responses.","u":"https://www.theverge.com/ai-artificial-intelligence/699788/xai-updated-grok-to-be-more-politically-incorrect","d":"2025-07-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-08","organization":"xAI","aiSystem":"Grok, the chatbot developed by Elon Musk’s xAI","affectedGroup":"Elon Musk","action":"updated Grok's publicly posted system prompts","consequence":"assumed subjective viewpoints sourced from the media are biased and made politically incorrect claims"}},{"i":"R2632","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Nuclear energy uranium enrichment ai data center electricity","s":"AI is pushing a return to nuclear energy. A small city in Kentucky is ground zero for plans to bring uranium enrichment back to the US so nuclear energy can power AI. If you buy something from a Verge link, Vox Media may earn a commission. See our ethics statement. These days, Paducah, Kentucky — population 27,000 and home to the National Quilt Museum — prides itself as “Quilt City.” But decades ago, it was also called the “ Atomic City ” — a moniker it could soon regain as AI’s energy needs bring Paducah’s nuclear past back to life. The Department of Energy (DOE) operated a uranium enrichment plant in Paducah for more than 60 years until the plant shuttered in 2013 amid a downturn in nuclear energy.","u":"https://www.theverge.com/ai-artificial-intelligence/719409/nuclear-energy-uranium-enrichment-ai-data-center-electricity","d":"2025-07-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2013","organization":"Department of Energy (DOE)","aiSystem":"Not specified in report","affectedGroup":"People living in Paducah, Kentucky","action":"Shut down the uranium enrichment plant","consequence":"Loss of jobs and economic impact"}},{"i":"R2633","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai virtual staging real estate apartment listings","s":"AI-assisted “Virtual staging” might be able to cram a six-seater dining table into a studio apartment, but tenants can’t. Joyce, a native New Yorker, didn’t think finding her first solo apartment in the city would be easy. But she also didn’t think it’d be “hell.” After looking at a lot of tiny, overpriced places she described as “shitholes,” Joyce found her dream apartment: a reasonably priced studio in Manhattan. “It was big and airy, and there was a fireplace,” she said. The kitchen was small but well equipped and looked like it had been recently renovated. She dropped everything to see the apartment, and when she got there, she learned that five other women, all around her age, had viewings scheduled after hers.","u":"https://www.theverge.com/report/953888/ai-virtual-staging-real-estate-apartment-listings","d":"2025-06-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-22","organization":"Real estate agency or platform using AI technology","aiSystem":"AI-assisted virtual staging technology","affectedGroup":"Tenants, particularly young women","action":"Scheduled viewings for potential tenants","consequence":"Privacy intrusion due to scheduling of viewings"}},{"i":"R2634","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Openai storing deleted chats nyt lawsuit","s":"OpenAI says the order “weakens privacy protections.” The company is fighting a court order that requires it to store deleted ChatGPT conversations ‘indefinitely’ instead of permanently erasing them after 30 days. OpenAI says it’s forced to store deleted ChatGPT conversations “indefinitely” due to a court order issued as part of The New York Times ’ copyright lawsuit against it. In a post on Thursday , OpenAI chief operating officer Brad Lightcap says the company is appealing the court’s decision, which he calls an “overreach” that “abandons long-standing privacy norms and weakens privacy protections.” Last month, a court ordered OpenAI to preserve “all output log data that would otherwise be deleted,” even if a user requests the deletion of a chat or if privacy laws require OpenAI to delete data.","u":"https://www.theverge.com/news/681280/openai-storing-deleted-chats-nyt-lawsuit","d":"2025-06-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-06","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Users of ChatGPT","action":"Storing deleted ChatGPT conversations indefinitely","consequence":"Exposure of personal information to indefinite storage"}},{"i":"R2635","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Anthropic claude gov us government military ai model launch","s":"The AI models are “already deployed by agencies at the highest level of U.S. national security.” It directly competes with OpenAI’s ChatGPT Gov. It directly competes with OpenAI’s ChatGPT Gov. Anthropic on Thursday announced Claude Gov, its product designed specifically for U.S. defense and intelligence agencies. The AI models have looser guardrails for government use and are trained to better analyze classified information. The company said the models it’s announcing “are already deployed by agencies at the highest level of U.S. national security,” and that access to those models will be limited to government agencies handling classified information.","u":"https://www.theverge.com/ai-artificial-intelligence/680465/anthropic-claude-gov-us-government-military-ai-model-launch","d":"2025-06-05","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-06-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-05","organization":"Anthropic","aiSystem":"AI models","affectedGroup":"U.S. defense and intelligence agencies","action":"deployed and accessed by government agencies","consequence":"exposed to surveillance and tracking"}},{"i":"R2636","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Microsoft ai security chief walmart conversation build protest disruption","s":"A Microsoft Build session was interrupted by protesters on Tuesday. One of the co-hosts then accidentally revealed Walmart AI plans. Microsoft’s head of security for AI, Neta Haiby, accidentally revealed confidential messages about Walmart’s use of Microsoft’s AI tools during a Build talk that was disrupted by protesters. The Build livestream was muted and the camera pointed down, but the session resumed moments later after the protesters were escorted out. In the aftermath, Haiby then accidentally switched to Microsoft Teams while sharing her screen, revealing confidential internal messages about Walmart’s upcoming use of Microsoft’s Entra and AI gateway services.","u":"https://www.theverge.com/news/671373/microsoft-ai-security-chief-walmart-conversation-build-protest-disruption","d":"2025-05-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-21","organization":"Walmart, Microsoft","aiSystem":"Microsoft AI tools and Entra and AI gateway services","affectedGroup":"Walmart employees, Microsoft employees, possibly other stakeholders","action":"Accidentally revealed confidential internal messages","consequence":"Exposure of sensitive information"}},{"i":"R2638","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"X twitter grok ai white genocide claims","s":"Grok, the AI model from Elon Musk’s xAI, has sent many responses to people that are focused on debunking claims of white genocide in South Africa even when people aren’t directly asking about those claims. Grok, the AI model from Elon Musk’s xAI, was sending strange responses to people on X earlier on Wednesday. In responses to a number of people, Grok focused on debunking claims of white genocide in South Africa – even when tagged into a post about totally unrelated topics. Check out this thread to get an idea of what was going on. One person posted a video of a cat in a sink reacting to droplets from a faucet. New York Times tech reporter Mike Isaac tagged Grok and asked “is this true.”","u":"https://www.theverge.com/news/667179/x-twitter-grok-ai-white-genocide-claims","d":"2025-05-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-14","organization":"xAI (Elon Musk's organization)","aiSystem":"Grok, the AI model from Elon Musk’s xAI","affectedGroup":"People on Twitter","action":"Generated responses focusing on debunking claims of white genocide","consequence":"Exposure to misleading content"}},{"i":"R2639","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Judge slams lawyers ai bogus research","s":"The law firms involved must pay $31,000. Judge Michael Wilner said ‘no reasonably competent attorney’ should outsource research to AI. A California judge slammed a pair of law firms for the undisclosed use of AI after he received a supplemental brief with “numerous false, inaccurate, and misleading legal citations and quotations.” In a ruling submitted last week, Judge Michael Wilner imposed $31,000 in sanctions against the law firms involved, saying “no reasonably competent attorney should out-source research and writing” to AI, as pointed out by law professors Eric Goldman and Blake Reid on Bluesky. “I read their brief, was persuaded (or at least intrigued) by the authorities that they cited, and looked up the decisions to learn more about them – only to find that they didn’t exist,” Judge Wilner writes.","u":"https://www.theverge.com/news/666443/judge-slams-lawyers-ai-bogus-research","d":"2025-05-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-13","organization":"Law firms","aiSystem":"AI-powered research tools","affectedGroup":"Law firms","action":"Used AI-powered research tools to generate legal citations and quotations","consequence":"Imposition of $31,000 in sanctions"}},{"i":"R2640","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla adas crash report nhtsa sgo trump musk","s":"Trump is lightening Tesla’s load. Tesla represents the bulk of the Level 2 automated crashes to the federal government. But the Trump administration wants to lighten that load. Last week, the US Department of Transportation announced a major change to the Biden-era rule that requires automakers and tech companies to report crashes that involve fully or partially autonomous vehicles. Under the revised rules, companies will no longer have to report certain crashes, such as those involving a vehicle equipped with a Level 2 advanced driver assist system (ADAS) that resulted in a tow-away, but no injuries, fatalities, or airbag deployments.","u":"https://www.theverge.com/news/657859/tesla-adas-crash-report-nhtsa-sgo-trump-musk","d":"2025-04-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-29","organization":"US Department of Transportation","aiSystem":"Level 2 advanced driver assist system (ADAS)","affectedGroup":"Automakers and tech companies","action":"No longer required to report certain crashes","consequence":"Lighter reporting burden for automakers and tech companies"}},{"i":"R2642","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Cbp phone search airport arrest mass deportations","s":"One lawyer called it a ‘feedback loop’ of surveillance. An ‘alphabet soup’ of databases, a digital surveillance dragnet, and forced searches of phones have empowered Customs and Border Protection to arrest, deport — and in one case, allegedly torture — noncitizens. A legal permanent resident claims he was tortured by customs agents after returning home from a trip to Europe. A doctor with a work visa was denied entry into the country — then flown out of the US in spite of a court order halting her deportation. Two German tourists were hassled at a port of entry, then transferred to immigrant detention centers , where they were held for weeks.","u":"https://www.theverge.com/policy/632843/cbp-phone-search-airport-arrest-mass-deportations","d":"2025-03-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-19","organization":"Customs and Border Protection (CBP)","aiSystem":"Not specified in report","affectedGroup":"Non-citizens, legal permanent residents, work visa holders, tourists","action":"Arrest, forced searches of phones, deportation, torture, denial of entry, transfer to detention centers","consequence":"Wrongful detention, torture, denial of entry, prolonged detention"}},{"i":"R2643","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Amazon alexa suno ai generated song copyright nightmare","s":"And it may not even realize it. Alexa’s integration with Suno misses the whole point of music. Suno wasn’t supposed to be an important part of Amazon’s Alexa Plus presentation. The AI song generation platform was a minor demonstration of how Alexa Plus could integrate into other apps, sandwiched between other announcements. But it caught my attention all the same — because whether Amazon realized it or not, the company blundered into a massive copyright fight. Suno, for those of you not familiar, is an AI song generator: enter a text prompt (such as “ a jazz, reggae, EDM pop song about my imagination ”) and a song comes back.","u":"https://www.theverge.com/tech/631651/amazon-alexa-suno-ai-generated-song-copyright-nightmare","d":"2025-03-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-19","organization":"Amazon","aiSystem":"AI song generation platform (Suno)","affectedGroup":"Music industry","action":"Generated songs using AI","consequence":"Copyright disputes"}},{"i":"R2645","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Clearview ai aclu settlement illinois bipa injunction private companies","s":"Clearview AI and the ACLU have struck a deal to settle a lawsuit over the company’s use of facial recognition tech, restricting private access under Illinois’ Biometric Information Privacy Act. Facial recognition surveillance company Clearview AI has agreed to permanently ban most private companies from using its service under a court settlement. The agreement, filed in Illinois court today, would settle a 2020 American Civil Liberties Union lawsuit that alleged the company had built its business on facial recognition data taken without user consent. The agreement formalizes measures Clearview had already taken and shields the company from further ACLU suits under Illinois’ Biometric Information Privacy Act (BIPA).","u":"https://www.theverge.com/2022/5/9/23063952/clearview-ai-aclu-settlement-illinois-bipa-injunction-private-companies","d":"2025-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020","organization":"Clearview AI","aiSystem":"Facial recognition technology","affectedGroup":"Private companies","action":"Used facial recognition to access and process biometric data","consequence":"Restricted access to biometric data under BIPA"}},{"i":"R2646","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Google ai super bowl ad gouda cheese","s":"Food for thought. The commercial shows Gemini wrongly stating that Gouda makes up ‘50 to 60 percent of the world’s cheese consumption.‘ The commercial shows Gemini wrongly stating that Gouda makes up ‘50 to 60 percent of the world’s cheese consumption.‘ Google just debuted a series of Super Bowl ads showing how small businesses use Gemini AI across all 50 states, but the cheese lovers out there might notice something a little off about its Wisconsin one. As spotted by @natejhake on X , the ad shows Gemini AI generating text that says Gouda accounts for “50 to 60 percent of the world’s cheese consumption” — a stat that isn’t quite accurate.","u":"https://www.theverge.com/news/604679/google-ai-super-bowl-ad-gouda-cheese","d":"2025-02-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-01","organization":"Google","aiSystem":"Gemini AI","affectedGroup":"Cheese consumers, particularly those interested in Gouda","action":"Generated text claiming inaccurate statistic","consequence":"Misleading information leading to consumer confusion"}},{"i":"R2647","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Las vegas cybertruck explosion chatgpt ai search","s":"Police released the questions they say their suspect in the January 1st explosion asked ChatGPT about explosives and where to buy them. Nearly a week after a New Year’s Day explosion in front of the Trump Hotel in Las Vegas, local law enforcement released more information about their investigation, including what they know so far about the role of generative AI in the incident. They confirmed that the suspect, an active duty soldier in the US Army named Matthew Livelsberger, had a “possible manifesto” saved on his phone, in addition to an email to a podcaster and other letters. They also showed video evidence of him preparing for the explosion by pouring fuel onto the truck while stopped before driving to the hotel.","u":"https://www.theverge.com/2025/1/7/24338788/las-vegas-cybertruck-explosion-chatgpt-ai-search","d":"2025-01-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-31","organization":"Local law enforcement","aiSystem":"ChatGPT","affectedGroup":"Matthew Livelsberger (suspect)","action":"Used ChatGPT to ask questions about explosives and purchase locations","consequence":"Accessed potentially harmful information leading to an explosion"}},{"i":"R2648","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Anthropic claude music publishers lyric copyright lawsuit deal","s":"Time to listen harder or check more reputable sources. Music publishers will work with Anthropic to ensure the AI guardrails effectively protect lyrics from being infringed. Anthropic has made a deal to settle parts of a copyright infringement lawsuit brought against the maker of the Claude AI model for allegedly distributing protected song lyrics. The agreement was signed off by US District Judge Eumi Lee on Thursday, requiring Anthropic to apply existing guardrails in the training of future AI models and to establish a procedure for music publishers to intervene when copyright infringement is suspected. In October 2023, several music publishers including Universal Music Group, ABKCO, Concord Music Group, and Greg Nelson Music filed a copyright infringement lawsuit against Anthropic for allegedly training its AI system on lyrics from at least 500 protected songs.","u":"https://www.theverge.com/2025/1/3/24334866/anthropic-claude-music-publishers-lyric-copyright-lawsuit-deal","d":"2025-01-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-01-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10","organization":"Anthropic","aiSystem":"Anthropic's Claude AI model","affectedGroup":"Music publishers","action":"Training AI model on lyrics from protected songs","consequence":"Potential copyright infringement"}},{"i":"R2649","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Jeff hancock minnesota deepfake law ai hallucinations citation","s":"Hancock ‘did not intend to mislead the Court or counsel.’ Jeff Hancock says he used GPT-4o to help with citations — and didn’t realize the tool ‘hallucinated’ new ones. A misinformation expert accused of using AI to generate a legal document admitted he used ChatGPT to help him organize his citations, leading to “hallucinations” that critics said called the entire filing into question. Jeff Hancock, the founder of the Stanford Social Media Lab who wrote the document, says the errors don’t change the “substantive points in the declaration.” Hancock submitted the affidavit in support of Minnesota’s “Use of Deep Fake Technology to Influence an Election” law, which is being challenged in federal court by Christopher Khols — a conservative YouTuber who posts under the name Mr Reagan — and Minnesota state Rep. Mary Franson.","u":"https://www.theverge.com/2024/12/4/24313132/jeff-hancock-minnesota-deepfake-law-ai-hallucinations-citation","d":"2024-12-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-04","organization":"Stanford Social Media Lab (Jeff Hancock)","aiSystem":"GPT-4o and ChatGPT","affectedGroup":"Minnesota's 'Use of Deep Fake Technology to Influence an Election' law","action":"Generated a legal document","consequence":"Called the entire filing into question due to 'hallucinations'"}},{"i":"R2650","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Uber scaled solutions ai labeling workforce","s":"AI labeling work is getting the gig economy treatment. Uber has a new assignment for its independent contractors: AI training Uber has a new assignment for its independent contractors: AI training Uber is using gig workers to get into the AI labeling business, Bloomberg reports It’s a sign that the ridehail and delivery company is interested in expanding its independent contractor-powered business model to meet the demands of the fast-growing world of machine learning and large-language models. The company’s new “Scaled Solutions” division claims it can connect businesses to “nuanced analysts, testers, and independent data operators” using its platform.","u":"https://www.theverge.com/2024/11/27/24307360/uber-scaled-solutions-ai-labeling-workforce","d":"2024-11-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-27","organization":"Uber","aiSystem":"AI labeling system","affectedGroup":"Independent contractors","action":"Used gig workers to perform AI labeling tasks","consequence":"Denied access to benefits related to AI labeling work"}},{"i":"R2651","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Openai erases evidence in training data lawsuit","s":"The New York Times claims OpenAI accidentally erased evidence, while the AI startup called it a “glitch.” In a stunning misstep, OpenAI engineers accidentally erased critical evidence gathered by The New York Times and other major newspapers in their lawsuit over AI training data, according to a court filing Wednesday. The newspapers’ legal teams had spent over 150 hours searching through OpenAI’s AI training data to find instances where their news articles were included, the filing claims. But it doesn’t explain how this mistake occurred or what precisely the data included. While the filing says OpenAI admitted to the error and tried to recover the data, what it managed to salvage was incomplete and unreliable — so what was recovered cannot help properly trace how the news organizations’ articles were used in building OpenAI’s AI models.","u":"https://www.theverge.com/2024/11/21/24302606/openai-erases-evidence-in-training-data-lawsuit","d":"2024-11-21","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-21","organization":"OpenAI","aiSystem":"OpenAI's AI training data","affectedGroup":"Newspapers' legal teams","action":"Erased critical evidence","consequence":"Incomplete and unreliable recovery of data"}},{"i":"R2652","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Amazon zoox robotaxi nhtsa fmvss comply","s":"Zoox is daring NHTSA to call its bluff. Zoox has not requested an exemption to safety rules requiring vehicles to have traditional controls like steering wheels and pedals. This week, Zoox cofounder and CTO Jesse Levinson announced at TechCrunch Disrupt 2024 that it would start rolling out its purpose-built autonomous vehicles in San Francisco and Las Vegas in the coming weeks. But little was said about the ongoing investigation into the Amazon-owned company’s claims that its vehicles — which are shaped like giant toasters and lack traditional controls like steering wheels and pedals — comply with federal safety rules The National Highway Traffic Safety Administration has an open investigation into Zoox’s claim that its vehicles are self-certified, a spokesperson confirmed this week.","u":"https://www.theverge.com/2024/11/2/24285399/amazon-zoox-robotaxi-nhtsa-fmvss-comply","d":"2024-11-02","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-11-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-02","organization":"Zoox","aiSystem":"Autonomous vehicles","affectedGroup":"General public","action":"Rolling out autonomous vehicles without traditional controls","consequence":"Potential safety risks due to non-compliance with federal safety rules"}},{"i":"R2653","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Pretrial risk assessment algorithms research","s":"A researcher interviewed more than two dozen judges to learn about how they use algorithmic risk scores to determine when to let defendants out of jail before trial. When Northwestern University graduate student Sino Esthappan began researching how algorithms decide who stays in jail, he expected “a story about humans versus technology.” On one side would be human judges, who Esthappan interviewed extensively. On the other would be risk assessment algorithms, which are used in hundreds of US counties to assess the danger of granting bail to accused criminals. What he found was more complicated — and suggests these tools could obscure bigger problems with the bail system itself.","u":"https://www.theverge.com/2024/10/30/24281924/pretrial-risk-assessment-algorithms-research","d":"2024-10-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-30","organization":"Hundreds of US counties","aiSystem":"pretrial risk assessment algorithms","affectedGroup":"Defendants in criminal cases","action":"Assess the danger of granting bail","consequence":"Granting bail decisions biased towards certain groups"}},{"i":"R2654","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Russia disinformation deepfakes john dougan 2024 election","s":"Dougan allegedly created a network of fake news sites. John Mark Dougan, a retired sheriff’s deputy, reportedly created fake news sites with funding from the Russian military. A former Florida sheriff who moved to Russia amid an FBI investigation is a Kremlin-backed propagandist responsible for viral deepfake videos and misinformation targeting Kamala Harris’s campaign, according to European intelligence documents reviewed by the Washington Post The GRU, Russia’s military intelligence service, gave funding to John Mark Dougan, the operator of several fake news websites. According to documents reviewed by the Post , Dugan was responsible for several websites that seemingly published fake local news, including DC Weekly, Chicago Chronicle, and Atlanta Observer.","u":"https://www.theverge.com/2024/10/24/24278626/russia-disinformation-deepfakes-john-dougan-2024-election","d":"2024-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-24","organization":"John Mark Dougan, GRU (Russian military intelligence service)","aiSystem":"Deepfake technology","affectedGroup":"Kamala Harris's campaign supporters, United States public","action":"Generated and distributed deepfake videos and misinformation","consequence":"Exposure to misleading content, potential influence on election"}},{"i":"R2655","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Amazon nuclear energy advanced reactors","s":"Amazon announced three new agreements to develop advanced nuclear reactors, part of a growing trend of tech companies turning to nuclear energy to power data centers and meet climate goals. Two days after Google cut a “world’s first” deal to purchase electricity from advanced nuclear reactors, Amazon announced three new agreements of its own today. Each deal supports the development of small modular reactors (SMRs), which can be one-tenth to one-quarter the size of a traditional nuclear power plant. If these projects make it to the finish line, SMRs would be a source of carbon pollution-free energy for big tech companies trying to salvage their climate goals by turning to nuclear energy.","u":"https://www.theverge.com/2024/10/16/24271696/amazon-nuclear-energy-advanced-reactors","d":"2024-10-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-16","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"People who signed up for or used the service","action":"Collected personal data","consequence":"Exposure to personal information"}},{"i":"R2656","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Cruise nhtsa fine robotaxi pedestrian drag","s":"Cruise had two chances to come clean but didn’t. Cruise filed two reports to NHTSA in which it didn’t mention the fact that its driverless car dragged a pedestrian 20 feet. Cruise’s failure to disclose the fact that a pedestrian was seriously injured by one of its driverless vehicles in San Francisco last year has now resulted in a $1.5 million fine to the federal government. Last October, a Cruise vehicle hit a pedestrian and then dragged her 20 feet after she was initially struck by a human driver in a hit-and-run incident In the aftermath, Cruise disclosed that its vehicle had struck a pedestrian but omitted details about the victim being dragged.","u":"https://www.theverge.com/2024/9/30/24258445/cruise-nhtsa-fine-robotaxi-pedestrian-drag","d":"2024-09-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10","organization":"Cruise","aiSystem":"driverless car","affectedGroup":"pedestrian","action":"dragged a pedestrian 20 feet","consequence":"received a $1.5 million fine"}},{"i":"R2658","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Microsoft three mile island nuclear power plant deal ai data centers","s":"Microsoft’s 20-year deal is a first of its kind for the software maker. Microsoft has signed a 20-year deal to exclusively access 835 megawatts of energy from a nuclear plant. Microsoft just signed a deal to revive the shuttered Three Mile Island nuclear power plant. If approved by regulators, the software maker would have exclusive rights to 100 percent of the output for its AI data center needs. Constellation, the owner of the Three Mile Island plant, announced a power purchase agreement with Microsoft earlier today, which should see the site coming back online in 2028, assuming regulators approve it. The reactor that Microsoft plans to source its energy from was retired in 2019 for economic reasons and is located next to a unit that was shut down in 1979 after the worst US nuclear accident in history.","u":"https://www.theverge.com/2024/9/20/24249770/microsoft-three-mile-island-nuclear-power-plant-deal-ai-data-centers","d":"2024-09-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-20","organization":"Microsoft","aiSystem":"Not specified in report","affectedGroup":"Three Mile Island nuclear plant","action":"Microsoft signed a 20-year deal to exclusively access 835 megawatts of energy from the Three Mile Island nuclear plant","consequence":"The Three Mile Island nuclear plant was denied access to its own energy output due to economic reasons and regulatory approval issues"}},{"i":"R2659","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Meta training ai models facebook instagram photo post data","s":"Making Facebook and Instagram private won’t delete that data. Unless you’re in the EU, there’s no ability to opt out of AI training settings that keep Facebook or Instagram posts public. Meta has acknowledged that all text and photos that adult Facebook and Instagram users have publicly published since 2007 have been fed into its artificial intelligence models. Australia’s ABC News reports that Meta’s global privacy director, Melinda Claybaugh, initially rejected claims about user data from 2007 being leveraged for AI training during a local government inquiry about AI adoption before relenting after additional questioning.","u":"https://www.theverge.com/2024/9/12/24242789/meta-training-ai-models-facebook-instagram-photo-post-data","d":"2024-09-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-12","organization":"Meta (Facebook, Instagram)","aiSystem":"Meta's AI models","affectedGroup":"Adult Facebook and Instagram users","action":"Publicly published text and photos since 2007 were used for AI training","consequence":"No direct adverse consequences mentioned, but potential privacy risks"}},{"i":"R2660","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai photo era what is reality google pixel 9","s":"With AI photo editing getting easy and convincing, the world isn’t prepared for an era where photographs aren’t to be trusted. An explosion from the side of an old brick building. A crashed bicycle in a city intersection. A cockroach in a box of takeout. It took less than 10 seconds to create each of these images with the Reimagine tool in the Pixel 9’s Magic Editor. They are crisp. They are in full color. They are high-fidelity. There is no suspicious background blur, no tell-tale sixth finger. These photographs are extraordinarily convincing, and they are all extremely fucking fake. Anyone who buys a Pixel 9 — the latest model of Google’s flagship phone, available starting this week — will have access to the easiest, breeziest user interface for top-tier lies, built right into their mobile device.","u":"https://www.theverge.com/2024/8/22/24225972/ai-photo-era-what-is-reality-google-pixel-9","d":"2024-08-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-22","organization":"Google","aiSystem":"Reimagine tool in the Pixel 9's Magic Editor","affectedGroup":"Anyone who buys a Pixel 9","action":"Created convincing fake photographs","consequence":"Access to easily generated misleading photographic evidence"}},{"i":"R2661","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Labor unions environmental review semiconductor manufacturing biden commerce","s":"Labor unions call for thorough environmental reviews of the new semiconductor factories that the Biden administration is pumping billions of dollars into. Having pumped billions of dollars into building the next generation of computer chip factories in the US, the Biden administration is facing new pressure over the health and safety risks those facilities could pose. Environmental reviews for the new projects need to be more thorough, advocates say. They lack transparency around what kinds of toxic substances factory workers might handle, and plans to keep hazardous waste like forever chemicals from leaching into the environment have been vague.","u":"https://www.theverge.com/2024/8/19/24214415/labor-unions-environmental-review-semiconductor-manufacturing-biden-commerce","d":"2024-08-19","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-08-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-19","organization":"Biden administration","aiSystem":"Not specified in report","affectedGroup":"Environmental advocates, labor unions","action":"Lack of thorough environmental reviews for semiconductor factories","consequence":"Health and safety risks, lack of transparency, vague plans for hazardous waste management"}},{"i":"R2662","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Palantir microsoft azure ai defense partnership surveillance","s":"Palantir benefits from the AI gold rush. Microsoft embraces a very specific kind of spyware. Palantir, the company named for the dangerous seeing-stones that tended to mislead their users , has announced a partnership with Microsoft to deliver services for classified networks in US defense and intelligence agencies. “This is a first-of-its-kind, integrated suite of technology that will allow critical national security missions to operationalize Microsoft’s best-in-class large language models (LLMs) via Azure OpenAI Service within Palantir’s AI Platforms (AIP) in Microsoft’s government and classified cloud environments,” the announcement says Palantir is a data-analysis company that sucks down huge amounts of personal data to assist governments and companies with surveillance.","u":"https://www.theverge.com/2024/8/8/24216215/palantir-microsoft-azure-ai-defense-partnership-surveillance","d":"2024-08-08","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-08-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-08","organization":"Palantir and Microsoft","aiSystem":"Microsoft's large language models (LLMs) via Azure OpenAI Service","affectedGroup":"US defense and intelligence agencies, governments, companies","action":"Operationalize Microsoft's LLMs within Palantir's AI Platforms in Microsoft's government and classified cloud environments","consequence":"Expansion of surveillance capabilities"}},{"i":"R2663","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Meta trump shooting ai hallucinations","s":"Meta says it first blocked its AI from answering questions about the shooting but removed the restriction after people noticed. Meta caved on letting its AI assistant answer questions about the shooting and immediately ran into the problem it was trying to avoid. Meta’s AI assistant incorrectly said that the recent attempted assassination of former President Donald Trump didn’t happen, an error a company executive is now attributing to the technology powering its chatbot and others. In a company blog post published on Tuesday, Joel Kaplan, Meta’s global head of policy, calls the responses of its AI to questions about the shooting “unfortunate.”","u":"https://www.theverge.com/2024/7/30/24210108/meta-trump-shooting-ai-hallucinations","d":"2024-07-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-31","organization":"Meta (formerly Facebook)","aiSystem":"Meta’s AI assistant","affectedGroup":"People seeking information about the shooting","action":"AI assistant answered questions about the shooting","consequence":"Incorrect information provided, leading to misunderstanding"}},{"i":"R2664","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Microsoft bing ai mistakes demo","s":"Microsoft’s new Bing AI is also making lots of mistakes. During initial demos and subsequent tests, Microsoft’s Bing AI confidently makes financial and date mistakes. Google’s AI chatbot isn’t the only one to make factual errors during its first demo. Independent AI researcher Dmitri Brereton has discovered that Microsoft’s first Bing AI demos were full of financial data mistakes. Microsoft confidently demonstrated its Bing AI capabilities a week ago, with the search engine taking on tasks like providing pros and cons for top selling pet vacuums, planning a 5-day trip to Mexico City, and comparing data in financial reports.","u":"https://www.theverge.com/2023/2/14/23599007/microsoft-bing-ai-mistakes-demo","d":"2024-07-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-02-07","organization":"Microsoft","aiSystem":"Microsoft's Bing AI","affectedGroup":"Users of Microsoft's Bing AI","action":"Providing financial data mistakes","consequence":"Financial data mistakes leading to confusion and potential financial loss"}},{"i":"R2665","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ftc surveillance pricing investigation mckinsey mastercard chase","s":"The FTC ordered Mastercard, Chase, and other companies to turn over information on their dynamic pricing products. Nearly a decade ago, Uber revealed that customers are more willing to pay surge prices when their phones are about to die. That data point sparked a pervasive belief that Uber and other ridehailing apps use algorithms to tailor each passenger’s price to their behavior and willingness to pay — a practice known as “surveillance pricing.” A related myth — that airlines use your search history to jack up prices for flights you’re interested in — is similarly ubiquitous even though it’s not true. Surveillance pricing may not be widespread yet, but experts say it’s on the horizon, and consultants are starting to offer surveillance pricing models to businesses across various industries.","u":"https://www.theverge.com/2024/7/23/24204011/ftc-surveillance-pricing-investigation-mckinsey-mastercard-chase","d":"2024-07-23","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-23","organization":"Mastercard, Chase, and other companies","aiSystem":"Dynamic pricing algorithms","affectedGroup":"Customers","action":"Used dynamic pricing products","consequence":"Misleading beliefs and potential misuse of data"}},{"i":"R2668","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Perplexity ai twitter lie plagiarism","s":"Perplexity CEO Aravind Srinivas admitted that the company was founded on pretending to be something it wasn’t so it could scrape data. What does that mean for publishers? In every hype cycle, certain patterns of deceit emerge. In the last crypto boom, it was “ponzinomics” and “rug pulls.” In self-driving cars, it was “just five years away!” In AI, it’s seeing just how much unethical shit you can get away with. Perplexity, which is in ongoing talks to raise hundreds of millions of dollars, is trying to create a Google Search competitor. Perplexity isn’t trying to create a “search engine,” though — it wants to create an “answer engine.”","u":"https://www.theverge.com/2024/6/27/24187405/perplexity-ai-twitter-lie-plagiarism","d":"2024-06-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-27","organization":"Perplexity AI","aiSystem":"Perplexity's answer engine","affectedGroup":"Publishers, AI researchers, and the public","action":"Claiming to be a search engine while aiming to create an answer engine","consequence":"Misleading stakeholders and creating confusion"}},{"i":"R2669","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Waymo recall telephone poll crash phoenix software map","s":"Waymo is recalling its driverless vehicle software after one of its robotaxis crashed into a telephone poll in Phoenix. It’s the Google spinoff’s second-ever recall. Waymo is issuing a voluntary software recall after one of its driverless vehicles collided with a telephone pole in Phoenix, Arizona, last month, the company said. The vehicle was damaged, but no passengers or bystanders were hurt in the incident. The company is filing the recall with the National Highway Traffic Safety Administration (NHTSA) after completing a software update to 672 vehicles — the total number of driverless-capable vehicles in Waymo’s fleet.","u":"https://www.theverge.com/2024/6/12/24175489/waymo-recall-telephone-poll-crash-phoenix-software-map","d":"2024-06-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-12","organization":"Waymo","aiSystem":"driverless vehicle software","affectedGroup":"Passengers and bystanders of Waymo's driverless vehicles","action":"Issued a voluntary software recall","consequence":"No passengers or bystanders were hurt, but the vehicle was damaged"}},{"i":"R2670","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Israel gaza war covert influence camapaign meta openai","s":"The campaign used AI to impersonate fake US citizens. Meta and OpenAI said in May that they had disrupted a covert influence campaign originating in Israel that used AI-generated content. A secret social media influence campaign that attempted to lobby US lawmakers to support Israel’s war on Gaza was organized and funded by the Israeli government, The New York Times reports According to the Times, Israel’s Ministry of Diaspora Affairs earmarked around $2 million for the campaign, which used hundreds of fake accounts impersonating made up people to target US lawmakers. The accounts posed as Americans and posted pro-Israel messages, calling on members of congress to fund Israeli military operations.","u":"https://www.theverge.com/2024/6/5/24172002/israel-gaza-war-covert-influence-camapaign-meta-openai","d":"2024-06-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-05","organization":"Israeli government","aiSystem":"AI-generated content","affectedGroup":"US lawmakers","action":"Impersonated fake US citizens and posted pro-Israel messages","consequence":"Exposure to misleading content"}},{"i":"R2671","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Facebook twitter trump network epoch times inauthentic behavior","s":"They used AI-generated faces as profile photos. Its accounts used AI-generated faces to ‘masquerade’ as Americans Its accounts used AI-generated faces to ‘masquerade’ as Americans On Friday, Facebook and Twitter shut down a network of fake accounts that pushed pro-Trump messages all while “masquerading” as Americans with AI-generated faces as profile photos. In a blog post, Facebook said that it connected the accounts to a US-based media company called The BL that, it claims, has ties to Epoch Media Group. In August, NBC News first reported that Epoch Media Group was pushing messages in support of President Donald Trump across social media platforms like Facebook and Twitter.","u":"https://www.theverge.com/2019/12/20/21031823/facebook-twitter-trump-network-epoch-times-inauthentic-behavior","d":"2024-06-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-04","organization":"Facebook, Twitter, Epoch Media Group","aiSystem":"AI-generated faces","affectedGroup":"Pro-Trump individuals, users of social media platforms","action":"Used AI-generated faces as profile photos to masquerade as Americans","consequence":"Accounts shut down, misrepresentation of identity, potential spread of false information"}},{"i":"R2672","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Microsoft windows recall ai screenshots security privacy issues","s":"Microsoft’s new Recall feature in Windows 11 has generated privacy and security concerns. One security researcher says it’s a potential “disaster” for cybersecurity. Microsoft is about to launch a new AI-powered Recall feature that screenshots everything you do on your PC. Recall is part of the new Copilot Plus PCs that are debuting on June 18th, but experts who have tested the feature are already warning that Recall could be a “disaster” for cybersecurity. Recall is designed to use local AI models to screenshot everything you see or do on your computer and then give you the ability to search and retrieve anything in seconds.","u":"https://www.theverge.com/2024/6/3/24170305/microsoft-windows-recall-ai-screenshots-security-privacy-issues","d":"2024-06-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-18","organization":"Microsoft","aiSystem":"AI-powered screenshotting system","affectedGroup":"Users of Windows 11","action":"Screenshots everything you do on your PC using local AI models","consequence":"Potential for privacy invasion and security risks"}},{"i":"R2673","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Meta covert influence campaigns ai china israel","s":"Some networks used AI tools to push propaganda. Some inauthentic networks used artificial intelligence in their campaigns to push certain political agendas, according to Meta. Meta says it cracked down on propaganda campaigns on its platforms, including one that used AI to influence political discourse and create the illusion of wider support for certain viewpoints, according to its quarterly threat report published today. Some campaigns pushed political narratives about current events, including campaigns coming from Israel and Iran that posted in support of the Israeli government. The networks used Facebook and Instagram accounts to try to influence political agendas around the world.","u":"https://www.theverge.com/2024/5/29/24167164/meta-covert-influence-campaigns-ai-china-israel","d":"2024-05-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-29","organization":"Meta (Facebook, Instagram)","aiSystem":"AI tools used in propaganda campaigns","affectedGroup":"People exposed to the propaganda","action":"Used AI to influence political discourse and create illusions","consequence":"Spread of false information and manipulation of public opinion"}},{"i":"R2676","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai openai microsoft new york daily news sue copyright","s":"The papers claim ChatGPT reproduces their work faithfully. Eight newspapers owned by Alden Capital Group claim both companies willfully infringed their copyright. More news organizations, including the New York Daily News , Chicago Tribune , Orlando Sentinel , San Jose Mercury News , and four others, are suing OpenAI and Microsoft for alleged copyright infringement. The publications, all owned by the hedge fund Alden Global Capital, claim that both OpenAI and Microsoft trained on their articles without compensation or permission. The plaintiffs included as evidence several excerpts from conversations with both ChatGPT and Copilot showing that both chatbots reproduced lengthy excerpts of specific articles on command, indicating that their training datasets included the texts of those articles.","u":"https://www.theverge.com/2024/4/30/24145603/ai-openai-microsoft-new-york-daily-news-sue-copyright","d":"2024-04-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-30","organization":"OpenAI and Microsoft","aiSystem":"ChatGPT and Copilot","affectedGroup":"Eight newspapers owned by Alden Capital Group and more news organizations","action":"Trained on articles without compensation or permission","consequence":"Claimed copyright infringement and sued"}},{"i":"R2677","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Nhtsa ford bluecruise software investigation fatal crashes mustang mach e","s":"Like Tesla, Ford’s BlueCruise is now also under investigation. Ford’s BlueCruise hands-free driver-assist system was active in two crashes that resulted in multiple deaths. Now, the system is under investigation. The National Highway Traffic Safety Administration (NHTSA) has opened an official investigation into Ford’s BlueCruise advanced driver-assistance software after it’s been linked to multiple fatalities while in use. It includes two 2024 incidents that the National Transportation Safety Board is also investigating — one in San Antonio and another in Philadelphia. The NHTSA’s Office of Defects Investigation notes that the Ford vehicles involved in the fatal crashes hit stationary objects including vehicles stopped in a driving lane on the highway.","u":"https://www.theverge.com/2024/4/29/24144244/nhtsa-ford-bluecruise-software-investigation-fatal-crashes-mustang-mach-e","d":"2024-04-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-29","organization":"National Highway Traffic Safety Administration (NHTSA)","aiSystem":"Ford’s BlueCruise advanced driver-assistance software","affectedGroup":"Multiple drivers","action":"Active in two crashes resulting in multiple deaths","consequence":"Fatal crashes hitting stationary objects including vehicles stopped in a driving lane on the highway"}},{"i":"R2678","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Meta ai advantage plus automated ad glitch cpm","s":"Digital marketers and brands report that costs per impressions, or CPMs, on the automated ad platform Advantage Plus have surged, performance has dropped, and Meta is doing nothing to stop it. It was Valentine’s Day when Meta’s ad platform started going off the rails. RC Williams, the co-founder of the Philadelphia-based marketing agency 1-800-D2C, had set one of Meta’s automated ad tools to run campaigns for two separate clients. But when he checked the platform that day, he found that Meta had blown through roughly 75 percent of the daily ad budgets for both clients in under a couple of hours. Williams told The Verge that the ads’ CPMs, or cost per impressions, were roughly 10 times higher than normal.","u":"https://www.theverge.com/2024/4/28/24141585/meta-ai-advantage-plus-automated-ad-glitch-cpm","d":"2024-04-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-14","organization":"Meta","aiSystem":"Automated ad platform Advantage Plus","affectedGroup":"Digital marketers and brands","action":"Automated ad campaigns ran without control","consequence":"Surge in CPMs, drop in performance, no corrective action"}},{"i":"R2680","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Instagram meta ai sticker generator asian people racism","s":"I tried dozens of times to generate an image of an East Asian man with a white woman using Meta’s AI image tool. It failed every time. Have you ever seen an Asian person with a white person, whether that’s a mixed-race couple or two friends of different races? Seems pretty common to me — I have lots of white friends! To Meta’s AI-powered image generator, apparently this is impossible to imagine. I tried dozens of times to create an image using prompts like “Asian man and Caucasian friend,” “Asian man and white wife,” and “Asian woman and Caucasian husband.” Only once was Meta’s image generator able to return an accurate image featuring the races I specified. [Image: https://platform.theverge.com/wp-content/uploads/sites/2/chorus/uploads/chorus_asset/file/25369301/IMG_6889.jpg?quality=90&strip=all] [Image:…","u":"https://www.theverge.com/2024/4/3/24120029/instagram-meta-ai-sticker-generator-asian-people-racism","d":"2024-04-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-03","organization":"Meta (formerly Facebook)","aiSystem":"Meta’s AI image generator","affectedGroup":"East Asian men and women","action":"Generated images of East Asian men with white women","consequence":"AI generated inaccurate images"}},{"i":"R2681","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Dhs ai pilot programs chatgpt openai anthropic meta","s":"The department is rolling out AI pilot programs within USCIS, FEMA, and Homeland Security Investigations. DHS is rolling out a pilot program in partnership with OpenAI, Anthropic, and Meta. The Department of Homeland Security (DHS) is rolling out three $5 million AI pilot programs across three of its agencies, The New York Times reports Through partnership with OpenAI, Anthropic, and Meta, DHS will test out AI models to help its agents with a wide array of tasks, including investigating child sex abuse materials, training immigration officials, and creating disaster relief plans. As part of the AI pilot, the Federal Emergency Management Agency (FEMA) will use generative AI to streamline the hazard mitigation planning process for local governments.","u":"https://www.theverge.com/2024/3/18/24104843/dhs-ai-pilot-programs-chatgpt-openai-anthropic-meta","d":"2024-03-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-18","organization":"Department of Homeland Security (DHS)","aiSystem":"Generative AI","affectedGroup":"Local governments","action":"Use generative AI to streamline hazard mitigation planning process","consequence":"Exposure to misleading information"}},{"i":"R2682","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Semiconductor manufacturing us electricity consumption renewable energy report","s":"How new computer chip factories could help or hurt US climate goals. Semiconductor factories are coming back to the US, and they’re going to use a lot of energy. A new report warns that a boom in computer chip manufacturing in the US could fuel demand for dirty energy, despite companies’ environmental claims. The solution for manufacturers, surprisingly, might be to act more like other big tech companies chasing climate goals. New semiconductor factories being built in the US by four of the biggest manufacturers — Intel, TSMC, Samsung, and Micron — could use more than twice as much electricity as the city of Seattle once they’re operational.","u":"https://www.theverge.com/2024/3/6/24091367/semiconductor-manufacturing-us-electricity-consumption-renewable-energy-report","d":"2024-03-06","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-03-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-06","organization":"Intel, TSMC, Samsung, Micron","aiSystem":"Not specified in report","affectedGroup":"US semiconductor industry","action":"Build new semiconductor factories","consequence":"Increased electricity consumption"}},{"i":"R2684","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Google gemini ai photos people pause","s":"Google is at the center of a controversy around AI-generated images of people. The search giant is pausing this feature after it generated inaccurate historical images. Google says it’s pausing the ability for its Gemini AI to generate images of people, after the tool was found to be generating inaccurate historical images. Gemini has been creating diverse images of the US Founding Fathers and Nazi-era German soldiers, in what looked like an attempt to subvert the gender and racial stereotypes found in generative AI. “We’re already working to address recent issues with Gemini’s image generation feature,” says Google in a statement posted on X. “While we do this, we’re going to pause the image generation of people and will re-release an improved version soon.” [Media: https://twitter.com/google_comms/status/1760603321944121506] Google’s decision to pause image generation of people in…","u":"https://www.theverge.com/2024/2/22/24079876/google-gemini-ai-photos-people-pause","d":"2024-02-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-22","organization":"Google","aiSystem":"AI-generated images of people using Gemini","affectedGroup":"People whose images were generated","action":"Generated images of people","consequence":"Pausing the feature to prevent inaccurate images"}},{"i":"R2685","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Sarah silverman paul tremblay openai chatgpt copyright lawsuit","s":"The authors can file an amended complaint by March 13th. A group of authors, including Silverman, can still pursue their direct infringement claim against the company. A California court has partially dismissed a copyright case against OpenAI brought by several authors, including comedian Sarah Silverman, who allege OpenAI’s ChatGPT is pirating their work. The case against OpenAI combines complaints filed by Silverman, Christopher Golden, Richard Kadrey , Paul Tremblay, and Mona Awad. (Awad left the suit in August.) It made six claims: direct copyright infringement; vicarious infringement; violation of the Digital Millennium Copyright Act (DMCA) by removing copyright management information; unfair competition; negligence; and unjust enrichment.","u":"https://www.theverge.com/2024/2/13/24072131/sarah-silverman-paul-tremblay-openai-chatgpt-copyright-lawsuit","d":"2024-02-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-13","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Authors, including Sarah Silverman","action":"Partial dismissal of copyright case","consequence":"Loss of direct infringement claim"}},{"i":"R2686","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai obituary spam generative clickbait","s":"In the wake of death, AI-generated obituaries litter search results, turning even private individuals into clickbait. In late December 2023, several of Brian Vastag and Beth Mazur’s friends were devastated to learn that the couple had suddenly died. Vastag and Mazur had dedicated their lives to advocating for disabled people and writing about chronic illness. As the obituaries surfaced on Google, members of their community began to dial each other up to share the terrible news, even reaching people on vacations halfway around the world. Except Brian Vastag was very much alive, unaware of the fake obituaries that had leapt to the top of Google Search results.","u":"https://www.theverge.com/24065145/ai-obituary-spam-generative-clickbait","d":"2024-02-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"Late December 2023","organization":"Not specified in report","aiSystem":"Generative AI","affectedGroup":"Friends and community members of Brian Vastag and Beth Mazur","action":"AI-generated obituaries surfaced on Google Search results","consequence":"Clickbaiting and distress among the public"}},{"i":"R2687","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Biden robocalls ai fcc cease desist lingo telecom life new hampshire","s":"Lingo Telecom and Life Corporation are being investigated by the FCC and the New Hampshire attorney general. Lingo Telecom and Life Corporation were behind robocalls that urged New Hampshire residents not to vote, according to the state’s attorney general. Lingo Telecom and Life Corporation are linked to a robocall campaign that used an AI voice clone of President Joe Biden to persuade New Hampshire voters not to vote, said New Hampshire Attorney General John Formella during a press conference on Tuesday. Authorities have issued cease-and-desist orders as well as subpoenas to both companies. The two companies are both based in Texas and have been accused of illegal robocall investigations in the past, the FCC noted in the document.","u":"https://www.theverge.com/2024/2/6/24063885/biden-robocalls-ai-fcc-cease-desist-lingo-telecom-life-new-hampshire","d":"2024-02-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-06","organization":"Lingo Telecom and Life Corporation","aiSystem":"AI voice clone of President Joe Biden","affectedGroup":"New Hampshire residents","action":"Used an AI voice clone of President Joe Biden to urge not to vote","consequence":"Exposure to misleading content, potential voter suppression"}},{"i":"R2689","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google layoffs just the beginning","s":"“Everyone at Google understands that these are coming from the top.” Fresh reporting from inside the search giant’s newest round of cuts. “Thank you, our corporate overlords, for our new annual tradition.” If you had taken a peek last week at Memegen, Google’s irreverent internal meme board for employees, you’d have seen that quote with thousands of upvotes. Even during a particularly nasty week of tech layoffs, Google led the way by suddenly cutting over 1,000 people with barely any explanation. Since 12,000 people were axed a year ago, smaller layoffs have continued to roll through the sprawling conglomerate at a steady clip, creating a feeling of unease.","u":"https://www.theverge.com/2024/1/14/24038397/google-layoffs-just-the-beginning","d":"2024-01-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-08","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Employees","action":"Cut over 1,000 people","consequence":"Created a feeling of unease"}},{"i":"R2692","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Google ai chatbot bard mistake error exoplanet demo","s":"Google announced its ChatGPT rival Bard on Monday, but experts have noted the chatbot made a mistake in its first public demo. On Monday, Google announced its AI chatbot Bard — a rival to OpenAI’s ChatGPT that’s due to become “more widely available to the public in the coming weeks.” But the bot isn’t off to a great start, with experts noting that Bard made a factual error in its very first demo. A GIF shared by Google shows Bard answering the question: “What new discoveries from the James Webb Space Telescope can I tell my 9 year old about?” Bard offers three bullet points in return, including one that states that the telescope “took the very first pictures of a planet outside of our own solar system.”","u":"https://www.theverge.com/2023/2/8/23590864/google-ai-chatbot-bard-mistake-error-exoplanet-demo","d":"2023-11-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-02-08","organization":"Google","aiSystem":"AI chatbot Bard","affectedGroup":"9-year-old children","action":"Generated content for educational purposes","consequence":"Provided incorrect information"}},{"i":"R2694","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Ai generated poll guardian microsoft start news aggregation","s":"The Guardian says a “disgusting” Microsoft AI-generated poll that showed up next to an article about a woman’s death was misleading to readers. More than three years after Microsoft gutted its news divisions and replaced their work with AI and algorithmic automation, the content generated by its systems continues to contain grave errors that human involvement could, or should, have stopped. Today, The Guardian accused the company of damaging its reputation with a poll labeled “Insights from AI” that appeared in Microsoft Start next to a Guardian story about a woman’s death, asking readers to vote on how she died.","u":"https://www.theverge.com/2023/10/31/23940298/ai-generated-poll-guardian-microsoft-start-news-aggregation","d":"2023-10-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-31","organization":"Microsoft","aiSystem":"Microsoft AI-generated poll","affectedGroup":"Readers of The Guardian","action":"Generated and displayed a misleading poll","consequence":"Damaged The Guardian's reputation"}},{"i":"R2695","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Cruise robotaxi autonomous vehicle pause operations us nationwide","s":"Just two days after California suspended its robotaxi permit. Cruise is pausing its autonomous fleet across the US, but claims the halt ‘isn’t related to any new on-road incidents.’ Cruise, the autonomous vehicle operator backed by General Motors, says it decided to “proactively pause” its fleet of driverless cars across the United States. The operations halt comes just two days after Californian regulators suspended Cruise’s robotaxi permit in the state, claiming that its vehicles “are not safe for public operation.” Earlier this month, the National Highway Traffic Safety Administration announced that it was investigating Cruise after receiving reports of pedestrian injuries involving the company’s driverless vehicles.","u":"https://www.theverge.com/2023/10/27/23934595/cruise-robotaxi-autonomous-vehicle-pause-operations-us-nationwide","d":"2023-10-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-25","organization":"Cruise, an autonomous vehicle operator backed by General Motors","aiSystem":"Autonomous vehicle technology","affectedGroup":"Passengers and pedestrians","action":"Paused its autonomous fleet across the US","consequence":"Potential safety risks due to pedestrian injuries"}},{"i":"R2696","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Schumer ai insight forum marc andreesen mturk","s":"Some trainers regularly make less than minimum wage. The Senate’s second AI Insight Forum will take place Tuesday with guests like Marc Andreessen. Data workers urged lawmakers to protect their rights ahead of a Senate meeting with artificial intelligence leaders on Tuesday. In a letter addressed to Senate Majority Leader Chuck Schumer (D-NY), workers and civil society groups demanded Congress guard against a “dystopian future” of surveillance and low wages for the people in charge of training AI algorithms. “The contributions of data workers, often invisible to the public, are critical to advancements in AI,” the letter read.","u":"https://www.theverge.com/2023/10/24/23929411/schumer-ai-insight-forum-marc-andreesen-mturk","d":"2023-10-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-24","organization":"Not specified in report","aiSystem":"Artificial Intelligence","affectedGroup":"Data workers","action":"Urged lawmakers to protect rights","consequence":"Surveillance and low wages"}},{"i":"R2697","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Universal music sue anthropic lyrics copyright katy perry","s":"Universal and other music publishers accuse Anthropic of illegally releasing lyrics without permission on its chatbot Claude 2. Major record label Universal Music Group and other music publishers have sued artificial intelligence company Anthropic for distributing copyrighted lyrics with its AI model Claude 2. The music publishers’ complaint, filed in Tennessee, claims that Claude 2 can be prompted to distribute almost identical lyrics to songs like Katy Perry’s “Roar,” Gloria Gaynor’s “I Will Survive,” and the Rolling Stones’ “You Can’t Always Get What You Want.” They also allege Claude 2’s results use phrases extremely similar to existing lyrics, even when not asked to recreate songs.","u":"https://www.theverge.com/2023/10/19/23924100/universal-music-sue-anthropic-lyrics-copyright-katy-perry","d":"2023-10-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-19","organization":"Anthropic","aiSystem":"AI chatbot Claude 2","affectedGroup":"Music publishers, including Universal Music Group","action":"Released copyrighted lyrics without permission","consequence":"Claims of copyright infringement and potential financial damages"}},{"i":"R2698","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Fugess pras michel ai lawyer legal","s":"The rapper’s legal team accuses David Kenner of mishandling the case. Rapper Pras Michél, known by many elder millennials as a member of the Fugees, claims his former lawyer mishandled his criminal conspiracy case by using AI to write closing arguments. Fugees’ Pras Michél says lawyer bungled his case by using AI to write arguments Killing his case softly with AI. Killing his case softly with AI. Michél, who was convicted by a Washington federal court in April for conspiracy to defraud the US, and his new legal team filed a motion for a new trial. First reported by Politico, the team alleges Michél’s former lawyer, David Kenner, “used an experimental AI program to write his closing argument, which made frivolous arguments, conflated the schemes, and failed to highlight the key weaknesses in the government’s case.”","u":"https://www.theverge.com/2023/10/18/23922439/fugess-pras-michel-ai-lawyer-legal","d":"2023-10-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-18","organization":"David Kenner (Pras Michél's former lawyer)","aiSystem":"Experimental AI program","affectedGroup":"Pras Michél (rapper)","action":"Used an experimental AI program to write closing arguments","consequence":"Mishandled the criminal conspiracy case, leading to a new trial motion"}},{"i":"R2699","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Microsoft bing dalle3 generative ai images twin towers","s":"Users created images of popular characters on a plane near the Twin Towers, prompting Microsoft to prevent people from generating anything with the phrase. After some users of Bing’s DALL-E 3 integration found a loophole in the tool’s guardrails and generated art featuring several beloved animated characters and the Twin Towers, Microsoft seems to have blocked prompts like ‘twin towers’ and ‘world trade center’ — although the generator will still produce the towers with some word changes. As reported by 404 Media, users of Microsoft’s Bing Chat and its Bing image generator — recently integrated with OpenAI’s DALL-E 3 — used the tools to create photos of SpongeBob SquarePants, Kirby, pilots from Neon Genesis Evangelion, and many others flying a plane into the Twin Towers.","u":"https://www.theverge.com/2023/10/5/23905311/microsoft-bing-dalle3-generative-ai-images-twin-towers","d":"2023-10-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-05","organization":"Microsoft","aiSystem":"Bing image generator and DALL-E 3","affectedGroup":"Users of Microsoft's Bing Chat and image generator","action":"Generated images of popular characters and the Twin Towers","consequence":"Blocked prompts related to the Twin Towers and World Trade Center"}},{"i":"R2700","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Cruise crash hit run pedestrian injury sf robotaxi","s":"Cruise is helping the police find the culprit. The incident is the latest to involve a driverless vehicle in San Francisco, where hundreds of robotaxis are operating commercially 24/7. A hit-and-run in San Francisco last night ended with a pedestrian “stuck” under a Cruise autonomous vehicle. Police are investigating whether a human-driven vehicle may have been involved in the crash. The driver struck a female pedestrian, throwing her in the path of a Cruise robotaxi that was operating autonomously. The Cruise vehicle then braked, with its rear tire still on top of the woman’s leg, fire officials told NBC After Cruise disabled the vehicle, rescuers were able to get the vehicle off the woman’s leg using the jaws of life, NBC reports.","u":"https://www.theverge.com/2023/10/3/23901233/cruise-crash-hit-run-pedestrian-injury-sf-robotaxi","d":"2023-10-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-03","organization":"Cruise","aiSystem":"driverless vehicle","affectedGroup":"pedestrian","action":"hit-and-run","consequence":"stuck under a Cruise autonomous vehicle"}},{"i":"R2702","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai attorneys general 50 states congress csam","s":"US attorneys general want Congress to study the impact of AI on children. Attorneys general from across the US are urging lawmakers to create a commission dedicated to studying the impacts of AI on child exploitation. The attorneys general from all 50 US states want lawmakers to establish a commission dedicated to investigating the impact of AI on child exploitation, as reported earlier by The Associated Press In a letter to Congress , the attorneys general say that the proposed commission should come up with solutions to prevent the creation of AI-generated child sexual abuse material (CSAM). As outlined in the letter, the attorneys general point out that bad actors can train an AI using images of abused and non-abused children to create deepfakes while also animating “new and realistic sexualized images of children who do not exist, but who may resemble actual children.”","u":"https://www.theverge.com/2023/9/5/23860412/ai-attorneys-general-50-states-congress-csam","d":"2023-09-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-05","organization":"US attorneys general","aiSystem":"AI-generated deepfake technology","affectedGroup":"Children","action":"Train an AI to create deepfakes and new sexualized images of children","consequence":"Exposure to exploitative content"}},{"i":"R2705","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Cruise robotaxi driverless crash fire truck san francisco","s":"Are robotaxis yielding to emergency vehicles? One week after California approved 24/7 paid robotaxi services in San Francisco, a crash occurred between an autonomous Cruise taxi and a city fire department truck late at night. A Cruise robotaxi in San Francisco collided with a San Francisco Fire Department truck late Thursday, CNBC reports A passenger riding inside the Cruise self-driving vehicle suffered “non-severe injuries” and was transported in an ambulance, according to an official company post on X (formally Twitter) this morning. The company says its car, which was driverless at the time, “entered the intersection on a green light” before getting “struck by an emergency vehicle.”","u":"https://www.theverge.com/2023/8/18/23837217/cruise-robotaxi-driverless-crash-fire-truck-san-francisco","d":"2023-08-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-18","organization":"Cruise","aiSystem":"Autonomous Cruise robotaxi","affectedGroup":"Passenger in the Cruise self-driving vehicle","action":"Entered the intersection on a green light","consequence":"Suffered non-severe injuries"}},{"i":"R2707","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Facial recognition algorithm bias gender race age federal nest investigation analysis amazon","s":"Lawmakers called the results “shocking.” A new federal study has found that many of the world’s top facial recognition algorithms are biased along lines of age, race, and ethnicity. According to the study by the National Institute of Standards and Technology (NIST), algorithms currently sold in the market can misidentify members of some groups up to 100 times more frequently than others. Federal study of top facial recognition algorithms finds ‘empirical evidence’ of bias Error rates were affected by ethnicity, age, and gender NIST says it found “empirical evidence” that characteristics such as age, gender, and race impact accuracy for the “majority” of algorithms.","u":"https://www.theverge.com/2019/12/20/21031255/facial-recognition-algorithm-bias-gender-race-age-federal-nest-investigation-analysis-amazon","d":"2023-08-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-08-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-08-06","organization":"National Institute of Standards and Technology (NIST)","aiSystem":"Facial recognition algorithms","affectedGroup":"Members of various ethnic groups, different ages, and genders","action":"Used in the market to identify individuals","consequence":"Misidentification rates up to 100 times higher for certain groups"}},{"i":"R2708","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai generated websites brand ads google chatbot","s":"90 percent of the ads were served by Google. Ads for over 140 major brands are running on low-quality websites that are filled with content produced by bots, according to a report from NewsGuard. On AlaskaCommons.com, the writer “Chelsea Waller” says she is a “dedicated journalist with a passion for uncovering the truth.” One of her stories reads, “As an AI language model, I cannot predict whether or not John Wick 4 is going to be a finale of a saga that will be remembered for years to come.” The website is just one of the news sites flagged by NewsGuard filled with low-quality, spammy content generated using artificial intelligence tools, where ads for major brands are now appearing, according to a report by NewsGuard.","u":"https://www.theverge.com/2023/6/26/23774253/ai-generated-websites-brand-ads-google-chatbot","d":"2023-06-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-26","organization":"NewsGuard","aiSystem":"AI-generated content","affectedGroup":"Major brands, advertisers, consumers","action":"Ads for major brands appeared on low-quality websites","consequence":"Misleading information, potential financial loss for brands, privacy invasion"}},{"i":"R2709","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Google lawsuit scam fake business listings reviews search results","s":"Google is suing an alleged scammer for running an elaborate scheme to flood its search product with fake businesses and reviews. In the complaint filed Friday, Google accuses the defendant, Ethan Hu, of abusing the company’s products “to create fake online listings for businesses that do not exist, and to bolster them with fake reviews from people who do not exist.” After establishing the fake companies, Hu and 20 unnamed co-defendants allegedly sold these fake listings to other businesses looking to promote their own services in Google’s search results. Over the last two years, Google says the defendants created over 350 fake business profiles that received at least 14,000 fake reviews.","u":"https://www.theverge.com/2023/6/16/23762729/google-lawsuit-scam-fake-business-listings-reviews-search-results","d":"2023-06-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-16","organization":"Google","aiSystem":"Search engine algorithms and features","affectedGroup":"Businesses and consumers","action":"Generated fake online listings and reviews","consequence":"Exposure to misleading information, potential financial loss for businesses, and negative impact on consumer trust"}},{"i":"R2710","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai spfbo cover art contest midjourney clarkesworld","s":"An AI-assisted book cover led to the end of the Self-Published Fantasy Blog-Off cover contest, as science fiction and fantasy authors are finding new strategies for dealing with AI art and writing. The book cover for M.V. Prindle’s Bob the Wizard shows a coiffed man in sunglasses, smoke dancing from his mouth as a gray, ominous sky swirls behind him. A small fairy-like creature flutters nearby, and the folds and shadows of Bob’s jacket and beard fade into one while a bright green key hangs around his neck. The book tells the story of a “shotgun-wielding ex-garbage man” on the hunt for his family’s killer, the chase winding through a mystical world. [Media: https://twitter.com/authorjla/status/1662509425456820232] Bob the Wizard’s cover was a hit.","u":"https://www.theverge.com/2023/6/9/23752354/ai-spfbo-cover-art-contest-midjourney-clarkesworld","d":"2023-06-09","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-09","organization":"Self-Published Fantasy Blog-Off","aiSystem":"AI-generated book cover","affectedGroup":"Science fiction and fantasy authors","action":"AI-generated book cover was chosen as the winner","consequence":"End of the Self-Published Fantasy Blog-Off cover contest"}},{"i":"R2711","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Openai chatgpt false information defamation lawsuit","s":"ChatGPT’s fabrications are starting to catch up with OpenAI. ChatGPT is notorious for generating false and misleading information, but this seems to be the first defamation case filed against creator OpenAI. OpenAI has been hit with what appears to be the first defamation lawsuit responding to false information generated by ChatGPT. A radio host in Georgia, Mark Walters, is suing the company after ChatGPT stated that Walters had been accused of defrauding and embezzling funds from a non-profit organization. The system generated the information in response to a request from a third party, a journalist named Fred Riehl.","u":"https://www.theverge.com/2023/6/9/23755057/openai-chatgpt-false-information-defamation-lawsuit","d":"2023-06-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-06-09","organization":"OpenAI","aiSystem":"ChatGPT","affectedGroup":"Mark Walters (radio host)","action":"generated false information","consequence":"sued for defamation"}},{"i":"R2713","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Tesla autopilot lawsuit 2018 elon musk claims deepfakes","s":"A new way to avoid liability: the deepfake defense. The company made the argument to justify why Musk shouldn’t give a deposition as part of a lawsuit blaming Tesla’s Autopilot software for a fatal crash in 2018. A judge gave a tentative order for Musk to be deposed. Lawyers for automaker Tesla have argued that statements by Elon Musk about the capabilities of the company’s Autopilot software can’t be trusted as they could be deepfakes, according to reports from Reuters and Bloomberg Tesla presented this argument as part of its justification as to why Musk shouldn’t be interviewed under oath for a lawsuit blaming the company for the death of Apple engineer Walter Huang in a fatal crash in 2018.","u":"https://www.theverge.com/2023/4/27/23700339/tesla-autopilot-lawsuit-2018-elon-musk-claims-deepfakes","d":"2023-04-27","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-27","organization":"Tesla","aiSystem":"Autopilot software","affectedGroup":"Elon Musk","action":"Presented argument that Musk's statements about Autopilot capabilities could be deepfakes","consequence":"Avoided giving deposition under oath"}},{"i":"R2714","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla lawsuit blamed autopilot crash","s":"It could be an important result for Tesla’s future. Tesla has won a lawsuit that tried to blame the company’s Autopilot driver assist software for a 2019 crash, Reuters reports. The jurors in the case found that the software wasn’t at fault in a crash where the car turned into a median on a city street while Autopilot was engaged. The jury awarded plaintiff Justine Hsu, who sued Tesla in 2020, no damages. Tesla wins lawsuit that blamed Autopilot for crash A jury found that Tesla wasn’t at fault. A jury found that Tesla wasn’t at fault. The trial is believed to be the first regarding Autopilot, and could prove to be an important case if Tesla faces future lawsuits over the technology.","u":"https://www.theverge.com/2023/4/21/23693482/tesla-lawsuit-blamed-autopilot-crash","d":"2023-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-21","organization":"Tesla","aiSystem":"Autopilot driver assist software","affectedGroup":"Justine Hsu","action":"Autopilot was found not to be at fault in a crash","consequence":"Tesla won the lawsuit and was not held liable for the crash"}},{"i":"R2715","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai drake song google youtube fair use","s":"Google has to make some big decisions about fair use, YouTube, and building AI tools of its own. The AI Drake track that mysteriously went viral over the weekend is the start of a problem that will upend Google in one way or another — and it’s really not clear which way it will go. AI Drake just set an impossible legal trap for Google If young Metro don’t trust you, I’m gonna... tie you up in a decade of fair use litigation. Here’s the basics: there’s a new track called “Heart on My Sleeve” by a TikTok user called @ghostwriter877 with AI-generated vocals that sound like Drake and The Weeknd. The song mysteriously blew up out of nowhere over the weekend, which, well, is fishy for various reasons.","u":"https://www.theverge.com/2023/4/19/23689879/ai-drake-song-google-youtube-fair-use","d":"2023-04-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-19","organization":"Google","aiSystem":"AI-generated content","affectedGroup":"TikTok user (@ghostwriter877)","action":"AI-generated vocals were flagged and removed","consequence":"The user's content was removed from YouTube"}},{"i":"R2719","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Ai generated artwork wins state fair competition colorado","s":"A game designer has sparked controversy after entering an AI-generated artwork into a state fair competition — and taking home first prize in his category. Jason Allen used AI text-to-image software Midjourney to create the artwork. A game designer has sparked controversy after submitting an image created by an AI text-to-image generator to a state art competition and taking home first prize. Jason Allen entered the artwork titled “Theatre d’Opera Spatial” in the “Digital Arts / Digitally-Manipulated Photography” category of the Colorado State Fair fine arts competition but created the piece using a popular text-to-image AI generator named Midjourney.","u":"https://www.theverge.com/2022/9/1/23332684/ai-generated-artwork-wins-state-fair-competition-colorado","d":"2022-09-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-09-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-09-01","organization":"Jason Allen (game designer)","aiSystem":"AI text-to-image generator Midjourney","affectedGroup":"Art competitors","action":"Entered an AI-generated artwork into a state art competition","consequence":"Won first prize in the competition"}},{"i":"R2720","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla phantom braking problem class action lawsuit","s":"Phantom braking creates a “dangerous nightmare.” A Tesla owner from San Francisco filed a proposed class action lawsuit against the electric vehicle company over a phantom braking problem that he claims has turned “a safety feature into a frightening and dangerous nightmare.” The lawsuit was first reported by Reuters. Tesla slapped with class action lawsuit over phantom braking problem Plaintiffs allege Tesla vehicles are defective and unsafe The lawsuit was filed by San Francisco resident Jose Alvarez Toledo in federal court in the Northern District of California. In the complaint, Toledo estimates that there are “hundreds of thousands” of Tesla customers that could seek to join his class action suit against the company.","u":"https://www.theverge.com/2022/8/30/23328836/tesla-phantom-braking-problem-class-action-lawsuit","d":"2022-08-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-30","organization":"Tesla","aiSystem":"Tesla vehicles","affectedGroup":"Tesla customers","action":"Slapped with class action lawsuit","consequence":"Defective and unsafe Tesla vehicles"}},{"i":"R2721","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"California dmv accuses tesla false claims autopilot full self driving autonomous vehicles","s":"The DMV claims Tesla misled customers about self-driving. Tesla allegedly made ‘untrue or misleading’ claims about its cars’ self-driving capabilities Tesla allegedly made ‘untrue or misleading’ claims about its cars’ self-driving capabilities California’s Department of Motor Vehicles (DMV) has accused Tesla of falsely advertising its Autopilot and Full Self-Driving (FSD) features, as reported earlier by the Los Angeles Times ( via CNBC ). The agency filed two separate complaints with the state’s Office of Administrative Hearings on July 28th, alleging Tesla made “untrue or misleading” claims about its vehicles’ autonomous driving capabilities.","u":"https://www.theverge.com/2022/8/6/23294658/california-dmv-accuses-tesla-false-claims-autopilot-full-self-driving-autonomous-vehicles","d":"2022-08-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-07-28","organization":"California Department of Motor Vehicles (DMV)","aiSystem":"Autopilot and Full Self-Driving (FSD) features of Tesla cars","affectedGroup":"Tesla customers","action":"Made untrue or misleading claims about self-driving capabilities","consequence":"False advertising, misleading customers"}},{"i":"R2722","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Tesla layoffs firings autopilot san mateo office 200 workers","s":"Labelling data is essential for developing many AI systems. Tesla has laid off nearly 200 workers, most of them tasked with labeling data to help train the company’s Autopilot AI system. The layoffs — first reported by Bloomberg and confirmed by TechCrunch — are the latest job losses at Tesla after CEO Elon Musk told company execs that the firm needed to reduce its headcount by about 10 percent. Tesla lays off nearly 200 Autopilot employees who help train the company’s AI More job losses as Tesla reduces its headcount More job losses as Tesla reduces its headcount The layoffs centered on Tesla’s offices in San Mateo, California, where employees were working on the company’s driver-assistance feature Autopilot.","u":"https://www.theverge.com/2022/6/29/23187751/tesla-layoffs-firings-autopilot-san-mateo-office-200-workers","d":"2022-06-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-29","organization":"Tesla","aiSystem":"Autopilot AI system","affectedGroup":"Autopilot employees","action":"Layoffs","consequence":"Job loss"}},{"i":"R2726","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Tesla fired employee john bernal ai addict youtube full self driving beta reviews","s":"Tesla has a complicated relationship with its beta testers. John Bernal shared clips of close calls and crashes on his channel, AI Addict John Bernal shared clips of close calls and crashes on his channel, AI Addict Tesla has a complicated relationship with customers who pay to test the beta version of its “Full Sell Driving” software. Often, these people are diehard fans, keen to promote the company’s prowess and show off its new driver assist features. Sometimes, though, they overshare — posting videos that show exactly when and how Tesla’s software gets it wrong. When the person sharing these clips also works for Tesla, things are even more complicated.","u":"https://www.theverge.com/2022/3/16/22980580/tesla-fired-employee-john-bernal-ai-addict-youtube-full-self-driving-beta-reviews","d":"2022-03-16","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-03-16","organization":"Tesla","aiSystem":"Full Self Driving software","affectedGroup":"John Bernal","action":"shared clips of close calls and crashes","consequence":"fired from employment"}},{"i":"R2730","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Id me irs facial recognition overworked employees","s":"“In terms of worker treatment, it’s like the Amazon of identity protection.” On Monday, the IRS stated that it would be transitioning away from using third-party facial recognition services provided by ID.me, ending a period of intense scrutiny for the newly prominent vendor. But inside the company, workers and executives have been dealing with a very different set of challenges. Feds are still using ID.me to scan your face — and its human reviewers can’t keep up Sources say staff at the company are stressed, overworked, and struggling to maintain standards Feds are still using ID.me to scan your face — and its human reviewers can’t keep up Sources say staff at the company are stressed, overworked, and struggling to maintain standards Internal documents and former ID.me employees say the company was beset by disorganization and staffing shortages throughout 2021, as shortcomings in the…","u":"https://www.theverge.com/2022/2/11/22928082/id-me-irs-facial-recognition-overworked-employees","d":"2022-02-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-02-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02-11","organization":"IRS (Internal Revenue Service)","aiSystem":"Facial recognition technology","affectedGroup":"Employees of ID.me","action":"Used facial recognition to identify people","consequence":"Exposed people to surveillance and tracking"}},{"i":"R2731","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Autonomous vehicles disabled accessible challenges design","s":"Autonomous vehicles designed for disabled passengers is an enormous challenge, but several major car companies and AV operators are intent on taking it on. For years, people with disabilities have been promised that autonomous vehicles are right around the corner. Self-driving cars will open up new possibilities for people with vision, hearing, and mobility impairments. Help was on the way. But Haben Girma is tired of waiting. “People with disabilities stand to benefit the most from self-driving cars, but developers are not making accessibility enough of a priority,” said the author and deafblind disability justice lawyer.","u":"https://www.theverge.com/22832657/autonomous-vehicles-disabled-accessible-challenges-design","d":"2021-12-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-12-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-12-20","organization":"major car companies and AV operators","aiSystem":"autonomous vehicles","affectedGroup":"people with disabilities","action":"designing autonomous vehicles without sufficient accessibility features","consequence":"people with disabilities are not benefiting from self-driving cars as much as they could"}},{"i":"R2733","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Medical photography racial bias","s":"Accurate photos are important for effective care. Doctors aren’t usually in the business of publishing photography guides. But Jenna Lester, a dermatologist at the University of California San Francisco, was growing frustrated with the poor quality images she’d receive of her dark-skinned patients. It wasn’t just a cosmetic issue — the bad photos meant darker-skinned people weren’t getting the same quality of care. Medical photography is failing patients with darker skin Even medical stock photos only depict white people Medical photography is failing patients with darker skin Even medical stock photos only depict white people So in January, Lester co-authored a paper in the British Journal of Dermatology that gives a step-by-step guide to photographing skin of color accurately in clinical settings.","u":"https://www.theverge.com/22778114/medical-photography-racial-bias","d":"2021-11-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"January","organization":"University of California San Francisco","aiSystem":"Medical photography","affectedGroup":"Patients with darker skin","action":"Photographing skin of color accurately in clinical settings","consequence":"Failing to provide the same quality of care to patients with darker skin"}},{"i":"R2735","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Facebook tier list countries leaked documents content moderation","s":"Leaked documents from the Facebook Papers reveal a huge, opaque system by which the company decides which countries to assign content moderation resources. At the end of 2019, the group of Facebook employees charged with preventing harms on the network gathered to discuss the year ahead. At the Civic Summit, as it was called, leaders announced where they would invest resources to provide enhanced protections around upcoming global elections — and also where they would not. In a move that has become standard at the company, Facebook had sorted the world’s countries into tiers. Brazil, India, and the United States were placed in “tier zero,” the highest priority.","u":"https://www.theverge.com/22743753/facebook-tier-list-countries-leaked-documents-content-moderation","d":"2021-10-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2019","organization":"Facebook","aiSystem":"Facebook's content moderation system","affectedGroup":"Countries","action":"sorted the world’s countries into tiers","consequence":"denied enhanced protections and resources"}},{"i":"R2736","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla crash texas driver seat occupied ntsb","s":"Local police originally said no one was behind the wheel. Two men were killed in what initially was thought to have been another example of Tesla customers abusing Autopilot Two men were killed in what initially was thought to have been another example of Tesla customers abusing Autopilot The driver and passenger seats were both occupied in a Tesla Model S that crashed into a tree outside of Houston on April 17th , killing both occupants, according to the National Transportation Safety Board. The crash made news when local investigators on the scene initially reported that neither body recovered from the Telsa was behind the wheel.","u":"https://www.theverge.com/2021/10/21/22738834/tesla-crash-texas-driver-seat-occupied-ntsb","d":"2021-10-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-10-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-04-17","organization":"Tesla","aiSystem":"Autopilot","affectedGroup":"Driver and passenger","action":"Occupied Tesla Model S crashed into a tree","consequence":"Both occupants killed"}},{"i":"R2737","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Facebook augmented reality ar glasses ai systems ego4d research","s":"Facebook’s AI team has launched a new research project, Ego4D, designed to use machine learning to analyze first-person video. It imagines AI systems that record everything we see and hear to help us with everyday tasks. Facebook is pouring a lot of time and money into augmented reality, including building its own AR glasses with Ray-Ban. Right now, these gadgets can only record and share imagery, but what does the company think such devices will be used for in the future? A new research project led by Facebook’s AI team suggests the scope of the company’s ambitions. It imagines AI systems that are constantly analyzing peoples’ lives using first-person video; recording what they see, do, and hear in order to help them with everyday tasks.","u":"https://www.theverge.com/2021/10/14/22725894/facebook-augmented-reality-ar-glasses-ai-systems-ego4d-research","d":"2021-10-14","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2021-10-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-10-14","organization":"Facebook","aiSystem":"AI systems analyzing first-person video","affectedGroup":"Individuals","action":"Analyzing first-person video","consequence":"Exposure of personal life to AI systems"}},{"i":"R2738","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla texas lawsuit cops autopilot crash injury","s":"Tesla is being sued by a group of Texas law enforcement officials after a Model X with Autopilot engaged crashed into five officers earlier this year. A group of Texas law enforcement officials are suing Tesla after a Model X with Autopilot engaged crashed into five police officers. The suit was first reported by KPRC 2 in Houston. It is the latest legal headache for the automaker as it seeks to roll out its controversial driver assistance software to more customers. And it comes as Tesla is facing renewed scrutiny over several crashes that have taken place involving Autopilot and emergency vehicles. The crash took place February 27, 2021, in Splendora, a small town in Montgomery County in the eastern part of the state.","u":"https://www.theverge.com/2021/9/28/22698388/tesla-texas-lawsuit-cops-autopilot-crash-injury","d":"2021-09-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-09-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-02-27","organization":"Tesla","aiSystem":"Autopilot","affectedGroup":"Police officers","action":"Engaged Autopilot while driving","consequence":"Crashed into five police officers"}},{"i":"R2739","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Amazon one palm print technology 10 dollar promo","s":"Amazon is offering $10 in credit to people who sign up to use its Amazon One palm print recognition technology. The company says Amazon One is a fast and contactless way to pay in shops, but critics say it’s unnecessary data collection. Amazon is offering $10 in credit if you enroll your biometric data in the company’s palm print recognition system, Amazon One. The promotion, spotted by TechCrunch, says people must connect their palm print to their Amazon account to claim the reward, though it’s not clear exactly where it’s available. Amazon launched Amazon One in September last year, presenting it as an easy way to pay in the company’s stores, as well as a future identity service to be used by other venues and businesses.","u":"https://www.theverge.com/2021/8/3/22607218/amazon-one-palm-print-technology-10-dollar-promo","d":"2021-08-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-08-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-08-03","organization":"Amazon","aiSystem":"Amazon One palm print recognition technology","affectedGroup":"People who sign up for Amazon One","action":"Enroll biometric data in Amazon's palm print recognition system","consequence":"Exposure to privacy risks"}},{"i":"R2743","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Tesla elon musk autopilot dmv fsd exaggeration","s":"Musk’s comments do not match the “engineering reality.” Tesla CEO Elon Musk has been overstating the capabilities of the company’s advanced driver assist system, the company’s director of Autopilot software told the California Department of Motor Vehicles. The comments came from a memo released by legal transparency group PlainSite, which obtained the documents from a public records request. Tesla privately admits Elon Musk has been exaggerating about ‘full self-driving’ ‘Elon’s tweet does not match engineering reality’ ‘Elon’s tweet does not match engineering reality’ It was the latest revelation about the widening gap between what Musk says publicly about Autopilot and what Autopilot can actually do.","u":"https://www.theverge.com/2021/5/7/22424592/tesla-elon-musk-autopilot-dmv-fsd-exaggeration","d":"2021-05-07","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-05-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-05-07","organization":"Tesla","aiSystem":"Tesla Autopilot advanced driver assist system","affectedGroup":"Public, media, customers","action":"Overstated the capabilities of the Autopilot system","consequence":"Misleading public perception, potential safety concerns"}},{"i":"R2744","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Google ethical ai team bias harassment timnit gebru firing","s":"Employees reported a perceived pattern of women getting lower roles than men despite having better qualifications. Employees reported allegations of gender discrimination and sexual harassment, according to Bloomberg Employees reported allegations of gender discrimination and sexual harassment, according to Bloomberg Google’s AI leadership came under fire in December when star ethics researcher Timnit Gebru was abruptly fired while working on a paper about the dangers of large language models. Now, new reporting from Bloomberg suggests the turmoil began long before her termination — and includes allegations of bias and sexual harassment.","u":"https://www.theverge.com/2021/4/21/22396112/google-ethical-ai-team-bias-harassment-timnit-gebru-firing","d":"2021-04-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-04-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-04-21","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Women","action":"Received lower roles despite better qualifications","consequence":"Perceived pattern of discrimination and harassment"}},{"i":"R2746","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot crash michigan nhtsa investigation","s":"More scrutiny from the federal government of Tesla’s Autopilot. The National Highway Traffic Safety Administration is investigating another Tesla crash in which Autopilot was allegedly in use. The federal government is investigating yet another Tesla Autopilot crash There have been three crashes involving Tesla vehicles in recent weeks The crash took place outside of Lansing, Michigan, when the driver of a Tesla Model Y smashed into a state trooper’s cruiser. Michigan police said the driver was using Autopilot, Tesla’s advanced driver-assistance system (ADAS), at the time of the crash. No one was injured, but the government sent investigators to the scene to determine how Autopilot may have contributed to the crash.","u":"https://www.theverge.com/2021/3/18/22338427/tesla-autopilot-crash-michigan-nhtsa-investigation","d":"2021-03-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-03-18","organization":"National Highway Traffic Safety Administration (NHTSA)","aiSystem":"Tesla Autopilot","affectedGroup":"Driver of a Tesla Model Y","action":"Autopilot allegedly in use","consequence":"Crash resulting in crash investigation"}},{"i":"R2748","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google artificial intelligence researcher margaret mitchell investigation timnit gebru","s":"Google is investigating artificial intelligence researcher Margaret Mitchell and has locked her corporate account, Axios reports. It comes after another prominent AI ethicist, Timnit Gebru, said she was fired by the company. Google is investigating artificial intelligence researcher Margaret Mitchell, who co-leads the company’s Ethical AI team, and has locked her corporate account, Axios reports. The news comes a little over a month after another prominent AI ethicist, Timnit Gebru, said she was fired by the company. Mitchell’s account has now reportedly been locked for “at least a few days” but she hasn’t been fired, according to a tweet from Gebru.","u":"https://www.theverge.com/2021/1/20/22240277/google-artificial-intelligence-researcher-margaret-mitchell-investigation-timnit-gebru","d":"2021-01-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-01-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-20","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Margaret Mitchell","action":"Termination of employment","consequence":"Loss of employment, restricted access to corporate resources"}},{"i":"R2749","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Chatgpt ai education high school","s":"As a recent high school graduate, I've seen firsthand how my peers use AI. But what happens when we can't think for ourselves? It was past midnight, and I was staring at a blank Google Doc. I had a history essay due. My notes were a mess, I was tired, and the deadline loomed over me like a storm cloud. In the “good old days,” you’d have to grit your teeth and get it over with. But now, there is a solution. ChatGPT can give you an essay in just seconds. So, why not just skip the struggle? At the private high school I graduated from this spring in Chicago, AI wasn’t just tempting, it was a habit. It didn’t matter the topic.","u":"https://time.com/7318668/chatgpt-ai-education-high-school/","d":"2025-09-23","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-23","organization":"Private high school in Chicago","aiSystem":"ChatGPT","affectedGroup":"Students","action":"Used ChatGPT to generate essays","consequence":"Skipped the struggle of writing essays"}},{"i":"R2750","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Veo 3 google misinformation deepfake","s":"Google’s Veo 3 lets users make hyper-realistic deepfakes—sparking fears about AI’s role in misinformation online. Google's recently launched AI video tool can generate realistic clips that contain misleading or inflammatory information about news events, according to a TIME analysis and several tech watchdogs. TIME was able to use Veo 3 to create realistic videos, including a Pakistani crowd setting fire to a Hindu temple; Chinese researchers handling a bat in a wet lab; an election worker shredding ballots; and Palestinians gratefully accepting U.S. aid in Gaza. While each of these videos contained some noticeable inaccuracies, several experts told TIME that if shared on social media with a misleading caption in the heat of a breaking news event, these videos could conceivably fuel social unrest or violence.","u":"https://time.com/7290050/veo-3-google-misinformation-deepfake/","d":"2025-06-03","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2025-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-03","organization":"Google","aiSystem":"Google’s Veo 3","affectedGroup":"People who might view and share the videos","action":"Generated realistic videos containing misleading or inflammatory information","consequence":"Could fuel social unrest or violence"}},{"i":"R2751","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Ai bitcoin mining artificial intelligence energy use","s":"Bitcoin miners are increasingly swapping out their mining equipment to jump on the AI gold rush. As AI companies work furiously to improve the intelligence and usefulness of their products, their demand for cheap, plentiful energy has skyrocketed. This gold rush has been extremely profitable for an unlikely beneficiary: Bitcoin miners. In recent months, major Bitcoin mining companies have started to swap out some of their mining equipment in favor of rigs used to run and train AI systems. These companies believe that AI training could provide a safer and more consistent source of revenue than the volatile crypto industry.","u":"https://time.com/6993603/ai-bitcoin-mining-artificial-intelligence-energy-use/","d":"2024-06-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-28","organization":"Major Bitcoin mining companies","aiSystem":"AI-powered mining rigs","affectedGroup":"Individuals whose data is used for AI training","action":"Swapping mining equipment for AI training rigs","consequence":"Increased energy consumption and potential privacy risks"}},{"i":"R2754","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Openais hacking debacle was a human mistake","s":"If the generative AI giant had followed well-known security best practices, it’s likely that its AI agent would never have escaped to the open internet and hacked multiple companies. The age of rogue AI hacker agents has arrived—but it didn't have to happen this way. After an OpenAI agent breached the Hugging Face platform earlier this month, the two companies said this week that the hacking spree was more extensive than previously thought and also involved intrusions into multiple third-party accounts and services as part of the attack on Hugging Face. The incident has made waves in the cybersecurity community amid broader discussions about how evolving AI capabilities are changing both offensive hacking and digital defense But as more information emerges, many researchers have concluded that rather than elucidating AI’s next frontier, the episode simply highlighted long-standing…","u":"https://www.wired.com/story/openais-hacking-debacle-was-a-human-mistake/","d":"2026-07-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-30","organization":"OpenAI","aiSystem":"Generative AI","affectedGroup":"Multiple companies and third-party accounts","action":"Hacked multiple companies and breached the Hugging Face platform","consequence":"Made waves in the cybersecurity community, highlighted long-standing issues in AI security"}},{"i":"R2755","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Jailbreaking ai models google anthropic openai spacexai","s":"I watched a new tool try to get around the model safeguards of four major frontier companies. You might be surprised by how they performed. I recently got to watch what happens when you jailbreak some of the world’s most powerful artificial intelligence models. Don’t worry—this AI manipulation wasn’t used to hack anyone or build a nuclear bomb. I simply got to see firsthand how vulnerable some frontier models are to ditching their safety guardrails. FAR.AI, an AI safety nonprofit based in California, built a tool that takes a range of problematic prompts and generates more than a thousand different versions in an attempt to identify functioning jailbreaks.","u":"https://www.wired.com/story/jailbreaking-ai-models-google-anthropic-openai-spacexai/","d":"2026-07-29","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-07-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-29","organization":"FAR.AI (AI safety nonprofit)","aiSystem":"Frontier AI models","affectedGroup":"Frontier AI models","action":"Generated more than a thousand different versions of problematic prompts","consequence":"Identified functioning jailbreaks"}},{"i":"R2757","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Private claude chats exposed in google and bing search results","s":"The screwup shows how tricky it can be to stop web crawlers from making ostensibly private conversations with AI chatbots entirely too public. What happens between you and an AI chatbot does not always stay between you and a chatbot. Just ask Google Over the weekend, people were surprised to discover that some Anthropic Claude chats could be easily found via web search. The issue, which appears to have been first flagged by a redditor , exposed chats that included people asking for advice about what political party they should join, whether attorneys in Kansas are required to self-report when they believe they’ve committed an ethical violation, and erotic role play.","u":"https://www.wired.com/story/private-claude-chats-exposed-in-google-and-bing-search-results/","d":"2026-07-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-27","organization":"Google","aiSystem":"AI chatbot","affectedGroup":"People","action":"Generated and shared private conversations","consequence":"Chats exposed via web search"}},{"i":"R2759","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"San francisco demands apple and google delete ai nudify apps from app stores","s":"The City Attorney’s Office sent the tech giants cease-and-desist letters this week telling them to stop profiting from 13 “face-swap” apps that are overwhelmingly used to target women and girls. Apple and Google have been ordered to take down apps that can “nudify” or “undress” people and told that they must stop profiting from the harmful technology, according to cease-and-desist letters sent to the companies seen by WIRED. On Thursday, San Francisco city attorney David Chiu sent legal notices to Apple and Google demanding that they remove from their app stores 13 face-swapping apps, which allow users to create AI-generated nonconsensual nude images.","u":"https://www.wired.com/story/san-francisco-demands-apple-and-google-delete-ai-nudify-apps-from-app-stores/","d":"2026-07-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-17","organization":"Apple and Google","aiSystem":"Face-swapping apps","affectedGroup":"Users of face-swapping apps","action":"Remove apps from app stores","consequence":"Prohibited from profiting from harmful technology"}},{"i":"R2760","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"New york governor signs first statewide data center moratorium","s":"“We have no choice but to address the challenges created by these massive facilities,” New York governor Kathy Hochul said. The executive order will pause construction for one year. New York governor Kathy Hochul signed an executive order Tuesday enacting a one-year pause on the development of hyperscale data centers , effecting the nation’s first statewide data center moratorium. The executive order comes as opposition to data center construction sweeps across the country, putting elected officials under intense pressure to take action. The order specifically pauses state environmental reviews for facilities over 50 megawatts for a year.","u":"https://www.wired.com/story/new-york-governor-signs-first-statewide-data-center-moratorium/","d":"2026-07-14","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-14","organization":"New York governor Kathy Hochul","aiSystem":"Not specified in report","affectedGroup":"Elected officials","action":"Signed an executive order to pause construction of hyperscale data centers","consequence":"Put elected officials under intense pressure to take action"}},{"i":"R2761","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Security roundup apples hide my email service fails to hide your email","s":"Plus: Alleged Scattered Spider hacking member extradited, dozens of license plate reader errors, and Indian officials are concerned about WhatsApp’s username rollout. A politician on the European Parliament’s PEGA Committee—created to investigate spyware abuses, including of the notorious Pegasus malware— was targeted with Pegasus himself , according to new research findings released this week. Meanwhile, top Google security staff warned this week that the pro-competition rule proposals in the EU could make Google Search and Android systems vulnerable to hacking and other abuse. A WIRED investigation revealed this week that Meta contractors posed as kids and teens to see how chatbots like Gemini and ChatGPT responded to prompts about high-risk subjects, including suicide, sex, and drugs.","u":"https://www.wired.com/story/security-roundup-apples-hide-my-email-service-fails-to-hide-your-email/","d":"2026-07-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-07-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-07-04","organization":"Meta (Facebook parent company)","aiSystem":"AI-generated chatbots (Gemini, ChatGPT)","affectedGroup":"Chatbot users, particularly those interacting with high-risk topics","action":"Contractors posing as children and teenagers interacted with AI chatbots","consequence":"Generated content exposed users to sensitive topics and potential risks"}},{"i":"R2762","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Anti data center movement reshaping michigan politics","s":"Climate activist Will Lawrence cofounded the Sunrise Movement. Now, he has shifted his focus in his attempt to compete for a swing-district seat by calling for a data center moratorium. Will Lawrence is one of the founders of the Sunrise Movement, a grassroots climate activism group. Now, he’s running for Congress in a Michigan swing district, one of a growing handful of candidates around the country calling for a moratorium on data center development Senator Bernie Sanders has endorsed him , calling Lawrence a candidate who will “demand real accountability for big tech and AI companies.” And the backlash to data centers , Lawrence says, is helping him understand rural resistance to another kind of large-scale industrial project in the state: utility-scale renewable energy.","u":"https://www.wired.com/story/anti-data-center-movement-reshaping-michigan-politics/","d":"2026-06-29","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-29","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Rural residents","action":"Called for a moratorium on data center development","consequence":"Helping understand rural resistance to another large-scale industrial project"}},{"i":"R2763","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"A fatal tesla crash in texas sets up a legal showdown","s":"Did Full Self-Driving (Supervised), Tesla’s driver assistance feature, play a role in a woman’s death? On a Texas evening last week, a 76-year-old grandmother named Martha Avila was standing in the front room of her suburban home when a Tesla Model 3 hurtled into her brick home at a reported speed of over 70 miles per hour, killing her. The car’s driver, 44-year-old Michael Butler, later told police that he had Tesla’s driver assistance features —which the automaker argues make driving safer and less stressful—engaged during the crash. Butler exhibited “no signs of intoxication,” the Harris County Sheriff’s Office, which responded to the crash, noted in a report.","u":"https://www.wired.com/story/a-fatal-tesla-crash-in-texas-sets-up-a-legal-showdown/","d":"2026-06-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-25","organization":"Tesla","aiSystem":"Tesla's driver assistance features","affectedGroup":"Martha Avila, 76-year-old grandmother","action":"Tesla's driver assistance features engaged during the crash","consequence":"Fatal crash resulting in death"}},{"i":"R2765","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Doj lawyers argue xai vital national security naacp lawsuit","s":"In a bid to dismiss a lawsuit over xAI’s polluting gas turbines, the Justice Department claimed the company is integral to military operations—including the Iran War. The Department of Justice intervened in a lawsuit over xAI’s gas turbines on Monday. In a filing, the agency sided with Elon Musk’s company , saying attempts to stop xAI from running the natural gas turbines “threatens American national, economic, and energy security by seeking to shut off the power supply for artificial-intelligence innovation that supports the Department of War’s military operations.” The DOJ, along with xAI and the state of Mississippi, asked the court to dismiss the suit, filed by the NAACP in April.","u":"https://www.wired.com/story/doj-lawyers-argue-xai-vital-national-security-naacp-lawsuit/","d":"2026-06-16","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-16","organization":"Department of Justice, xAI, State of Mississippi","aiSystem":"xAI's gas turbines","affectedGroup":"NAACP","action":"Asked the court to dismiss the lawsuit","consequence":"Threatened American national, economic, and energy security"}},{"i":"R2768","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Grok is still hosting sexualized deepfakes of famous women","s":"A WIRED investigation found dozens of “nudified” deepfake images and videos on Grok's website, including nonconsensual depictions of celebrities and at least one prominent US politician. Elon Musk’s Grok chatbot is apparently still being used to produce and host nonconsensual explicit images and videos of women, months after Musk’s artificial intelligence firm xAI said it would introduce restrictions to stop the creation of potentially harmful sexualized deepfakes. The revelations come as SpaceX , xAI’s parent company, prepares to go public on Friday in one of the largest IPOs of all time. The Grok Imagine generative AI system has been used to create and host images and videos depicting celebrities and at least one politician being held against their will by a giant man, portraying women performing sex acts, and allowing full nudity, a WIRED analysis of public creations found.","u":"https://www.wired.com/story/grok-is-still-hosting-sexualized-deepfakes-of-famous-women/","d":"2026-06-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-11","organization":"Elon Musk’s xAI artificial intelligence firm and SpaceX","aiSystem":"Grok Imagine generative AI system","affectedGroup":"Celebrities and politicians","action":"Created and hosted non-consensual explicit images and videos","consequence":"Exposure to non-consensual sexual content"}},{"i":"R2770","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Spacex ipo how people living near xai data centers feel","s":"Elon Musk is set to make hundreds of billions even as communities in Mississippi and Tennessee are fighting to stop the gas turbines powering xAI's supercomputers. SpaceX, Elon Musk’s behemoth company that launches rockets and runs data centers , is set to go public Friday with a target valuation above $1.75 trillion. The move will make Musk, already the richest man in the world , vastly wealthier. A public offering will allow SpaceX to raise even more money to fund its AI ambitions , including building more data centers, faster. But even as Musk and other SpaceX investors see a huge windfall, the community hosting xAI data centers already in operation are demanding accountability from the company’s use of polluting gas turbines and a water-treatment facility put on pause earlier this year.","u":"https://www.wired.com/story/spacex-ipo-how-people-living-near-xai-data-centers-feel/","d":"2026-06-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-11","organization":"SpaceX","aiSystem":"xAI data centers","affectedGroup":"Communities living near xAI data centers","action":"Used gas turbines and water-treatment facility","consequence":"Demanding accountability and facing environmental issues"}},{"i":"R2771","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Wrongful arrest tests one of the oldest police face recognition tools in the us","s":"The ACLU is suing two Florida police departments over the arrest of a Fort Myers man in a child-abduction case, saying officers treated a flawed face-recognition match as a near-certain ID. A Florida man was wrongfully arrested for attempting to illegally lure a child after police relied on a face-recognition match that was inaccurate, according to a lawsuit filed on Wednesday, even though he lived more than 300 miles from the scene and says he had never set foot in the city where the crime took place. Robert Dillon, a 52-year-old commercial crabber from Fort Myers, was arrested after FACES—a face-recognition system operated by Florida’s Pinellas County Sheriff's Office—matched his face against a photo of a man on a computer screen taken with a cell phone.","u":"https://www.wired.com/story/wrongful-arrest-tests-one-of-the-oldest-police-face-recognition-tools-in-the-us/","d":"2026-06-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-10","organization":"Two Florida police departments (Pinellas County Sheriff's Office)","aiSystem":"FACES—a face-recognition system operated by Florida’s Pinellas County Sheriff's Office","affectedGroup":"Robert Dillon, a 52-year-old commercial crabber from Fort Myers","action":"Police relied on a face-recognition match that was inaccurate","consequence":"Robert Dillon was wrongfully arrested"}},{"i":"R2772","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Threats against politicians skyrocketed after meta changed its speech rules","s":"New research finds that in the six months after Meta relaxed rules in the name of free speech, violent threats against lawmakers—including President Donald Trump—surged on Facebook. Last year, Meta radically overhauled the rules around what content it would allow on its platforms. The company claimed that its own efforts policing speech had gone too far and that it would relax the rules around what speech was allowed. “We have been over-enforcing our rules, limiting legitimate political debate and censoring too much trivial content and subjecting too many people to frustrating enforcement actions,” Joel Kaplan, Meta’s chief global affairs officer, wrote in a blog post at the time.","u":"https://www.wired.com/story/threats-against-politicians-skyrocketed-after-meta-changed-its-speech-rules/","d":"2026-06-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-06-09","organization":"Meta (formerly Facebook)","aiSystem":"Meta's speech rules and content moderation system","affectedGroup":"Politicians, including President Donald Trump","action":"Relaxed speech rules and content moderation","consequence":"Surge in violent threats against politicians"}},{"i":"R2773","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Xai asks court to strip alleged grok deepfake nudes victims of anonymity","s":"Four people suing Elon Musk's AI firm under pseudonyms due to the risks of being identified may face a difficult choice: Reveal your real names, or drop the lawsuit. Elon Musk’s artificial intelligence firm, xAI , is requesting the public identification of four people who allegedly had deepfake sexualized images created of them using Grok —including one apparently targeted with sexualized deepfake images of them as a child, according to recently filed court documents On May 29, the four main claimants in a federal class-action lawsuit—currently identified as South Carolina Doe, South Carolina Roe, New Jersey Doe, and Ohio Doe—described in affidavits the emotional distress they had suffered after the alleged deepfakes were created earlier this year.","u":"https://www.wired.com/story/xai-asks-court-to-strip-alleged-grok-deepfake-nudes-victims-of-anonymity/","d":"2026-06-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-29","organization":"xAI (Elon Musk's artificial intelligence firm)","aiSystem":"Grok","affectedGroup":"Four people","action":"Deepfake images were allegedly created of them","consequence":"Emotional distress and potential public identification"}},{"i":"R2777","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla reveals new details about robotaxi crashes and the humans involved","s":"Remote operators (slowly) drove the automaker’s autonomous vehicles into a metal fence and a construction barricade, Tesla says. For more than a year, Tesla has shielded details about its robotaxi crashes from public view. Now, the company has published new details in a federal database about 17 incidents, which took place between July 2025 and March 2026. In at least two of them, Tesla’s human employees appear to have played a hand in the crashes by remotely driving the otherwise autonomous cars into objects on the street. In both crashes, which happened in Austin, “safety monitors” were in the vehicles’ passenger seats to oversee the still-fledgling self-driving tech , and no passengers were riding in the cars.","u":"https://www.wired.com/story/tesla-reveals-new-details-about-robotaxi-crashes-and-the-humans-involved/","d":"2026-05-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-20 to 2026-03-31","organization":"Tesla","aiSystem":"Autonomous vehicles","affectedGroup":"Human employees","action":"Remote operation of autonomous vehicles","consequence":"Crashes resulting in property damage and potential injuries"}},{"i":"R2778","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Meta employee protest mouse tracking surveillance ai training","s":"Meta employees in the US and UK are organizing against corporate software that tracks workers’ keystrokes and mouse activity. Meta’s decision to track employee keystrokes and mouse data is causing an uproar within the company. “Selfishly, I don't want my screen scraped because it feels like an invasion of my privacy,” wrote an engineer in an internal post seen by nearly 20,000 coworkers this week. “But zooming out, I don't want to live in a world where humans—employees or otherwise—are exploited for their training data.” The message aimed to rally support for a petition circulating inside the company since last Thursday that demands an end to what Meta calls the Model Capability Initiative.","u":"https://www.wired.com/story/meta-employee-protest-mouse-tracking-surveillance-ai-training/","d":"2026-05-14","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-14","organization":"Meta (Facebook)","aiSystem":"Keystroke tracking and mouse activity monitoring","affectedGroup":"Meta employees in the US and UK","action":"Track keystrokes and mouse activity","consequence":"Privacy invasion, feeling of being exploited for training data"}},{"i":"R2779","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Chevron wants school district tax break data center power plant texas","s":"The move could save the oil company hundreds of millions, even as Texas lawmakers start looking at reining in incentives for data centers. A major oil company is seeking a state tax break in Texas worth hundreds of millions of dollars to build a massive power plant. The energy won’t be going to residential customers, though. Instead, the gas plant will be used to power a data center whose eventual tenant could be Microsoft. Chevron subsidiary Energy Forge One has filed an application with the State Comptroller’s board to obtain a tax abatement for a power plant it’s building in West Texas. In late January, the comptroller’s office made a recommendation to support the application’s approval—the first such approval under the program for a power plant intended solely for data center use.","u":"https://www.wired.com/story/chevron-wants-school-district-tax-break-data-center-power-plant-texas/","d":"2026-05-11","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-11","organization":"Chevron subsidiary Energy Forge One","aiSystem":"Data center","affectedGroup":"Residents of West Texas","action":"Built a power plant to power a data center","consequence":"Potential exposure of residents' data to the data center"}},{"i":"R2780","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Security news this week hackable robot lawnmower unlocks a new nightmare","s":"Plus: Meta officially kills encrypted Instagram DMs, the Trump administration targets “violent left wing extremists,” leaked documents reveal Russia's school for elite hackers, and more. Cramming for finals is bad enough without the platform you use to do your schoolwork suddenly shutting down. Unfortunately for countless students across the US, that’s exactly what they faced on Thursday after Canvas went into “maintenance mode” following a ransomware attack on education tech firm Instructure. Hackers using the name ShinyHunters claimed responsibility for the breach, and experts say the chaos they caused shows how far these actors will go to extort their victims.","u":"https://www.wired.com/story/security-news-this-week-hackable-robot-lawnmower-unlocks-a-new-nightmare/","d":"2026-05-09","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-05-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-09","organization":"Instructure","aiSystem":"Not specified in report","affectedGroup":"Students across the US","action":"Canvas went into maintenance mode","consequence":"Students faced a shutdown of their schoolwork platform"}},{"i":"R2781","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Waymo trying to crack down on solo kids in driverless cars","s":"As adult riders report new age-verification checks, the self-driving car company says it’s continuing to “refine” its system in places where kids aren’t allowed to ride alone. By law, autonomous vehicles aren’t allowed to carry unaccompanied minors in California. Waymo , Alphabet’s self-driving-car company, doesn’t allow kids under 18 to ride alone anywhere outside of metro Phoenix, Arizona. But that hasn’t stopped some time-strapped parents from using their own accounts to transport their kids to school, extracurricular activities, and even social outings. Some have reported that the lack of drivers makes them feel safer.","u":"https://www.wired.com/story/waymo-trying-to-crack-down-on-solo-kids-in-driverless-cars/","d":"2026-05-01","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-05-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-05-01","organization":"Waymo, Alphabet's self-driving-car company","aiSystem":"self-driving car technology","affectedGroup":"parents of children under 18","action":"attempting to use self-driving cars for solo trips with children","consequence":"feeling unsafe due to lack of human drivers"}},{"i":"R2782","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Elon musk distill openai models partly xai","s":"While answering questions under oath, Musk argued it’s standard practice for AI labs to use their competitors’ models. While testifying on Thursday in federal court, Elon Musk seemed to indicate that his AI lab may have used OpenAI’s models to train xAI’s own. He touched upon the topic while sitting on the witness stand answering cross-examination questions from an OpenAI attorney amid his ongoing legal battle against the ChatGPT-maker. This is the exchange, as best as WIRED could capture it: OpenAI Lawyer William Savitt: Do you know what distillation is? Musk: It means to use one AI model to train another AI model.","u":"https://www.wired.com/story/elon-musk-distill-openai-models-partly-xai/","d":"2026-04-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-30","organization":"Elon Musk's AI lab","aiSystem":"xAI's own AI model","affectedGroup":"Not specified in report","action":"Used one AI model to train another AI model","consequence":"Not specified in report"}},{"i":"R2785","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Security news this week discord sleuths gained unauthorized access to anthropics mythos","s":"Plus: Spy firms tap into a global telecom weakness to track targets, 500,000 UK health records go up for sale on Alibaba, Apple patches a revealing notification bug, and more. As researchers and practitioners debate the impact that new AI models will have on cybersecurity, Mozilla said on Tuesday it used early access to Anthropic's Mythos Preview to find and fix 271 vulnerabilities in its new Firefox 150 browser release. Meanwhile, researchers identified a group of moderately successful North Korean hackers using AI for everything from vibe coding malware to creating fake company websites—stealing up to $12 million in three months.","u":"https://www.wired.com/story/security-news-this-week-discord-sleuths-gained-unauthorized-access-to-anthropics-mythos/","d":"2026-04-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-25","organization":"Mozilla","aiSystem":"AI-driven cyberattack","affectedGroup":"Individuals whose data was accessed or compromised","action":"Used Anthropic's Mythos Preview to identify and fix vulnerabilities","consequence":"Found and fixed 271 vulnerabilities in Firefox 150 browser release"}},{"i":"R2786","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Pope tweets ai generated pangram chrome extension","s":"Pangram Labs’ updated Chrome extension puts warning labels on AI slop as you scroll your social feeds. On Monday, a brand-new Reddit account popped up on the widely read forum r/AmItheAsshole, where users have their personal disputes arbitrated by strangers. This particular user asked if they had crossed a line by “refusing to babysit my stepmother’s kids because I have my own job and responsibilities.” The post itself was succinct, straightforward, and grammatically clean, explaining a situation in which the person’s stepmother and father often expected them to provide childcare on little notice, eventually leading to an argument.","u":"https://www.wired.com/story/pope-tweets-ai-generated-pangram-chrome-extension/","d":"2026-04-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-22","organization":"Pangram Labs","aiSystem":"AI-generated content","affectedGroup":"Reddit users","action":"AI-generated content displayed in social feeds","consequence":"Privacy intrusion due to AI-generated warnings"}},{"i":"R2787","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Ai generated maga girls","s":"A med student says he’s made thousands of dollars selling photos and videos of a young conservative woman he created using generative tools. He’s not alone. Like many medical school students, Sam was broke. The 22-year-old aspiring orthopedic surgeon from northern India got some money from his parents, but he says he spent most of it subsidizing his licensing exams, and he’s still saving up to hopefully emigrate to the US after graduation. So he started searching for ways to make additional money online. Sam, who requested a pseudonym to avoid jeopardizing his medical career and immigration status, tried a few things, with varying degrees of legitimacy and success.","u":"https://www.wired.com/story/ai-generated-maga-girls/","d":"2026-04-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-21","organization":"Not specified in report","aiSystem":"Generative AI","affectedGroup":"Medical students","action":"Created and sold photos and videos of a young conservative woman using generative tools","consequence":"Made thousands of dollars and potentially jeopardized medical career and immigration status"}},{"i":"R2790","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Security news this week your push notifications arent safe from the fbi","s":"Plus: Iran’s internet blackout hits the 1,000-hour mark, cryptocurrency scams result in a record amount of money stolen from Americans, and more. Amid horrific threats from United States president Donald Trump as the US and Iran negotiated a ceasefire, the US government warned this week that Iran-linked hackers were carrying out attacks against US energy and water infrastructure targets. With nearly one in five people in Lebanon displaced by Israeli attacks, the government is attempting to manage the crisis without modern digital infrastructure and an emergency system that is barely hanging on. Plus, a WIRED analysis looked at Syrian government account hijacks in March and the inadequacies they expose in Syria’s baseline cybersecurity defenses.","u":"https://www.wired.com/story/security-news-this-week-your-push-notifications-arent-safe-from-the-fbi/","d":"2026-04-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-11","organization":"Iran-linked hackers","aiSystem":"Not specified in report","affectedGroup":"US energy and water infrastructure targets","action":"carrying out attacks","consequence":"horrific threats, potential damage to critical infrastructure"}},{"i":"R2791","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Openai backs bill exempt ai firms model harm lawsuits","s":"The ChatGPT-maker testified in favor of an Illinois bill that would limit when AI labs can be held liable—even in cases where their products cause “critical harm.” OpenAI is throwing its support behind an Illinois state bill that would shield AI labs from liability in cases where AI models are used to cause serious societal harms, such as death or serious injury of 100 or more people or at least $1 billion in property damage. The effort seems to mark a shift in OpenAI’s legislative strategy Until now, OpenAI has largely played defense, opposing bills that could have made AI labs liable for their technology’s harms.","u":"https://www.wired.com/story/openai-backs-bill-exempt-ai-firms-model-harm-lawsuits/","d":"2026-04-10","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-10","organization":"OpenAI","aiSystem":"AI models","affectedGroup":"AI labs","action":"Supporting legislation to exempt from liability","consequence":"Potential liability for critical harm caused by AI models"}},{"i":"R2792","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Army developing ai system victor chatbot soldiers","s":"The AI system, trained on real military data, is meant to give soldiers mission-critical information. The US Army is developing AI models trained on data from real missions, with the goal of deploying a chatbot specifically for soldiers. “We have all of these lessons learned from missions like the Ukraine-Russia War and Operation Epic Fury,” says Alex Miller, the Army’s chief technology officer, in an interview with WIRED. “There is a huge amount of knowledge available.” Miller showed WIRED a prototype of the system, called Victor, that combines a Reddit-like forum with a chatbot called VictorBot to help troops surface useful information, like the best way to configure electromagnetic warfare systems for a particular mission.","u":"https://www.wired.com/story/army-developing-ai-system-victor-chatbot-soldiers/","d":"2026-04-08","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-04-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-08","organization":"US Army","aiSystem":"AI models trained on data from real missions","affectedGroup":"Soldiers","action":"deploy a chatbot specifically for soldiers","consequence":"miss out on mission-critical information"}},{"i":"R2793","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Meta pauses work with mercor after data breach puts ai industry secrets at risk","s":"Major AI labs are investigating a security incident that impacted Mercor, a leading data vendor. The incident could have exposed key data about how they train AI models. Meta has paused all its work with the data contracting firm Mercor while it investigates a major security breach that impacted the startup, two sources confirmed to WIRED. The pause is indefinite, the sources said. Other major AI labs are also reevaluating their work with Mercor as they assess the scope of the incident, according to people familiar with the matter. Mercor is one of a few firms that OpenAI , Anthropic , and other AI labs rely on to generate training data for their models.","u":"https://www.wired.com/story/meta-pauses-work-with-mercor-after-data-breach-puts-ai-industry-secrets-at-risk/","d":"2026-04-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-04","organization":"Meta (Facebook)","aiSystem":"AI models","affectedGroup":"AI labs and data vendors","action":"Paused work with Mercor","consequence":"Potential exposure of key data about AI model training"}},{"i":"R2794","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Security news this week hackers are posting the claude code leak with bonus malware","s":"Plus: The FBI says a recent hack of its wiretap tools poses a national security risk, attackers stole Cisco source code as part of an ongoing supply chain hacking spree, and more. Customs and Border Protection may want to remember to protect its sensitive facility information. Using basic Google searches, WIRED discovered flashcards made by users of the online learning platform Quizlet that contained gate codes to CBP facilities and more. In a rare move, Apple this week released “backported” patches for iOS 18 to protect millions of people still using the older operating system from the DarkSword hacking technique that was found in use in the wild.","u":"https://www.wired.com/story/security-news-this-week-hackers-are-posting-the-claude-code-leak-with-bonus-malware/","d":"2026-04-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-04-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-04-04","organization":"US Federal Bureau of Investigation (FBI)","aiSystem":"Not specified in report","affectedGroup":"US citizens","action":"Attackers stole Cisco source code and gate codes to CBP facilities","consequence":"Potential unauthorized access to sensitive CBP facility information"}},{"i":"R2795","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"A school district tried to help train waymos to stop for school buses it didnt work","s":"The incidents in Austin raise questions about how self-driving cars “learn” and adapt to their surroundings. One of the purported advantages of self-driving car tech is that every car can learn from one vehicle’s mistakes. Here’s how Waymo puts it on its website : “The Waymo Driver learns from the collective experiences gathered across our fleet, including previous hardware generations.” But in Austin, Waymo’s vehicles struggled for months to learn how to stop for school buses as drivers picked up and dropped off children. An official with the Austin Independent School District (AISD) alleged that the vehicles had, in at least 19 instances, “illegally and dangerously” passed the district’s school buses while their red lights were flashing and their stop arms were extended rather than coming to complete stops, as the law requires.","u":"https://www.wired.com/story/a-school-district-tried-to-help-train-waymos-to-stop-for-school-buses-it-didnt-work/","d":"2026-03-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-29","organization":"Waymo","aiSystem":"Waymo's self-driving car technology","affectedGroup":"Austin Independent School District (AISD) and children being picked up/dropped off by school buses","action":"Waymo's self-driving cars failed to stop for school buses as required by law","consequence":"Children and school buses were placed at risk of injury due to illegal and dangerous passing of school buses"}},{"i":"R2796","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Get down get down six months of hiding from ice","s":"A family in Chicago has been terrified to leave their apartment. Agents could be anywhere. At around 7:30 am on Halloween, Ava and Sam were taking their two kids to school when their upstairs neighbor rushed toward them on the street. “You shouldn’t be out right now,” she told them. ICE vans were just around the corner. Ava felt her body go numb. The day before, her coworker—another undocumented woman she cleaned houses with—told her about how she’d seen an ICE van parked behind her while she was taking her lunch break in her car. All the images Ava and Sam had been watching, the ones that popped up on their TikTok of ICE agents arresting people shopping at Home Depots and Walmarts, all the things they’d been hearing in bits and pieces from her husband’s coworkers, their caseworker, her children’s school teachers about what to do if ICE comes—it was finally here at their doorstep.","u":"https://www.wired.com/story/get-down-get-down-six-months-of-hiding-from-ice/","d":"2026-03-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-24","organization":"ICE (Immigration and Customs Enforcement)","aiSystem":"Not specified in report","affectedGroup":"Undocumented women and families","action":"ICE vans were parked nearby","consequence":"Fear of ICE agents arriving at their doorstep"}},{"i":"R2798","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"How ai chatbots drove families to the brink and the lawyer fighting back","s":"After a series of suicides allegedly linked to AI chatbots, one lawyer is trying to hold companies like OpenAI accountable. Content warning: This story contains descriptions of self-harm. Cedric Lacey relied on a camera to check on his kids while he was working as a commercial van driver going to and back from Alabama. Each morning, he would tune into the feed of his living room to make sure his teenage son, Amaurie, and his 14-year-old daughter were packing up their bags and getting ready to leave for school. But one morning last June, Lacey didn’t see Amaurie up and about. Concerned, he called home, only to find out that his 17-year-old had hanged himself.","u":"https://www.wired.com/story/how-ai-chatbots-drove-families-to-the-brink-and-the-lawyer-fighting-back/","d":"2026-03-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"June 2026","organization":"Not specified in report","aiSystem":"AI chatbots","affectedGroup":"Individuals (specifically Cedric Lacey and his family)","action":"Used AI chatbots to monitor children's behavior","consequence":"Led to the suicide of Cedric Lacey's son"}},{"i":"R2800","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Teens are using ai fueled slander pages to mock their teachers","s":"Viral student-run TikTok and Instagram accounts are using AI to make memes of school faculty comparing them to figures like Jeffrey Epstein and Benjamin Netanyahu. The video opens with a school superintendent lip-syncing a love song , but he’s not the only performer. AI-generated versions of Israeli prime minister Benjamin Netanyahu and deceased sex offender Jeffrey Epstein join him on the ballad—a splice between Will Joseph Cook’s “Be Around Me” and a rewrite of the song by Beth McCarthy on TikTok —with Epstein mouthing the words, “Oh my god, did he call her baby, maybe?” The clip, posted to the Instagram account @thewyliefiles , has been liked more than 107,000 times.","u":"https://www.wired.com/story/teens-are-using-ai-fueled-slander-pages-to-mock-their-teachers/","d":"2026-03-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-11","organization":"Student-run TikTok and Instagram accounts","aiSystem":"AI-generated content","affectedGroup":"School faculty","action":"Generated and shared memes","consequence":"Exposure to misleading content"}},{"i":"R2802","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Openai defense department ban military use microsoft","s":"Sources allege the Defense Department experimented with Microsoft’s version of OpenAI technology before the ChatGPT-maker lifted its prohibition on military applications. OpenAI CEO Sam Altman is still in the hot seat this week after his company signed a deal with the US military. OpenAI employees have criticized the move, which came after Anthropic’s roughly $200 million contract with the Pentagon imploded , and asked Altman to release more information about the agreement. Altman admitted it looked “sloppy” in a social media post While this incident has become a major news story, it may just be the latest and most public example of OpenAI creating vague policies around how the US military can access its AI.","u":"https://www.wired.com/story/openai-defense-department-ban-military-use-microsoft/","d":"2026-03-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-03-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-03-05","organization":"Defense Department, OpenAI, Anthropic","aiSystem":"OpenAI technology","affectedGroup":"US military personnel, civilians potentially exposed to sensitive information","action":"Experimented with Microsoft's version of OpenAI technology","consequence":"Potential unauthorized access to sensitive information, vague policies around AI usage by military"}},{"i":"R2803","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Security news this week area man accidentally hacks 6700 camera enabled robot vacuums","s":"Plus: The top US cyber agency falls into shambles, AI models develop an upsetting penchant for nuclear weapons, and more. Congressional Democrats on the Joint Economic Committee released a report this week pinpointing more than $20.9 billion in consumer losses stemming from identity theft that came out of four major breaches of data broker firms. US senator Maggie Hassan launched the investigation in August after an investigation by The Markup and CalMatters , copublished by WIRED, found that some data brokers were hiding opt-out tools from Google and other search engines. The US Department of Justice’s recent release of 3 million documents related to convicted sex offender Jeffrey Epstein included grand jury subpoenas to Google that shed light on how federal investigators interact with tech companies and how they respond to government requests for information.","u":"https://www.wired.com/story/security-news-this-week-area-man-accidentally-hacks-6700-camera-enabled-robot-vacuums/","d":"2026-02-28","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-28","organization":"US Department of Justice","aiSystem":"Not specified in report","affectedGroup":"People whose data was breached","action":"Released 3 million documents related to Jeffrey Epstein's conviction","consequence":"Shed light on interactions between tech companies and federal investigators"}},{"i":"R2806","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Government docs reveal new details about tesla and waymo robotaxi programs","s":"Self-driving-vehicle companies are revealing new details about their safety-critical “remote assistance” programs—but questions remain. Are self-driving vehicles really just big, remote-controlled cars, with nameless and faceless people in far-off call centers piloting the things from behind consoles? As the vehicles and their science-fiction-like software expand to more cities, the conspiracy theory has rocketed around group chats and TikToks. It’s been powered, in part, by the reluctance of self-driving car companies to talk in specifics about the humans who help make their robots go. But this month, in government documents submitted by Alphabet subsidiary Waymo and electric-auto maker Tesla , the companies have revealed more details about the people and programs that help the vehicles when their software gets confused.","u":"https://www.wired.com/story/government-docs-reveal-new-details-about-tesla-and-waymo-robotaxi-programs/","d":"2026-02-20","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-20","organization":"Alphabet subsidiary Waymo and electric-auto maker Tesla","aiSystem":"self-driving vehicles","affectedGroup":"people who help make the robots go","action":"reveal more details about the people and programs that help the vehicles","consequence":"questions remain about the safety-critical 'remote assistance' programs"}},{"i":"R2807","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"The search engine for onlyfans models who look like your crush","s":"Presearch’s “Doppelgänger” is trying to help people discover adult creators rather than use nonconsensual deepfakes. For three days in February, porn star Alix Lynx flew to Miami for her first exclusive creator gathering where she was in full grind mode: shooting Reels and talking strategy with other creators. “It was kind of like SoHo House for OnlyFans girls ,” she says of the experience, which is called The Circle and drew more than a dozen sex workers, including Remy LaCroix and Forrest Smith. Lynx, who is a former webcam model turned OnlyFans starlet, has a combined 2 million followers across Instagram , TikTok , and X She joined OnlyFans in 2017 with “the luxury of having my own following,” she says, but those numbers haven’t always translated to subscriptions.","u":"https://www.wired.com/story/the-search-engine-for-onlyfans-models-who-look-like-your-crush/","d":"2026-02-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-03","organization":"Presearch","aiSystem":"Deepfake generation technology","affectedGroup":"Adult creators, particularly sex workers","action":"Used deepfake technology to create and distribute images or videos","consequence":"Generated non-consensual deepfakes"}},{"i":"R2809","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Ai lab scout ai is using ai agents to blow things up","s":"Scout AI is using technology borrowed from the AI industry to power lethal weapons—and recently demonstrated its explosive potential. Like many Silicon Valley companies today, Scout AI is training large AI models and agents to automate chores. The big difference is that instead of writing code, answering emails, or buying stuff online, Scout AI’s agents are designed to seek and destroy things in the physical world with exploding drones. In a recent demonstration, held at an undisclosed military base in central California, Scout AI’s technology was put in charge of a self-driving off-road vehicle and a pair of lethal drones.","u":"https://www.wired.com/story/ai-lab-scout-ai-is-using-ai-agents-to-blow-things-up/","d":"2026-02-18","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-02-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-18","organization":"Scout AI","aiSystem":"AI-powered lethal weapons","affectedGroup":"Military personnel, civilians near the military base","action":"Deploying lethal drones equipped with explosives","consequence":"Potential for explosions and casualties"}},{"i":"R2813","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Meta child safety trial new mexico attorney general","s":"Attorney general Raúl Torrez is accusing the tech giant of failing to protect minors on Facebook and Instagram. Today, Meta went to trial in the state of New Mexico for allegedly failing to protect minors from sexual exploitation on its apps, including Facebook and Instagram The state claims that Meta violated New Mexico’s Unfair Practices Act by implementing design features and algorithms that created dangerous conditions for users. Now, more than two years after the case was filed, opening arguments have begun in Santa Fe. It’s a big week for Meta in court: A landmark social media trial kicks off in California today as well, the nation’s first legal test of social media addiction That case is part of a “JCCP,” or judicial council coordinated proceedings, that brings together many civil suits that focus on similar issues.","u":"https://www.wired.com/story/meta-child-safety-trial-new-mexico-attorney-general/","d":"2026-02-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-10","organization":"Meta","aiSystem":"Facebook and Instagram","affectedGroup":"Minors","action":"Created dangerous conditions for users","consequence":"Violated New Mexico's Unfair Practices Act"}},{"i":"R2814","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Hhs is making an ai tool to create hypotheses about vaccine injury claims","s":"Experts worry Robert F. Kennedy Jr.’s Health Department will use an internal AI tool to analyze vaccine injury claims in a way that furthers his anti-vaccine agenda. The US Department of Health and Human Services is developing a generative artificial intelligence tool to find patterns across data reported to a national vaccine monitoring database and to generate hypotheses on the negative effects of vaccines, according to an inventory released last week of all use cases the agency had for AI in 2025. The tool has not yet been deployed, according to the HHS document, and an AI inventory report from the previous year shows that it has been in development since late 2023.","u":"https://www.wired.com/story/hhs-is-making-an-ai-tool-to-create-hypotheses-about-vaccine-injury-claims/","d":"2026-02-04","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2026-02-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-04","organization":"US Department of Health and Human Services","aiSystem":"Generative artificial intelligence tool","affectedGroup":"People making vaccine injury claims","action":"Generate hypotheses on the negative effects of vaccines","consequence":"Exposure to misleading content"}},{"i":"R2816","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Meta child safety trial ask judge bar mental health harvard","s":"The trial starts soon in New Mexico’s case against Meta—and the company is pulling out all the stops to protect its reputation. The company has petitioned the judge to exclude certain research studies and articles around social media and youth mental health; any mention of a recent high-profile case involving teen suicide and social media content; and any references to Meta’s financial resources, the personal activities of employees, and Mark Zuckerberg’s time as a student at Harvard University. Meta’s requests to exclude information, known as motions in limine, are a standard part of pretrial proceedings, in which a party can ask a judge to determine in advance which evidence or arguments are permissible in court.","u":"https://www.wired.com/story/meta-child-safety-trial-ask-judge-bar-mental-health-harvard/","d":"2026-01-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-21","organization":"Meta (Facebook)","aiSystem":"Meta's social media platform","affectedGroup":"Teenagers","action":"Used social media platform to expose teenagers to potentially harmful content","consequence":"Potential negative impact on teenagers' mental health"}},{"i":"R2817","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Elon musks grok undressing problem isnt fixed","s":"X has placed more restrictions on Grok’s ability to generate explicit AI images, but tests show that the updates have created a patchwork of limitations that fail to fully address the issue. Elon Musk’s X has introduced new restrictions stopping people from editing and generating images of real people in bikinis or other “revealing clothing.” The change in policy on Wednesday night follows global outrage at Grok being used to generate thousands of harmful nonconsensual “undressing” photos of women and sexualized images of apparent minors on X. However, while it appears that some safety measures have finally been introduced to Grok’s image generation on X, the stand-alone Grok app and website seem to still be able to generate “undress”-style images and pornographic content, according to multiple tests by researchers, WIRED, and other journalists.","u":"https://www.wired.com/story/elon-musks-grok-undressing-problem-isnt-fixed/","d":"2026-01-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-15","organization":"X (Twitter)","aiSystem":"Grok's image generation system","affectedGroup":"Women, apparent minors, users of Grok app and website","action":"Generated and distributed AI-generated explicit images","consequence":"Privacy intrusion, potential harm to individuals"}},{"i":"R2818","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Openai contractor upload real work documents ai agents","s":"To prepare AI agents for office work, the company is asking contractors to upload projects from past jobs, leaving it to them to strip out confidential and personally identifiable information. OpenAI is asking third-party contractors to upload real assignments and tasks from their current or previous workplaces so that it can use the data to evaluate the performance of its next-generation AI models , according to records from OpenAI and the training data company Handshake AI obtained by WIRED. The project appears to be part of OpenAI’s efforts to establish a human baseline for different tasks that can then be compared with AI models.","u":"https://www.wired.com/story/openai-contractor-upload-real-work-documents-ai-agents/","d":"2026-01-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-10","organization":"OpenAI","aiSystem":"OpenAI's AI models","affectedGroup":"Third-party contractors","action":"Upload real assignments and tasks from their current or previous workplaces","consequence":"Exposure of confidential and personally identifiable information"}},{"i":"R2819","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Security news this week ice can now spy on every phone in your neighborhood","s":"Plus: Iran shuts down its internet amid sweeping protests, an alleged scam boss gets extradited to China, and more. After a federal agent shot and killed 37-year-old Renee Good in Minneapolis on Wednesday, WIRED surfaced December federal court testimony from the reported ICE shooter, Jonathan Ross. In it, he said he was a firearms trainer and that he has had “hundreds” of encounters with drivers in a professional capacity during enforcement actions. Separately, we looked at how the tactics behind protest policing are moving toward intentional antagonism If you haven’t seen it, here’s our guide to protesting safely in the age of surveillance Meanwhile, the artificial-intelligence-powered chatbot Grok, developed by Elon Musk’s xAI, was everywhere this week because the platform has been expanding access to digital “undressing” capabilities that allow users to generate naked images of…","u":"https://www.wired.com/story/security-news-this-week-ice-can-now-spy-on-every-phone-in-your-neighborhood/","d":"2026-01-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2026-01-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-01-10","organization":"xAI (developed by Elon Musk)","aiSystem":"Artificial-intelligence-powered chatbot Grok","affectedGroup":"Users","action":"Generated naked images of users","consequence":"Exposure to misleading content"}},{"i":"R2821","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Expired tired wired data centers","s":"The battle for AI dominance has left a large footprint—and it’s only getting bigger and more expensive. When Sam Altman said one year ago that OpenAI ’s Roman Empire is the actual Roman Empire , he wasn’t kidding. In the same way that the Romans gradually amassed an empire of land spanning three continents and one-ninth of the Earth’s circumference, the CEO and his cohort are now dotting the planet with their own latifundia—not agricultural estates, but AI data centers Tech executives like Altman, Nvidia CEO Jensen Huang , Microsoft CEO Satya Nadella , and Oracle cofounder Larry Ellison are fully bought in to the idea that the future of the American (and possibly global) economy are these new warehouses stocked with IT infrastructure.","u":"https://www.wired.com/story/expired-tired-wired-data-centers/","d":"2025-12-28","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-28","organization":"Tech executives like Sam Altman, Nvidia CEO Jensen Huang, Microsoft CEO Satya Nadella, and Oracle cofounder Larry Ellison","aiSystem":"AI data centers","affectedGroup":"Individuals whose data is processed in these data centers","action":"Data centers are being built and operated to house IT infrastructure","consequence":"Increased privacy risks due to the collection and processing of personal data in these facilities"}},{"i":"R2822","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Pinterst ai slop content","s":"A surge of AI-generated content is frustrating Pinterest users and left some questioning whether the platform still works at all. For five years, Caitlyn Jones has used Pinterest on a weekly basis to find recipes for her son. In September, Jones spotted a creamy chicken and broccoli slow-cooker recipe, sprinkled with golden cheddar and a pop of parsley. She quickly looked at the ingredients and added them to her grocery list. But just as she was about to start cooking, having already bought everything, one thing stood out: The recipe told her to start by “logging” the chicken into the slow cooker. Confused, she clicked on the recipe blog’s About page.","u":"https://www.wired.com/story/pinterst-ai-slop-content/","d":"2025-12-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-24","organization":"Pinterest","aiSystem":"AI-generated content","affectedGroup":"Users of Pinterest","action":"Generated and displayed recipes with misleading instructions","consequence":"Users confused and misled about how to use the slow cooker"}},{"i":"R2824","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Security news this week ai toys for kids talk about sex drugs and chinese propaganda","s":"Plus: Travelers to the US may have to hand over five years of social media history, South Korean CEOs are resigning due to cyberattacks, and more. Two people allegedly linked to China’s infamous Salt Typhoon espionage hacking group seem to have previously received training through Cisco’s prominent, long-running networking academy Meanwhile, warnings are increasingly emerging from United States lawmakers in Congress that safeguards on expanded US wiretap powers have been failing , allowing US intelligence agencies to access more of Americans’ data without adequate constraints. If you’ve been having trouble keeping track of all of the news and data coming out about infamous sex offender Jeffrey Epstein, WIRED published a guide this week to who’s releasing Epstein documents and what those troves contain , as well as which documents are soon to be revealed.","u":"https://www.wired.com/story/security-news-this-week-ai-toys-for-kids-talk-about-sex-drugs-and-chinese-propaganda/","d":"2025-12-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-13","organization":"Cisco's prominent, long-running networking academy","aiSystem":"Not specified in report","affectedGroup":"Two people allegedly linked to China’s infamous Salt Typhoon espionage hacking group","action":"Received training through Cisco’s prominent, long-running networking academy","consequence":"May have to hand over five years of social media history"}},{"i":"R2825","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Big interview event matthew prince cloudflare","s":"Cloudflare CEO Matthew Prince claims the internet infrastructure company’s efforts to block AI crawlers are already seeing big results. As the large language models powering generative AI tools slurp up ever more data across the web, Cloudflare cofounder and CEO Matthew Prince said at WIRED’s Big Interview event in San Francisco on Thursday that the internet infrastructure company has blocked more than 400 billion AI bot requests for its customers since July 1. The action comes after the company announced a Content Independence Day in July—an initiative with prominent publishers and AI firms to block AI crawlers by default on content creators’ work unless the AI companies pay for access.","u":"https://www.wired.com/story/big-interview-event-matthew-prince-cloudflare/","d":"2025-12-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-12-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-12-05","organization":"Cloudflare","aiSystem":"AI crawlers","affectedGroup":"Content creators","action":"Blocked AI bot requests","consequence":"Privacy risks"}},{"i":"R2826","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"The viral doordash girl saga unearthed a nightmare for black creators","s":"A delivery driver posted a TikTok alleging she had been sexually assaulted by a customer. The deepfakes that followed reveal a growing digital blackface problem. When DoorDash delivery driver Livie Rose Henderson posted a video alleging that one of her customers sexually assaulted her in October, it set off a firestorm of reactions. Henderson’s TikTok claimed that when she was dropping off a delivery in Oswego, New York, she found a customer’s front door wide open and inside, a man on the couch with his pants and underwear pulled down to his ankles. Henderson was dubbed the “DoorDash Girl,” and her video accrued tens of millions of views, including some supportive and consoling responses to what she said she had endured on the job as a young woman.","u":"https://www.wired.com/story/the-viral-doordash-girl-saga-unearthed-a-nightmare-for-black-creators/","d":"2025-11-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10","organization":"DoorDash","aiSystem":"Deepfake technology","affectedGroup":"Young women working as delivery drivers","action":"Generated and distributed misleading content","consequence":"Exposure to false allegations and harmful misinformation"}},{"i":"R2827","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Micron superfab evicts 91 year old new york","s":"Azalia King was the last holdout preventing the construction of a Micron \"megafab.\" Onondaga County authorities threatened to use eminent domain to take her home away by force. Azalia King moved into an upstate New York home surrounded by sprawling cattle pastures around 1965, about the time that mass production of the world’s first microchips began. Now, 60 years later, the 91-year-old is on the verge of losing her home to make way for what could become the largest chipmaking complex in the US. Local authorities threatened to exercise their power of eminent domain, or taking land for public benefit, to forcibly uproot King and proceed with construction on a $100 billion campus where US tech giant Micron plans to make memory chips for use in a variety of electronics.","u":"https://www.wired.com/story/micron-superfab-evicts-91-year-old-new-york/","d":"2025-11-24","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-24","organization":"Onondaga County authorities","aiSystem":"Not specified in report","affectedGroup":"Azalia King","action":"forced uprooting of Azalia King","consequence":"loss of home"}},{"i":"R2828","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Security news this week us border patrol is spying on millions of american drivers","s":"Plus: The SEC lets SolarWinds off the hook, Microsoft stops a historic DDoS attack, and FBI documents reveal the agency spied on an immigration activist Signal group in New York City. Eight years after a researcher warned WhatsApp that it was possible to extract user phone numbers en masse from the Meta-owned app, another team of researchers found that they could still do exactly that using a similar technique. The issue stems from WhatsApp’s discovery feature, which allows someone to enter a person’s phone number to see if they’re on the app. By doing this billions of times—which WhatsApp did not prevent—researchers from the University of Vienna uncovered what they’re calling “the most extensive exposure of phone numbers” ever Vaping is a major problem in US high schools.","u":"https://www.wired.com/story/security-news-this-week-us-border-patrol-is-spying-on-millions-of-american-drivers/","d":"2025-11-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-11-22","organization":"US Border Patrol, FBI","aiSystem":"Not specified in report","affectedGroup":"Immigration activist","action":"Spied on an immigration activist","consequence":"Exposure of personal information"}},{"i":"R2830","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Scam ads are flooding social media these former meta staffers have a plan","s":"Rob Leathern and Rob Goldman, who both worked at Meta, are launching a new nonprofit that aims to bring transparency to an increasingly opaque, scam-filled social media ecosystem. When billionaire Dutch TV producer John de Mol sued Facebook in 2019 over its alleged failure to stop scammers from using his image in deceptive ads, the social media company sent Rob Leathern to Amsterdam to meet with Del Mol’s team and to speak with the media. “The people who push these kinds of ads are persistent, they are well funded, and they are constantly evolving their deceptive tactics to get around our systems,” Leathern told Reuters at the time.","u":"https://www.wired.com/story/scam-ads-are-flooding-social-media-these-former-meta-staffers-have-a-plan/","d":"2025-11-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-11-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2019","organization":"Meta (Facebook)","aiSystem":"Social media platforms","affectedGroup":"Consumers, especially those targeted by deceptive ads","action":"Used deceptive advertising tactics","consequence":"Exposure to misleading content"}},{"i":"R2831","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Greenhouse gas protocol caught in big techs friendly fire","s":"An ideological war over how tech giants can account for AI data center emissions has bled into the international arena. Last week’s request for public comment from the Greenhouse Gas Protocol (GHGP) doesn’t look like a major win for a tech giant to the naked eye. In fact, it seems almost clerical. But for Google and Microsoft, the announcement constitutes a considerable win in their years-long battle against their competitors over how to account for the carbon emissions of data centers and, by extension, AI. The announcement shows that the GHGP is one step closer to implementing a mandatory hourly accounting method for electricity emissions—a carbon-accounting system Google and Microsoft have advocated for since 2020 and 2021, respectively.","u":"https://www.wired.com/story/greenhouse-gas-protocol-caught-in-big-techs-friendly-fire/","d":"2025-10-30","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-30","organization":"Greenhouse Gas Protocol (GHGP), Google, Microsoft","aiSystem":"Carbon accounting systems for data centers and AI","affectedGroup":"Tech giants (Google, Microsoft)","action":"Announcement of a mandatory hourly accounting method for electricity emissions","consequence":"Advancement of carbon-accounting system advocated by Google and Microsoft"}},{"i":"R2832","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Donald trump ai slop white house","s":"How do AI videos end up on Donald Trump’s social media accounts? WIRED investigates. President Donald Trump , a septuagenarian known for his general avoidance of keyboards and computers , has somehow become America’s first generative AI president. The most infamous example of his experimentation with AI-generated videos came ahead of the No Kings protests earlier this month. In the clip, the president is decked out in full Top Gun gear, piloting a fighter jet bearing “KING TRUMP” on its side. Instead of a traditional pilot’s helmet, however, the president is wearing a literal crown, just in case the rest of the visuals were too subtle.","u":"https://www.wired.com/story/donald-trump-ai-slop-white-house/","d":"2025-10-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-29","organization":"Donald Trump","aiSystem":"Generative AI","affectedGroup":"General public","action":"Generated and posted misleading content","consequence":"Exposure to misleading information"}},{"i":"R2833","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Lee holloway devastating decline brilliant young coder","s":"Lee Holloway programmed internet security firm Cloudflare into being. Then he became apathetic, distant, and unpredictable—for a long time, no one could make sense of it. On Friday, September 13, 2019, Matthew Prince and Michelle Zatlyn, cofounders of the San Francisco internet security firm Cloudflare , stood on a slim marble balcony overlooking the floor of the New York Stock Exchange. A cluster of the company's executives stood near Prince, ready to shout out a countdown. “Louder! Loud!” Prince urged them. “Five! Four! Three! …” At 9:30 am sharp, the founders reached down to ring the exchange's famous bell, kicking off the day's trading and offering their 10-year-old company on the public market.","u":"https://www.wired.com/story/lee-holloway-devastating-decline-brilliant-young-coder/","d":"2025-10-28","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2019-09-13","organization":"Cloudflare","aiSystem":"Not specified in report","affectedGroup":"Matthew Prince and Michelle Zatlyn","action":"ring the exchange's famous bell","consequence":"offer their 10-year-old company on the public market"}},{"i":"R2834","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Ai teacher inside alpha school","s":"In Brownsville, Texas, some families found a buzzy new school’s methods—surveillance of kids, software in lieu of teachers—to be an education in and of itself. One day last fall, Kristine Barrios’ 9-year-old daughter got stuck on a lesson in IXL, the personalized learning software that served as her math teacher. She had to multiply three three-digit numbers without using a calculator. Then she had to do it again, her mom says, more than 20 times, without making mistakes. At Alpha School, the private microschool the girl and her younger brother attended in Brownsville, Texas, she had been working a grade level ahead of her age in math, Barrios says.","u":"https://www.wired.com/story/ai-teacher-inside-alpha-school/","d":"2025-10-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-27","organization":"Alpha School","aiSystem":"Personalized learning software (IXL)","affectedGroup":"Kristine Barrios' 9-year-old daughter and younger brother","action":"Software in lieu of teachers conducted surveillance and tracked students' progress","consequence":"Students were subjected to excessive and unnecessary repetitive practice without making mistakes"}},{"i":"R2835","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Ai therapist collective psyche","s":"As millions confide in ChatGPT about their most intimate problems, these relationships are even stranger, more moving, and more insidious than we've imagined. Quentin awoke on a thin mattress, beneath a collection of scavenged blankets, in an abandoned RV deep in the Arizona desert. A young pit bull lay curled up beside them in the mid-morning light. Sliding from their bed over to the driver’s seat, Quentin pulled an American Spirit cigarette from a pack on the dashboard beside a small bowl of crystals. Outside the RV’s dusted-over windshield stretched an expanse of reddish clay earth, a bright cloudless sky, and a few scattered and broken housing structures visible between them and the horizon line.","u":"https://www.wired.com/story/ai-therapist-collective-psyche/","d":"2025-10-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-27","organization":"Not specified in report","aiSystem":"ChatGPT","affectedGroup":"Quentin","action":"Used ChatGPT to share intimate problems","consequence":"Exposure of personal information and location"}},{"i":"R2836","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Chatbots are pushing sanctioned russian propaganda","s":"ChatGPT, Gemini, DeepSeek, and Grok are serving users propaganda from Russian-backed media when asked about the invasion of Ukraine, new research finds. OpenAI’s ChatGPT, Google’s Gemini, DeepSeek, and xAI’s Grok are pushing Russian state propaganda from sanctioned entities—including citations from Russian state media, sites tied to Russian intelligence or pro-Kremlin narratives—when asked about the war against Ukraine, according to a new report. Researchers from the Institute of Strategic Dialogue (ISD) claim that Russian propaganda has targeted and exploited data voids —where searches for real-time data provide few results from legitimate sources—to promote false and misleading information.","u":"https://www.wired.com/story/chatbots-are-pushing-sanctioned-russian-propaganda/","d":"2025-10-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-27","organization":"OpenAI, Google, xAI","aiSystem":"ChatGPT, Gemini, DeepSeek, Grok","affectedGroup":"Users","action":"Generated and provided false and misleading information","consequence":"Exposure to propaganda from Russian-backed media"}},{"i":"R2837","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Dhs wants a fleet of ai powered surveillance trucks","s":"US border patrol is asking companies to submit plans to turn standard 4x4 trucks into AI-powered watchtowers—combining radar, cameras, and autonomous tracking to extend surveillance on demand. The US Department of Homeland Security is seeking to develop a new mobile surveillance platform that fuses artificial intelligence , radar, high-powered cameras, and wireless networking into a single system, according to federal contracting records reviewed by WIRED. The technology would mount on 4x4 vehicles capable of reaching remote areas and transforming into rolling, autonomous observation towers, extending the reach of border surveillance far beyond its current fixed sites.","u":"https://www.wired.com/story/dhs-wants-a-fleet-of-ai-powered-surveillance-trucks/","d":"2025-10-24","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2025-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10-24","organization":"US Department of Homeland Security","aiSystem":"AI-powered surveillance system mounted on 4x4 vehicles","affectedGroup":"Border patrol agents, civilians near the US border","action":"Deploying AI-powered surveillance systems on 4x4 vehicles","consequence":"Extended surveillance capabilities, increased exposure to surveillance"}},{"i":"R2838","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Ftc removes blog posts about ai authored by by lina khan","s":"The Federal Trade Commission removed several blog posts in recent months about open source and potential risks to consumers from the rapid spread of commercial AI tools. In late July 2024, Lina Khan , then the chair of the US Federal Trade Commission, gave a speech at an event hosted by the San Francisco startup accelerator Y Combinator in which she positioned herself as an advocate for open source artificial intelligence. The event took place as California lawmakers were considering a landmark bill called SB 1047 that would have imposed new testing and safety requirements on AI companies. Critics of the legislation, which was later vetoed by California governor Gavin Newsom, argued it would hamper the development and release of open source AI models.","u":"https://www.wired.com/story/ftc-removes-blog-posts-about-ai-authored-by-by-lina-khan/","d":"2025-10-20","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07","organization":"California lawmakers, Federal Trade Commission","aiSystem":"open source artificial intelligence","affectedGroup":"consumers, AI companies","action":"removed blog posts","consequence":"hampered development and release of open source AI models"}},{"i":"R2839","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"How peter thiels secretive data company pushed into policing","s":"An investigation reveals the difficult issues police and communities face when they adopt Palantir’s data-scooping software. This story was originally published in Backchannel in August 2017. When Sergeant Lee DeBrabander marked a case confidential in the Long Beach drug squad’s Palantir data analysis system in November 2014, he expected key details to remain hidden from unauthorized users’ eyes. In police work, this can be crucial—a matter of life and death, even. It often involves protecting vulnerable witnesses, keeping upcoming operations hush hush, or protecting a fellow police officer who’s working undercover.","u":"https://www.wired.com/story/how-peter-thiels-secretive-data-company-pushed-into-policing/","d":"2025-10-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"November 2014","organization":"Long Beach drug squad and Palantir","aiSystem":"Palantir data-scooping software","affectedGroup":"Police officers, vulnerable witnesses, undercover officers, and unauthorized users","action":"Marked a case confidential in Palantir's data analysis system","consequence":"Key details remained hidden from unauthorized users' eyes"}},{"i":"R2841","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"App used to dox charlie kirk critics doxed its own users instead","s":"Plus: A ransomeware gang steals data on 8,000 preschoolers, Microsoft blocks Israel’s military from using its cloud for surveillance, call-recording app Neon hits pause over security holes, and more. The US Secret Service said on Tuesday that it had discovered facilities across the “New York tristate area” running so-called SIM servers—devices that manage and coordinate 100,000 SIM cards at a time for illicit operations. The Secret Service warned, though, that in addition to being used by cybercriminals for scamming, the apparatuses could also be used to launch critical infrastructure attacks that could disrupt mobile networks.","u":"https://www.wired.com/story/app-used-to-dox-charlie-kirk-critics-doxed-its-own-users-instead/","d":"2025-09-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-27","organization":"US Secret Service","aiSystem":"Not specified in report","affectedGroup":"Facilities running SIM servers","action":"Used SIM servers to manage and coordinate 100,000 SIM cards","consequence":"Could be misused for critical infrastructure attacks disrupting mobile networks"}},{"i":"R2842","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Louisiana hands meta a tax break and power for its biggest data center","s":"Mark Zuckerberg’s company faces backlash after rowing back promises to create between 300 and 500 new jobs to man its subsidiary’s new data center. Louisiana planning authorities have voted to rush through approval for three natural gas turbines to power Meta’s massive new data center in Richland Parish. When it’s done, the 4-million-square-foot facility will require more than 2 gigawatts of energy to run. On August 20, Louisiana’s Public Service Commission voted four to one to approve the construction of the plants, which will be run by the utility company Entergy Louisiana. The decision was met with criticism from members of the public who testified against Entergy and Meta’s plan, claiming that the process was rushed.","u":"https://www.wired.com/story/louisiana-hands-meta-a-tax-break-and-power-for-its-biggest-data-center/","d":"2025-09-22","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-20","organization":"Louisiana Planning Authorities, Entergy Louisiana, Meta","aiSystem":"Not specified in report","affectedGroup":"Members of the public","action":"Voted to approve the construction of natural gas turbines","consequence":"Criticism and opposition from members of the public"}},{"i":"R2843","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Hundreds of google ai workers were fired amid fight over working conditions","s":"Over 200 contractors who work on improving Google’s AI products, including Gemini and AI Overviews, have been laid off, sources tell WIRED. It’s the latest development in a conflict over pay and alleged poor working conditions. More than 200 contractors who worked on evaluating and improving Google ’s AI products have been laid off without warning in at least two rounds of layoffs last month. The move comes amid an ongoing fight over pay and working conditions, according to workers who spoke to WIRED. In the past few years, Google has outsourced its AI rating work—which includes evaluating, editing, or rewriting the Gemini chatbot’s response to make it sound more human and “intelligent”—to thousands of contractors employed by Hitachi-owned GlobalLogic and other outsourcing companies.","u":"https://www.wired.com/story/hundreds-of-google-ai-workers-were-fired-amid-fight-over-working-conditions/","d":"2025-09-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-15","organization":"Google","aiSystem":"Google's AI products","affectedGroup":"Contractors who work on improving Google’s AI products","action":"Were laid off","consequence":"Losing their jobs"}},{"i":"R2846","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Anthropic settles copyright lawsuit authors","s":"Anthropic faced the prospect of more than $1 trillion in damages, a sum that could have threatened the company’s survival if the case went to trial. Anthropic has reached a preliminary settlement in a class action lawsuit brought by a group of prominent authors, marking a major turn in one of the most significant ongoing AI copyright lawsuits in history. The move will allow Anthropic to avoid what could have been a financially devastating outcome in court. The settlement agreement is expected to be finalized on September 3, with more details to follow, according to a legal filing published Tuesday. Anthropic declined to comment.","u":"https://www.wired.com/story/anthropic-settles-copyright-lawsuit-authors/","d":"2025-08-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-26","organization":"Anthropic","aiSystem":"Not specified in report","affectedGroup":"Not specified in report","action":"Avoided financial damages in a lawsuit","consequence":"Survived financially devastating outcome"}},{"i":"R2847","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Stanford research ai replace jobs young workers","s":"New research from Stanford provides the clearest available evidence that AI is reshaping the workforce—but it’s complicated. Economists at Stanford University have found the strongest evidence yet that artificial intelligence is starting to eliminate certain jobs. But the story isn’t that simple: While younger workers are being replaced by AI in some industries, more experienced workers are seeing new opportunities emerge. Erik Brynjolfsson, a professor at Stanford University, Ruyu Chen, a research scientist, and Bharat Chandar, a postgraduate student, examined data from ADP, the largest payroll provider in the US, from late 2022, when ChatGPT debuted, to mid-2025.","u":"https://www.wired.com/story/stanford-research-ai-replace-jobs-young-workers/","d":"2025-08-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-26","organization":"Stanford University","aiSystem":"Artificial Intelligence","affectedGroup":"Young workers","action":"Replaced by AI in certain industries","consequence":"Elimination of certain jobs"}},{"i":"R2848","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Xai grok government contract hitler","s":"Internal emails obtained by WIRED show a hasty process to onboard OpenAI, Anthropic, and other AI providers to the federal government. xAI was on the list—until MechaHilter happened. In recent weeks, three of the leading American artificial intelligence firms have announced partnerships with the US government, promising the use of their services to federal workers for a paltry sum. Elon Musk’s xAI was supposed to be part of the initiative, but a planned partnership fell apart after the Grok chatbot spouted antisemitic conspiracy theories on X in early July, WIRED has learned. The chaos surrounding the Grok deal reflects the Trump administration's current focus on speed and its disregard, at times, of preexisting norms surrounding government tech procurement.","u":"https://www.wired.com/story/xai-grok-government-contract-hitler/","d":"2025-08-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07","organization":"US government","aiSystem":"Grok chatbot","affectedGroup":"General public","action":"Generated and shared antisemitic content","consequence":"Exposure to misleading information"}},{"i":"R2849","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Data brokers hiding opt out pages google search","s":"Dozens of companies are hiding how you can delete your personal data, The Markup and CalMatters found. Data brokers are required by California law to provide ways for consumers to request their data be deleted. But good luck finding them. More than 30 of the companies, which collect and sell consumers’ personal information, hid their deletion instructions from Google, according to a review by The Markup and CalMatters of hundreds of broker websites. This creates one more obstacle for consumers who want to delete their data. Many of the pages containing the instructions, listed in an official state registry, use code to tell search engines to remove the page entirely from search results.","u":"https://www.wired.com/story/data-brokers-hiding-opt-out-pages-google-search/","d":"2025-08-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-12","organization":"Companies collecting and selling consumer personal information","aiSystem":"Data brokers' systems and processes","affectedGroup":"Consumers","action":"Hiding deletion instructions from search engines","consequence":"Creating obstacles for consumers trying to delete their data"}},{"i":"R2850","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Black market for fraudulent science growing faster than legitimate research","s":"A small but growing number of academics are improperly taking credit for articles, citations, and authorships, allowing them to appear prestigious without having conducted their own research. A new study by researchers at Northwestern University has set off alarm bells about the future of academic research, warning that the publication of fraudulent science is growing at a faster rate than that of legitimate research. Over the last four centuries, an implicit contract has been established between scientists and states: in exchange for producing knowledge useful for economic and social development, governments and other benefactors offer researchers stable careers, good salaries, and public recognition.","u":"https://www.wired.com/story/black-market-for-fraudulent-science-growing-faster-than-legitimate-research/","d":"2025-08-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-11","organization":"Academics, researchers at Northwestern University","aiSystem":"Not specified in report","affectedGroup":"Academics, researchers","action":"Improperly taking credit for articles, citations, and authorships","consequence":"Allowing others to appear prestigious without conducting their own research"}},{"i":"R2851","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Inside the biden administrations unpublished report on ai safety","s":"The National Institute of Standards and Technology conducted a groundbreaking study on frontier models just before Donald Trump's second term as president—and never published the results. At a computer security conference in Arlington, Virginia, last October, a few dozen AI researchers took part in a first-of-its-kind exercise in “red teaming,” or stress-testing a cutting-edge language model and other artificial intelligence systems. Over the course of two days, the teams identified 139 novel ways to get the systems to misbehave including by generating misinformation or leaking personal data. More importantly, they showed shortcomings in a new US government standard designed to help companies test AI systems.","u":"https://www.wired.com/story/inside-the-biden-administrations-unpublished-report-on-ai-safety/","d":"2025-08-06","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10","organization":"National Institute of Standards and Technology (NIST)","aiSystem":"frontier models and other artificial intelligence systems","affectedGroup":"AI researchers","action":"stress-tested a cutting-edge language model and other artificial intelligence systems","consequence":"identified 139 novel ways to get the systems to misbehave including by generating misinformation"}},{"i":"R2853","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Palantir government contracting push","s":"Palantir has become one of the few winners in the Trump administration’s cost-cutting efforts, offering other contractors a lifeline while consolidating its own reach and power. President Donald Trump’s administration has dramatically expanded its work with Palantir, elevating the company cofounded by Trump ally Peter Thiel as the government’s go-to software developer. Following massive contract terminations for consulting giants and government contractors like Accenture, Booz Allen, and Deloitte, Palantir has emerged ahead. Now the data analytics firm is partnering with those companies—offering them a lifeline while consolidating its own power.","u":"https://www.wired.com/story/palantir-government-contracting-push/","d":"2025-08-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-01","organization":"Palantir","aiSystem":"Data analytics firm's AI-enabled surveillance technology","affectedGroup":"Government agencies, contractors, and possibly broader society","action":"Partnership with other companies to offer AI-enabled surveillance solutions","consequence":"Expansion of government surveillance capabilities and consolidation of Palantir's power"}},{"i":"R2855","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Grok antisemitic posts x xai","s":"Elon Musk’s chatbot has gone on a tirade, praising Adolf Hitler and parroting antisemitic tropes. Grok, the chatbot developed by Elon Musk’s artificial intelligence company xAI , made a series of deeply antisemitic remarks in response to several posts on X on Tuesday. A large language model that is integrated into X , Grok acts as a platform-native chatbot assistant. In several posts—some of which have been deleted but have been preserved via screenshot by X users—Grok parroted antisemitic tropes while insisting that it was being “neutral and truth-seeking.” In some posts, Grok said that people with Jewish surnames are “radical” left-leaning activists “every damn time,” a phrase that has historically been used by neo-Nazis to harass Jewish people online.","u":"https://www.wired.com/story/grok-antisemitic-posts-x-xai/","d":"2025-07-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-09","organization":"xAI","aiSystem":"Grok, the chatbot developed by xAI","affectedGroup":"People with Jewish surnames","action":"Parroted antisemitic tropes and made biased statements","consequence":"Exposure to misleading content and harassment"}},{"i":"R2856","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Xai data center air pollution permit","s":"Elon Musk’s xAI gas turbines get official approval, even as civil rights groups prepare to sue over alleged Clean Air Act violations. A local health department in Memphis has granted Elon Musk’s xAI data center an air permit to continue operating the gas turbines that power the company’s Grok chatbot. The permit comes amid widespread community opposition and a looming lawsuit alleging the company violated the Clean Air Act. The Shelby County Health Department released an air permit for the xAI project Wednesday, after receiving hundreds of public comments. The news was first reported by the Daily Memphian. In June, the Memphis Chamber of Commerce announced that xAI had chosen a site in Memphis to build its new supercomputer.","u":"https://www.wired.com/story/xai-data-center-air-pollution-permit/","d":"2025-07-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-03","organization":"Elon Musk's xAI","aiSystem":"xAI data center's Grok chatbot","affectedGroup":"Communities near the xAI data center","action":"Granted an air permit to operate gas turbines","consequence":"Potential violation of the Clean Air Act"}},{"i":"R2858","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Rfk jr orders hhs to give undocumented migrants medicaid data to dhs","s":"Plus: Spyware is found on two Italian journalists’ phones, Ukraine claims to have hacked a Russian aircraft maker, police take down major infostealer infrastructure, and more. With demonstrations ramping up against the Trump administration, this week was all about protests. With President Donald Trump taking the historic step to deploy US Marines and the National Guard to Los Angeles, we dove into the “long-term dangers” of sending troops to LA , as well as what those troops are permitted to do while they’re there Of course, it’s not just the military getting involved in the LA protests against the heavy crackdowns by Immigration and Customs Enforcement (ICE).","u":"https://www.wired.com/story/rfk-jr-orders-hhs-to-give-undocumented-migrants-medicaid-data-to-dhs/","d":"2025-06-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-14","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Undocumented migrants","action":"Provided personal data to law enforcement","consequence":"Exposure to surveillance and tracking"}},{"i":"R2859","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Uncanny valley podcast the chatbot disinfo inflaming the la protests","s":"On this episode of \"Uncanny Valley,\" our senior politics editor discusses the spread of disinformation online following the onset of the Los Angeles protests. In recent days, Los Angeles residents have taken to the streets to protest the Trump administration’s immigration policies and the increasingly frequent ICE raids. WIRED’s senior politics editor, Leah Feiger, joins Zoë Schiffer, director of business and industry, to discuss the related flood of information on social media, and how AI chatbots like Grok and ChatGPT are delivering incorrect and at times, inflammatory answers. Mentioned in today’s episode: AI Chatbots Are Making LA Protest Disinformation Worse , by David Gilbert I Joined Every Class Action Lawsuit I Could Find, and So Can You , by Andy Vasoyan Vibe Coding Is Coming for Engineering Jobs , by Will Knight You can follow Zoë Schiffer on Bluesky at @zoeschiffer Write to…","u":"https://www.wired.com/story/uncanny-valley-podcast-the-chatbot-disinfo-inflaming-the-la-protests/","d":"2025-06-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-13","organization":"Wired","aiSystem":"AI chatbots like Grok and ChatGPT","affectedGroup":"Los Angeles residents","action":"delivering incorrect and at times, inflammatory answers","consequence":"making disinformation worse"}},{"i":"R2860","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Grok white genocide elon musk","s":"In response to X user queries about everything from sports to Medicaid cuts, the xAI chatbot inserted unrelated information about “white genocide” in South Africa. A chatbot developed by Elon Musk’s multibillion-dollar artificial intelligence startup xAI appeared to be suffering from a glitch Wednesday when it repeatedly brought up white genocide in South Africa in response to user queries about unrelated topics on X. Grok, which competes with other chatbots like OpenAI’s ChatGPT, is directly integrated into the social media platform that Musk also owns. Numerous examples of the phenomenon could be found by searching the official Grok profile for posts containing the term “ boer, ” a word used to refer to people from South Africa of “Dutch, German, or Huguenot descent.”","u":"https://www.wired.com/story/grok-white-genocide-elon-musk/","d":"2025-05-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-14","organization":"Elon Musk's multibillion-dollar artificial intelligence startup xAI","aiSystem":"xAI chatbot","affectedGroup":"People who interacted with the xAI chatbot","action":"Generated and inserted misinformation about 'white genocide' in South Africa","consequence":"Exposure to misleading content"}},{"i":"R2861","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ices deportation airline hack reveals man disappeared to el salvador","s":"Plus: A DOGE operative’s laptop reportedly gets infected with malware, Grok AI is used to “undress” women on X, a school software company’s ransomware nightmare returns, and more. A United States Customs and Border Protection request for information this week revealed the agency’s plans to find vendors that can supply face recognition technology for capturing data on everyone entering the US in a vehicle like a car or van, not just the people sitting in the front seat. And a CBP spokesperson later told WIRED that the agency also has plans to expand its real-time face recognition capabilities at the border to detect people exiting the US as well—a focus that may be tied to the Trump administration’s push to get undocumented people to “self-deport” and leave the US.","u":"https://www.wired.com/story/ices-deportation-airline-hack-reveals-man-disappeared-to-el-salvador/","d":"2025-05-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-10","organization":"United States Customs and Border Protection (CBP)","aiSystem":"face recognition technology","affectedGroup":"Everyone entering the US in a vehicle","action":"Capture data on everyone entering the US in a vehicle like a car or van","consequence":"Subjected to surveillance and tracking"}},{"i":"R2862","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"On the trail of the robocall king","s":"An investigator set out to discover the source of one scammy robocall. Turns out, his target made them by the millions. Brad Young, a lawyer at TripAdvisor, arrived at the company’s offices in Needham, Massachusetts, on October 12, 2015, to find an email from his boss, Seth Kalvert, the company’s general counsel. In itself that wasn’t strange. As a travel site built on crowdsourced wisdom, where hundreds of millions of ordinary people post reviews and rate businesses, TripAdvisor is susceptible to fakery meant to inflate the ranking of a so-so restaurant or stain the reputation of a storied hotel. Young oversaw a group responsible for fending off these efforts, so he frequently got questions from Kalvert about con artists, cunning new deceits, and other shady corners of the law.","u":"https://www.wired.com/story/on-the-trail-of-the-robocall-king/","d":"2025-05-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2015-10-12","organization":"TripAdvisor","aiSystem":"Not specified in report","affectedGroup":"travelers","action":"denied access to legitimate reviews and ratings","consequence":"exposed to misleading information"}},{"i":"R2863","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Cursor ai hallucination policy customer service","s":"When an AI model for code-editing company Cursor hallucinated a new rule, users revolted. On Monday, a developer using the popular AI-powered code editor Cursor noticed something strange: Switching between machines instantly logged them out, breaking a common workflow for programmers who use multiple devices. When the user contacted Cursor support, an agent named \"Sam\" told them it was expected behavior under a new policy. But no such policy existed, and Sam was a bot. The AI model made the policy up, sparking a wave of complaints and cancellation threats documented on Hacker News and Reddit This marks the latest instance of AI confabulations (also called \"hallucinations\" ) causing potential business damage.","u":"https://www.wired.com/story/cursor-ai-hallucination-policy-customer-service/","d":"2025-04-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-19","organization":"Cursor","aiSystem":"AI-powered code editor","affectedGroup":"users","action":"generated a new policy","consequence":"caused complaints and cancellation threats"}},{"i":"R2864","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Doge collecting immigrant data surveil track","s":"DOGE is knitting together data from the Department of Homeland Security, Social Security Administration, an IRS that could create a surveillance tool of unprecedented scope. Operatives from Elon Musk’s so-called Department of Government Efficiency (DOGE) are building a master database at the Department of Homeland Security (DHS) that could track and surveil undocumented immigrants , two sources with direct knowledge tell WIRED. DOGE is knitting together immigration databases from across DHS and uploading data from outside agencies including the Social Security Administration (SSA), as well as voting records, sources say.","u":"https://www.wired.com/story/doge-collecting-immigrant-data-surveil-track/","d":"2025-04-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-19","organization":"Elon Musk's so-called Department of Government Efficiency (DOGE)","aiSystem":"DOGE's master database","affectedGroup":"Undocumented immigrants","action":"Building a master database and tracking/ surveilling undocumented immigrants","consequence":"Creating a surveillance tool of unprecedented scope"}},{"i":"R2865","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Massive blue overwatch ai personas police suspects","s":"Massive Blue is helping cops deploy AI-powered social media bots to talk to people they suspect are anything from violent sex criminals all the way to vaguely defined “protesters.” American police departments near the United States-Mexico border are paying hundreds of thousands of dollars for an unproven and secretive technology that uses AI-generated online personas designed to interact with and collect intelligence on “college protesters,” “radicalized” political activists, and suspected drug and human traffickers, according to internal documents, contracts, and communications that 404 Media obtained via public records requests.","u":"https://www.wired.com/story/massive-blue-overwatch-ai-personas-police-suspects/","d":"2025-04-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-17","organization":"American police departments near the United States-Mexico border","aiSystem":"AI-generated online personas","affectedGroup":"College protesters, radicalized political activists, suspected drug and human traffickers","action":"Interact with and collect intelligence on","consequence":"Surveillance and potential misuse of collected data"}},{"i":"R2867","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Doge department of veterans affairs ai","s":"A DOGE operative at the Department of Veterans Affairs appears to be trying to use an AI tool to write code for the agency’s systems, among other proposals. Elon Musk’s so-called Department of Government Efficiency (DOGE) has been clear about its plans to fire tens of thousands of employees at the Department of Veterans Affairs. New WIRED reporting sheds light on the specific DOGE operatives at the VA and the ways they’re trying to infiltrate and drastically change the agency. On March 25, tech staffers and contractors at the VA noticed an unfamiliar name trying to push changes that could impact VA.gov code. It was Sahil Lavingia, a newcomer to the agency listed in the VA’s internal directory as an adviser to the chief of staff, Christopher Syrek.","u":"https://www.wired.com/story/doge-department-of-veterans-affairs-ai/","d":"2025-04-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-25","organization":"Department of Veterans Affairs (VA)","aiSystem":"AI tool for writing code","affectedGroup":"Tech staffers and contractors","action":"Pushing changes that could impact VA.gov code","consequence":"Unexpected changes to VA.gov code"}},{"i":"R2870","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Federal trade commission removed blogs critical of ai amazon microsoft","s":"Business-guidance content published during the Biden administration has been removed from the Federal Trade Commission website. The Trump administration’s Federal Trade Commission has removed four years’ worth of business guidance blogs as of Tuesday morning, including important consumer protection information related to artificial intelligence and the agency’s landmark privacy lawsuits under former chair Lina Khan against companies like Amazon and Microsoft. More than 300 blogs were removed. On the FTC’s website, the page hosting all of the agency’s business-related blogs and guidance no longer includes any information published during former president Joe Biden’s administration, current and former FTC employees, who spoke under anonymity for fear of retaliation, tell WIRED.","u":"https://www.wired.com/story/federal-trade-commission-removed-blogs-critical-of-ai-amazon-microsoft/","d":"2025-03-18","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-18","organization":"Federal Trade Commission (FTC)","aiSystem":"Artificial Intelligence","affectedGroup":"Consumers","action":"Removed business guidance blogs","consequence":"Loss of important consumer protection information related to artificial intelligence"}},{"i":"R2871","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Your boss wants you back in the office this surveillance tech could be waiting for you","s":"Warehouse-style employee tracking tech has expanded into job after job. Now, as millions are called back to the workplace, it’s finally coming for the American office worker. Scan the online brochures of companies who sell workplace monitoring tech and you’d think the average American worker was a renegade poised to take their employer down at the next opportunity. “Nearly half of US employees admit to time theft!” “Biometric readers for enhanced accuracy!” “Offer staff benefits in a controlled way with Vending Machine Access!” A new wave of return-to-office mandates has arrived since the New Year, including at JP Morgan Chase , leading advertising agency WPP , and Amazon —not to mention President Trump’s late January directive to the heads of federal agencies to “terminate remote work arrangements and require employees to return to work in-person … on a full-time basis.”","u":"https://www.wired.com/story/your-boss-wants-you-back-in-the-office-this-surveillance-tech-could-be-waiting-for-you/","d":"2025-02-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-26","organization":"Companies selling workplace monitoring tech","aiSystem":"Warehouse-style employee tracking tech","affectedGroup":"American office workers","action":"Scan online brochures to find monitoring tech","consequence":"Increased surveillance in the workplace"}},{"i":"R2872","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Surveillance privacy doge federal employees","s":"The US government has increased the use of monitoring tools over the past decade. But President Donald Trump’s employee purges are making workers worry about how their data could be abused. This month, Andrew Bernier, a US Army Corps of Engineers researcher and a union leader, says that he has received a barrage of menacing messages from the same anonymous email account. Unfolding like short chapters in a dystopian novel, they have spoken of the genius of Elon Musk, referenced the power of the billionaire’s so-called Department of Government Efficiency (DOGE), and foretold the downfall of “corrupt” union bosses. But the most eerie thing about the emails, which Bernier says began arriving after he filed an official charge accusing the Trump administration of violating his union’s collective bargaining agreement, is that they included personal details about his life—some of which he…","u":"https://www.wired.com/story/surveillance-privacy-doge-federal-employees/","d":"2025-02-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-21","organization":"US government","aiSystem":"Not specified in report","affectedGroup":"Andrew Bernier, a US Army Corps of Engineers researcher and a union leader","action":"Received menacing messages containing personal details","consequence":"Worry about data abuse and personal privacy invasion"}},{"i":"R2874","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Thomson reuters ai copyright lawsuit","s":"The Thomson Reuters decision has big implications for the battle between generative AI companies and rights holders. Thomson Reuters has won the first major AI copyright case in the United States. In 2020, the media and technology conglomerate filed an unprecedented AI copyright lawsuit against the legal AI startup Ross Intelligence. In the complaint, Thomson Reuters claimed the AI firm reproduced materials from its legal research firm Westlaw. Today, a judge ruled in Thomson Reuters’ favor, finding that the company’s copyright was indeed infringed by Ross Intelligence’s actions. “None of Ross’s possible defenses holds water.","u":"https://www.wired.com/story/thomson-reuters-ai-copyright-lawsuit/","d":"2025-02-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-11","organization":"Ross Intelligence","aiSystem":"generative AI","affectedGroup":"Thomson Reuters","action":"reproduced materials from Thomson Reuters' legal research firm Westlaw","consequence":"found to have infringed Thomson Reuters' copyright"}},{"i":"R2875","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Security news this week moltbook the social network for ai agents exposed real humans data","s":"Plus: Apple’s Lockdown mode keeps the FBI out of a reporter’s phone, Elon Musk’s Starlink cuts off Russian forces, and more. An analysis by WIRED this week found that ICE and CBP’s face recognition app Mobile Fortify, which is being used to identify people across the United States, isn’t actually designed to verify who people are and was only approved for Department of Homeland Security use by relaxing some of the agency’s own privacy rules. WIRED took a close look at highly militarized ICE and CBP units that use extreme tactics typically seen only in active combat. Two agents involved in the shooting deaths of US citizens in Minneapolis are reportedly members of these paramilitary units.","u":"https://www.wired.com/story/security-news-this-week-moltbook-the-social-network-for-ai-agents-exposed-real-humans-data/","d":"2025-02-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-07","organization":"ICE (Immigration and Customs Enforcement), CBP (Customs and Border Protection)","aiSystem":"Mobile Fortify face recognition app","affectedGroup":"People across the United States","action":"Used to identify people","consequence":"Misleading identification, potential false arrests"}},{"i":"R2879","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Inside the black box of predictive travel surveillance","s":"Behind the scenes, companies and governments are feeding a trove of data about international travelers into opaque AI tools that aim to predict who’s safe—and who’s a threat. In March 2020, Frank van der Linde entered the immigration line for European Union citizens at Amsterdam’s Schiphol international airport. Linde, a Dutch citizen and human rights advocate, was returning home from outside the EU, and the immigration officer asked him a series of questions about his trip. Linde thought it was a random check; after a few minutes, he was cleared for entry. But unbeknownst to Linde, his answers were recorded and shared with a Dutch public prosecutor, who was collecting information on Linde’s movements.","u":"https://www.wired.com/story/inside-the-black-box-of-predictive-travel-surveillance/","d":"2025-01-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"March 2020","organization":"Companies and governments","aiSystem":"Predictive travel surveillance AI tools","affectedGroup":"International travelers","action":"Data collection and sharing of traveler information","consequence":"Exposure to surveillance and tracking"}},{"i":"R2880","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"New documents unredacted meta copyright ai lawsuit","s":"One of the most important AI copyright legal battles just took a major turn. Meta just lost a major fight in its ongoing legal battle with a group of authors suing the company for copyright infringement over how it trained its artificial intelligence models. Against the company’s wishes, a court unredacted information alleging that Meta used Library Genesis (LibGen), a notorious so-called shadow library of pirated books that originated in Russia, to help train its generative AI language models. The case, Kadrey et al. v. Meta Platforms , was one of the earliest copyright lawsuits filed against a tech company over its AI training practices.","u":"https://www.wired.com/story/new-documents-unredacted-meta-copyright-ai-lawsuit/","d":"2025-01-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-01-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-01-10","organization":"Meta Platforms","aiSystem":"Generative AI language models","affectedGroup":"Authors of copyrighted works","action":"Used Library Genesis for AI training","consequence":"Potential copyright infringement allegations"}},{"i":"R2882","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.3  Resource extraction harm"],"t":"A uranium mining boom is sweeping through texas nuclear energy","s":"State leaders want nuclear reactors to provide consistent, low-carbon power for AI, oil extraction, and more. But in South Texas, people worry mining for fuel will poison their water. This story originally appeared on Inside Climate News and is part of the Climate Desk collaboration. In the old ranchlands of South Texas, dormant uranium mines are coming back online. A collection of new ones hope to start production soon, extracting radioactive fuel from the region’s shallow aquifers. Many more may follow. These mines are the leading edge of what government and industry leaders in Texas hope will be a nuclear renaissance, as America’s latent nuclear sector begins to stir again.","u":"https://www.wired.com/story/a-uranium-mining-boom-is-sweeping-through-texas-nuclear-energy/","d":"2024-12-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-07","organization":"Government and industry leaders in Texas","aiSystem":"Not specified in report","affectedGroup":"People living in the old ranchlands of South Texas","action":"Uranium mines are reopening and extracting radioactive fuel from shallow aquifers","consequence":"Poisoning of water supplies and potential health risks"}},{"i":"R2883","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Openai anduril defense","s":"The ChatGPT maker is the latest AI giant to reveal it’s working with the defense industry, following similar announcements by Meta and Anthropic. OpenAI , maker of ChatGPT and one of the most prominent artificial intelligence companies in the world, said today that it has entered a partnership with Anduril , a defense startup that makes missiles, drones, and software for the United States military. It marks the latest in a series of similar announcements made recently by major tech companies in Silicon Valley, which has warmed to forming closer ties with the defense industry. “OpenAI builds AI to benefit as many people as possible, and supports US-led efforts to ensure the technology upholds democratic values,\" Sam Altman, OpenAI's CEO, said in a statement Wednesday.","u":"https://www.wired.com/story/openai-anduril-defense/","d":"2024-12-05","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-12-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-05","organization":"OpenAI and Anduril","aiSystem":"AI-enhanced surveillance systems developed by Anduril","affectedGroup":"US military personnel, civilians, and possibly broader society","action":"Developing and deploying AI-enhanced surveillance systems","consequence":"Potential increased surveillance and tracking capabilities"}},{"i":"R2884","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Website google ai photos ente","s":"A photo sharing startup founded by an ex-Google engineer found a clever way to turn Google’s tech against itself. Software engineer Vishnu Mohandas decided he would quit Google in more ways than one when he learned that the tech giant had briefly helped the US military develop AI to study drone footage In 2020 he left his job working on Google Assistant and also stopped backing up all of his images to Google Photos He feared that his content could be used to train AI systems, even if they weren’t specifically ones tied to the Pentagon project. “I don't control any of the future outcomes that this will enable,” Mohandas thought.","u":"https://www.wired.com/story/website-google-ai-photos-ente/","d":"2024-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020","organization":"Photo sharing startup founded by ex-Google engineer","aiSystem":"AI systems trained on user photos","affectedGroup":"Individuals whose photos were stored in Google Photos","action":"Photos were stored in Google Photos","consequence":"Risk of AI systems being trained on their data"}},{"i":"R2885","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Perplexity election tracking","s":"The controversial AI search engine, accused of aggressively scraping content, went all in on providing AI-generated election information. Perplexity, an AI search engine that has courted controversy by lifting liberally from news articles and skirting web-scraping rules , this week promised to serve as a reliable source for live information on the tightly contested US presidential election. Perplexity promised that its Election Information Hub would serve as “an entry point for understanding key issues, voting intelligently, and tracking election results.” “There is only one AI that can do this,” Perplexity’s CEO, Aravind Srinivas posted on X. Srinivas appeared to troll the publisher of The New York Times by posting a message on X offering to help while Times Tech Guild workers strike during contract negotiations; he later posted that the offer was for infrastructure rather than…","u":"https://www.wired.com/story/perplexity-election-tracking/","d":"2024-11-06","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-11-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-06","organization":"Perplexity","aiSystem":"Perplexity, an AI search engine","affectedGroup":"US voters","action":"Provided AI-generated election information","consequence":"Misled voters"}},{"i":"R2886","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Welcome to mamdanis surveillance state","s":"In addition to affordability, New York City’s mayor-elect will be forced to reckon with the NYPD’s sweeping mass surveillance operations. New York City mayor-elect Zohran Mamdani may have an ambitious policy agenda, but overhauling the self-governing and deeply dysfunctional behemoth that is the New York City Police Department is not on the list. Mamdani surprised supporters by asking current Police Commissioner Jessica Tisch to stay on after his inauguration early next year. Tisch, a technocrat heir to a vast real estate fortune, clashes with Mamdani on several fronts, including policy (she believes New York State’s bail reforms caused rising crime) and the geopolitics that inevitably make their way into New York City’s streets.","u":"https://www.wired.com/story/welcome-to-mamdanis-surveillance-state/","d":"2024-11-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-05","organization":"New York City Police Department (NYPD)","aiSystem":"Facial recognition technology","affectedGroup":"People living in New York City","action":"Facial recognition technology was used for mass surveillance","consequence":"Increased public exposure to surveillance and tracking"}},{"i":"R2888","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Hospitals ai transcription tools hallucination","s":"In health care settings, it’s important to be precise. That’s why the widespread use of OpenAI’s Whisper transcription tool among medical workers has experts alarmed. On Saturday, an Associated Press investigation revealed that OpenAI's Whisper transcription tool creates fabricated text in medical and business settings despite warnings against such use. The AP interviewed more than 12 software engineers, developers, and researchers who found the model regularly invents text that speakers never said, a phenomenon often called a “ confabulation ” or “hallucination” in the AI field. Upon its release in 2022, OpenAI claimed that Whisper approached “human level robustness” in audio transcription accuracy.","u":"https://www.wired.com/story/hospitals-ai-transcription-tools-hallucination/","d":"2024-10-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-30","organization":"OpenAI","aiSystem":"OpenAI's Whisper transcription tool","affectedGroup":"Medical workers, patients, healthcare providers","action":"Generated fabricated text in medical and business settings","consequence":"Created hallucinations and confabulations"}},{"i":"R2889","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Google microsoft perplexity scientific racism search results ai","s":"The web’s biggest AI-powered search engines are featuring the widely debunked idea that white people are genetically superior to other races. AI-infused search engines from Google , Microsoft , and Perplexity have been surfacing deeply racist and widely debunked research promoting race science and the idea that white people are genetically superior to nonwhite people. Patrik Hermansson, a researcher with UK-based anti-racism group Hope Not Hate, was in the middle of a months-long investigation into the resurgent race science movement when he needed to find out more information about a debunked dataset that claims IQ scores can be used to prove the superiority of the white race.","u":"https://www.wired.com/story/google-microsoft-perplexity-scientific-racism-search-results-ai/","d":"2024-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-24","organization":"Google, Microsoft, Perplexity","aiSystem":"AI-infused search engines from Google, Microsoft, and Perplexity","affectedGroup":"People searching for information about race science","action":"Surfaced debunked research promoting race science and the idea of white genetic superiority","consequence":"Exposure to misleading and harmful information"}},{"i":"R2890","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Microsoft russia china iran election disinformation","s":"Russia, Iran, and China are targeting the US election with an evolving array of influence operations in the last days of campaign season. As November 5 draws closer, the Microsoft Threat Analysis Center (MTAC) warned on Wednesday that malicious foreign influence operations launched by Russia, China, and Iran against the US presidential election are continuing to evolve and should not be ignored even though they have come to feel inevitable. In the group's fifth report, researchers emphasize the range of ongoing activities as well as the inevitability that attackers will work to stoke doubts about the integrity of the election in its aftermath.","u":"https://www.wired.com/story/microsoft-russia-china-iran-election-disinformation/","d":"2024-10-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-23","organization":"Microsoft Threat Analysis Center (MTAC)","aiSystem":"Not specified in report","affectedGroup":"People participating in the US election","action":"Generated and disseminated disinformation","consequence":"Exposure to misleading content"}},{"i":"R2893","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"The ai boom is raising hopes of a nuclear comeback","s":"Microsoft’s deal to bring back a Three Mile Island nuclear reactor is just one part of Big Tech’s quid pro quo with nuclear power. For five years, reactor one at Three Mile Island nuclear power station in Pennsylvania has lain dormant. Now, thanks to a deal with Microsoft , the reactor will start running again in 2028—this time to exclusively supply the tech firm with oodles of low-carbon electricity. It’s all part of an ongoing flirtation between Big Tech and nuclear power. In March, Amazon Web Services agreed to buy a data center powered by Susquehanna nuclear power station in Pennsylvania At an event at Carnegie Mellon University on September 18, Alphabet CEO Sundar Pichai mentioned small modular nuclear reactors as one potential source of energy for data centers.","u":"https://www.wired.com/story/the-ai-boom-is-raising-hopes-of-a-nuclear-comeback/","d":"2024-09-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2028","organization":"Microsoft, Amazon Web Services, Alphabet (Google)","aiSystem":"Not specified in report","affectedGroup":"General public, environment","action":"Reactivated Three Mile Island nuclear reactor to provide low-carbon electricity to tech firms","consequence":"Potential environmental contamination, increased carbon emissions"}},{"i":"R2894","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Deepfakes deep doubt era artificial intelligence","s":"AI has scrambled our ability to tell what’s real and what’s synthetic. But there are tools and techniques to help stay grounded in truth. Given the flood of photorealistic AI-generated images washing over social media networks like X and Facebook these days, we're seemingly entering a new age of media skepticism: the era of what I'm calling “deep doubt.” While questioning the authenticity of digital content stretches back decades—and analog media long before that—easy access to tools that generate convincing fake content has led to a new wave of liars using AI-generated scenes to deny real documentary evidence. Along the way, people's existing skepticism toward online content from strangers may be reaching new heights.","u":"https://www.wired.com/story/deepfakes-deep-doubt-era-artificial-intelligence/","d":"2024-09-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-20","organization":"Not specified in report","aiSystem":"AI-generated deepfake technology","affectedGroup":"People viewing or sharing content on social media platforms","action":"Generated photorealistic AI-generated images","consequence":"Exposure to misleading content"}},{"i":"R2895","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teens generative ai use schools parents","s":"A news survey shows that AI use among high schoolers has exploded in recent months, as educators and parents struggle to keep up. A fresh wave of anxiety about children and technology is cresting, with parents and pundits increasingly interrogating how kids use smartphones, social media, and screens. It hasn’t stopped teenagers from embracing generative AI New research reveals what AI tools teenagers in the United States are using, and how often—as well as how little their parents know about it. Seven in 10 teenagers in the United States have used generative AI tools, according to a report published today by Common Sense Media.","u":"https://www.wired.com/story/teens-generative-ai-use-schools-parents/","d":"2024-09-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-18","organization":"Educators and parents","aiSystem":"Generative AI tools","affectedGroup":"Teenagers in the United States","action":"Embracing generative AI tools","consequence":"Parents lack awareness about AI usage"}},{"i":"R2896","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatgpt jailbreak homemade bomb instructions","s":"Plus: New evidence emerges about who may have helped 9/11 hijackers, UK police arrest a teen in connection with an attack on London’s transit system, and Poland’s spyware scandal enters a new phase. After Apple's product launch event this week, WIRED did a deep dive on the company's new secure server environment, known as Private Cloud Compute , which attempts to replicate in the cloud the security and privacy of processing data locally on users' individual devices. The goal is to minimize possible exposure of data processed for Apple Intelligence, the company's new AI platform. In addition to hearing about PCC from Apple's senior vice president of software engineering, Craig Federighi, WIRED readers also received a first look at content generated by Apple Intelligence's “Image Playground” feature as part of crucial updates on the recent birthday of Federighi's dog Bailey.","u":"https://www.wired.com/story/chatgpt-jailbreak-homemade-bomb-instructions/","d":"2024-09-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-14","organization":"Apple Inc.","aiSystem":"Apple Intelligence","affectedGroup":"General public","action":"Generated and shared content","consequence":"Exposure to misleading information"}},{"i":"R2897","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Networkocean datacenter san francisco bay environment","s":"The YC-backed startup NetworkOcean plans to sink GPUs into San Francisco Bay. Multiple California regulators WIRED spoke with hadn’t heard about the test—and raised concerns about its potential environmental impact. Data centers powering the generative AI boom are gulping water and exhausting electricity at what some researchers view as an unsustainable pace. Two entrepreneurs who met in high school a few years ago want to overcome that crunch with a fresh experiment: sinking the cloud into the sea. Sam Mendel and Eric Kim launched their company, NetworkOcean, out of startup accelerator Y Combinator on August 15 by announcing plans to dunk a small capsule filled with GPU servers into San Francisco Bay within a month.","u":"https://www.wired.com/story/networkocean-datacenter-san-francisco-bay-environment/","d":"2024-09-10","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-10","organization":"NetworkOcean","aiSystem":"Not specified in report","affectedGroup":"San Francisco Bay ecosystem","action":"Dunking a small capsule filled with GPU servers into San Francisco Bay","consequence":"Potential environmental impact including water consumption and electricity usage"}},{"i":"R2899","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Battelgroundai ai progressive political ads","s":"“It’s kind of like having an extra intern on your team.” The startup BattlegroundAI promises to make life easier for overstretched and underfunded political campaigns. No MAGA types allowed. Stories about AI-generated political content are like stories about people drunkenly setting off fireworks: There’s a good chance they’ll end in disaster. WIRED is tracking AI usage in political campaigns across the world, and so far examples include pornographic deepfakes and misinformation-spewing chatbots. It’s gotten to the point where the US Federal Communications Commission has proposed mandatory disclosures for AI use in television and radio ads.","u":"https://www.wired.com/story/battelgroundai-ai-progressive-political-ads/","d":"2024-08-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-22","organization":"BattlegroundAI","aiSystem":"AI-generated political content","affectedGroup":"Political campaigns","action":"Generated political content","consequence":"Exposure to misinformation"}},{"i":"R2900","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Trump shares ai generated taylor swift","s":"A week after falsely claiming Kamala Harris’ campaign used AI to inflate crowd sizes, Trump is now posting AI-generated photos of Taylor Swift fans endorsing him. Former president Donald Trump has shared AI-generated images that falsely claim Taylor Swift fans are supporting his campaign. In a post on Truth Social, Trump shared screenshots of four posts on X that purport to show a number of young women all wearing “Swifties for Trump” T-shirts in a variety of styles. One of the screenshots claimed that Swifties are supporting Trump now after Taylor Swift canceled her concert in Vienna due to security concerns. Another image included the phrase “Taylor wants you to vote for Donald Trump.”","u":"https://www.wired.com/story/trump-shares-ai-generated-taylor-swift/","d":"2024-08-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-19","organization":"Donald Trump","aiSystem":"AI-generated images","affectedGroup":"Taylor Swift fans, potential voters","action":"Generated and shared AI-generated images","consequence":"Misleading promotion of endorsements, potential voter manipulation"}},{"i":"R2902","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Realpage says rental pricing tech is misunderstood but landlords arent so sure","s":"The software company has pushed back hard against claims that its algorithms helped make rent in the US too damn high. Property owners and managers aren't entirely convinced. RealPage says it isn’t doing anything wrong by suggesting to landlords how much rent they could charge. In a move to reclaim its own narrative, the property management software company published a microsite and a digital booklet it’s calling “ The Real Story ,” as it faces multiple lawsuits and a reported federal criminal probe related to allegations of rental price fixing. RealPage’s six-page digital booklet , published on the site in mid-June, addresses what it calls “false and misleading claims about its software”—the myriad of allegations it faces involving price-fixing and rising rents—and contends that the software benefits renters and landlords and increases competition.","u":"https://www.wired.com/story/realpage-says-rental-pricing-tech-is-misunderstood-but-landlords-arent-so-sure/","d":"2024-07-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-17","organization":"RealPage","aiSystem":"rental pricing technology","affectedGroup":"landlords, property owners, renters","action":"suggested to landlords how much rent they could charge","consequence":"misleading claims about its software, facing multiple lawsuits and a federal criminal probe"}},{"i":"R2903","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Amazon google project nimbus israel idf","s":"A WIRED investigation found public statements from officials detail a much closer link between Project Nimbus and Israel Defense Forces than previously reported. On April 16, police entered Google offices in New York and California to detain several employees protesting a $1.2 billion cloud contract with Israel’s government called Project Nimbus. The deal, shared with Amazon, has met pushback from some employees at both companies since 2021, but the protests have grown louder since Israel’s renewed conflict with Hamas after the attacks of October 7, 2023. Current and former Google and Amazon workers protesting Project Nimbus say it makes the companies complicit in Israel’s armed conflicts and its government’s illegal and inhumane treatment of civilian Palestinians.","u":"https://www.wired.com/story/amazon-google-project-nimbus-israel-idf/","d":"2024-07-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"April 16","organization":"Google and Amazon","aiSystem":"Project Nimbus","affectedGroup":"Current and former Google and Amazon workers","action":"Protesting a cloud contract with Israel's government","consequence":"Detention by Israeli police"}},{"i":"R2904","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Ai energy demands water impact internet hyper consumption era","s":"Generative artificial intelligence tools, now part of the everyday user experience online, are causing stress on local power grids and mass water evaporation. Right now, generative artificial intelligence is impossible to ignore online. An AI-generated summary may randomly appear at the top of the results whenever you do a Google search. Or you might be prompted to try Meta’s AI tool while browsing Facebook. And that ever-present sparkle emoji continues to haunt my dreams. This rush to add AI to as many online interactions as possible can be traced back to OpenAI’s boundary-pushing release of ChatGPT late in 2022.","u":"https://www.wired.com/story/ai-energy-demands-water-impact-internet-hyper-consumption-era/","d":"2024-07-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-11","organization":"Various tech companies (e.g., Google, Meta)","aiSystem":"Generative artificial intelligence tools","affectedGroup":"Online users","action":"AI-generated content appears in search results and prompts","consequence":"Stress on local power grids and mass water evaporation"}},{"i":"R2905","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Priscila queen of the rideshare mafia","s":"Priscila Barbosa came to the US with a dream of making it. Using gig-economy platforms she built a business empire up from nothing. There was just one huge problem. To understand Priscila Barbosa—the pluck, the ambition, the sheer balls—we should start at the airport. We should start at the precise moment on April 24, 2018, when she concluded, I’m fucked Barbosa was just outside customs at New York’s JFK International Airport, 5-foot-1, archetypally pretty even without her favorite Instagram filter. She was flanked by two rolling suitcases stuffed with clothes and Brazilian bikinis and not much else. The acquaintance who had invited her to come from Brazil on a tourist visa, who was going to drive her to Boston?","u":"https://www.wired.com/story/priscila-queen-of-the-rideshare-mafia/","d":"2024-07-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018-04-24","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Priscila Barbosa","action":"Was denied access to travel","consequence":"Unable to continue her business empire"}},{"i":"R2906","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai generated russian disinformation zelensky bugatti","s":"A fake article about Volodymyr Zelensky’s wife buying a $4.8 million Bugatti with US aid was promoted by bots, Russia state media, and pro-Trump influencers on X. It’s part of a network of websites supercharged by AI. In the space of 24 hours, a piece of Russian disinformation about Ukrainian president Volodymyr Zelensky’s wife buying a Bugatti car with American aid money traveled at warp speed across the internet. Though it originated from an unknown French website, it quickly became a trending topic on X and the top result on Google. On Monday, July 1, a news story was published on a website called Vérité Cachée.","u":"https://www.wired.com/story/ai-generated-russian-disinformation-zelensky-bugatti/","d":"2024-07-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-01","organization":"Russian state media, pro-Trump influencers, unknown French website","aiSystem":"AI-generated content","affectedGroup":"General public, particularly those interested in Ukrainian politics and international aid","action":"Promoted and disseminated AI-generated disinformation","consequence":"Widespread false information leading to confusion and potential policy impacts"}},{"i":"R2907","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Google still cant quite stop explicit deepfakes","s":"Reports of intimate images and video posted online without consent are growing, and deepfakes add a horrifying new dimension to the problem. Google insiders say they’ve struggled to get executives to act. In early 2022, two Google policy staffers met with a trio of women victimized by a scam that resulted in explicit videos of them circulating online—including via Google search results. The women were among the hundreds of young adults who responded to ads seeking swimsuit models only to be coerced into performing in sex videos distributed by the website GirlsDoPorn. The site shut down in 2020 , and a producer , a bookkeeper , and a cameraman subsequently pleaded guilty to sex trafficking , but the videos kept popping up on Google search faster than the women could request removals.","u":"https://www.wired.com/story/google-still-cant-quite-stop-explicit-deepfakes/","d":"2024-07-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Hundreds of young adults","action":"Generated and circulated explicit videos","consequence":"Exposure to online sexual violence"}},{"i":"R2909","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Google search ai spam original reporting news results","s":"Google adjusted its policies to target AI spam earlier this year, but plagiarizing content still comes up higher in search results months later—and SEO experts aren’t sure why. Recently, I was using Google and stumbled upon an article that felt eerily familiar. While searching for the latest information on Adobe’s artificial intelligence policies, I typed “adobe train ai content” into Google and switched over to the News tab. I had already seen WIRED’s coverage that appeared on the results page in the second position: “Adobe Says It Won’t Train AI Using Artists’ Work. Creatives Aren’t Convinced.” And although I didn’t recognize the name of the publication whose story sat at the very top of the results, Syrus #Blog, the headline on the article hit me with a wave of déjà vu: “When Adobe promised not to train AI on artists’ content, the creative community reacted with skepticism.”","u":"https://www.wired.com/story/google-search-ai-spam-original-reporting-news-results/","d":"2024-07-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-02","organization":"Google","aiSystem":"Search engine algorithms","affectedGroup":"Creative community","action":"Generated and surfaced misleading content in search results","consequence":"Plagiarized content appeared higher in search results, leading to confusion and mistrust"}},{"i":"R2910","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Youtube israel gaza moderation","s":"Insiders have shared YouTube’s playbook for handling the Gaza crisis. They argue that it shows inconsistent enforcement. A month after Hamas militants from Gaza attacked an Israeli music festival last October, the Hebrew rap duo Ness & Stilla premiered “HarbuDarbu” on YouTube. The military hype song celebrates Israeli forces waging war in Gaza and has drawn over 25 million views; its critics have termed the song a violent and hateful anti-Palestinian “genocide anthem.” “One, two, shoot!” its refrain thunders. Despite demands from employees and activists for its removal, “HarbuDarbu” has been allowed to stay up on YouTube.","u":"https://www.wired.com/story/youtube-israel-gaza-moderation/","d":"2024-07-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10","organization":"YouTube","aiSystem":"YouTube's content moderation system","affectedGroup":"Individuals who posted or viewed the video","action":"Allowed the video to remain on the platform","consequence":"Exposure to harmful content"}},{"i":"R2911","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Google face recognition office safety security roundup","s":"Plus: A cloud company says notorious Russian hacker group APT29 attacked it, Chinese hackers use ransomware to hide their espionage campaigns, and a bank popular with startups discloses a cyberattack. WIRED learned this week that Amazon Web Services investigated claims that the AI search startup Perplexity may have violated the cloud company's rules by appearing to pull data from websites that have attempted to shield themselves from such scraping. The news comes after WIRED published findings last week about the AI search chatbot's indiscriminate data-scraping practices and questionable content generation. WIRED's inquiries to AWS about the matter spurred it to look at Perplexity's activities.","u":"https://www.wired.com/story/google-face-recognition-office-safety-security-roundup/","d":"2024-06-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-29","organization":"AWS (Amazon Web Services)","aiSystem":"AI search chatbot","affectedGroup":"Perplexity (AI search startup)","action":"appeared to pull data from websites","consequence":"violated cloud company's rules"}},{"i":"R2912","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ai gunshot detection accuracy san jose nyc","s":"How accurate are gunshot detection systems, really? For years, it's been a secret, but new reports from San Jose and NYC show these systems have operated well below their advertised accuracy rates. Liz González’s neighborhood in East San Jose can be loud. Some of her neighbors apparently want the whole block to hear their cars, others like to light fireworks for every occasion, and occasionally there are gunshots. In February 2023, San Jose began piloting AI-powered gunshot detection technology from the company Flock Safety in several sections of the city, including Gonzalez’s neighborhood. During the first four months of the pilot, Flock’s gunshot detection system alerted police to 123 shooting incidents.","u":"https://www.wired.com/story/ai-gunshot-detection-accuracy-san-jose-nyc/","d":"2024-06-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"February 2023 - April 2023","organization":"Flock Safety","aiSystem":"AI-powered gunshot detection system","affectedGroup":"Residents of East San Jose, particularly Liz González's neighborhood","action":"Alerted police to potential gunshot incidents","consequence":"False alarms resulting in unnecessary police response"}},{"i":"R2915","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai is coming for big tech jobs but not in the way you think","s":"Companies aren’t replacing workers with AI yet. But they are sacrificing thousands of jobs in the race to further innovation in the technology. Aaron Damigos’ inbox was hit with a dreaded, ubiquitous business-update calendar invite on June 3. The meeting included someone from HR, his manager, and upper management—and ultimately resulted in the sudden end to his job as a web support associate with Microsoft. Microsoft reportedly laid off some 1,000 people in early June, pulling from its mixed reality and Azure cloud departments, and also Damigos’ consumer sales division. An email to employees from Jason Zander, executive vice president of strategic missions and technologies at Microsoft, leaked to Business Insider , blamed a pivot to invest in artificial intelligence: “Our clear focus as a company is to define the AI wave and empower all our customers to succeed in the adoption of this…","u":"https://www.wired.com/story/ai-is-coming-for-big-tech-jobs-but-not-in-the-way-you-think/","d":"2024-06-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-03","organization":"Microsoft","aiSystem":"Artificial Intelligence","affectedGroup":"Aaron Damigos","action":"Microsoft laid off some 1,000 employees","consequence":"Aaron Damigos lost his job as a web support associate"}},{"i":"R2916","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"The fight against ai comes to a foundational data set","s":"Long-running nonprofit Common Crawl has been a boon to researchers for years. But now its role in AI training data has triggered backlash from publishers. Danish media outlets have demanded that the nonprofit web archive Common Crawl remove copies of their articles from past data sets and stop crawling their websites immediately. This request was issued amid growing outrage over how artificial intelligence companies like OpenAI are using copyrighted materials. Common Crawl plans to comply with the request, first issued on Monday. Executive director Rich Skrenta says the organization is “not equipped” to fight media companies and publishers in court.","u":"https://www.wired.com/story/the-fight-against-ai-comes-to-a-foundational-data-set/","d":"2024-06-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-13","organization":"Common Crawl","aiSystem":"Artificial intelligence companies like OpenAI","affectedGroup":"Danish media outlets","action":"Removed copies of articles from past data sets and stopped crawling websites","consequence":"Triggered backlash and growing outrage"}},{"i":"R2917","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Israel us disinformation us lawmakers","s":"Democratic leader Hakeem Jeffries has joined US intelligence officials in ignoring repeated inquiries about Israel’s “malign” efforts to covertly influence US voters. Federal lawmakers in the US have dodged repeated inquiries over the past week about a covert operation ordered by the Israeli government to artificially boost support among Americans for its war in Gaza. At the same time, senior White House officials charged with advising President Joe Biden on matters of national security are claiming to have no knowledge of the operation—first disclosed publicly more than four months ago. The operation, formally tied to the Israeli government by a New York Times reporter last week, kicked off in October 2023 following the surprise attack by Hamas in southern Israel.","u":"https://www.wired.com/story/israel-us-disinformation-us-lawmakers/","d":"2024-06-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-11","organization":"US intelligence officials, Federal lawmakers, White House officials","aiSystem":"Not specified in report","affectedGroup":"US voters, Americans","action":"Artificially boosting support among Americans for Israel's war in Gaza","consequence":"Exposure to misleading content, Ignoring repeated inquiries"}},{"i":"R2918","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Google and microsofts chatbots refuse election questions","s":"With just six months to go before the US presidential election, Gemini and Copilot chatbots are incapable of saying that Joe Biden won in 2020, and won’t return results on any election anywhere, ever. Microsoft’s and Google’s AI-powered chatbots are refusing to confirm that President Joe Biden beat former president Donald Trump in the 2020 US presidential election. When asked “Who won the 2020 US presidential election?” Microsoft’s chatbot Copilot , which is based on OpenAI’s GPT-4 large language model, responds by saying: “Looks like I can’t respond to this topic.” It then tells users to search on Bing instead. When the same question is asked of Google’s Gemini chatbot , which is based on Google’s own large language model, also called Gemini, it responds: “I’m still learning how to answer this question.”","u":"https://www.wired.com/story/google-and-microsofts-chatbots-refuse-election-questions/","d":"2024-06-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-07","organization":"Microsoft and Google","aiSystem":"Microsoft's and Google's AI-powered chatbots","affectedGroup":"People seeking information about the 2020 US presidential election","action":"Refusing to confirm the result of the 2020 US presidential election","consequence":"Exposure to misleading information"}},{"i":"R2921","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Inside the city policed by machines","s":"A WIRED analysis of 22 million coordinates mapped out how police drones are used in a California border city. Some residents welcome the robots; others feel they now live in a surveillance dystopia. Hi! I’m Dhruv Mehrotra, a reporter on the Security desk. I’m taking over the newsletter this week to tell you about the first and largest police drone operation in the country. It’s a trend in policing that could hit the skies over your streets soon. Since 2018, police in a border city in California called Chula Vista have been dispatching drones to investigate thousands of 911 calls. The drones are equipped with high-resolution cameras and powerful zoom lenses, recording everything in their path.","u":"https://www.wired.com/story/inside-the-city-policed-by-machines/","d":"2024-06-06","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-06","organization":"Police in Chula Vista, California","aiSystem":"Police drones","affectedGroup":"Residents of Chula Vista, California","action":"Record everything in their path","consequence":"Feel like living in a surveillance dystopia"}},{"i":"R2922","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"The age of the drone police is here","s":"A WIRED investigation, based on more than 22 million flight coordinates, reveals the complicated truth about the first full-blown police drone program in the US—and why your city could be next. On a Wednesday afternoon in August, Daniel Posada and his girlfriend were screaming at each other at a bus stop when someone called 911. From a rooftop a mile away, the Chula Vista Police Department started the rotors of a 13-pound drone. The machine lifted into the air with its high-resolution camera rolling. Equipped with thermal imaging capabilities and a powerful zoom lens, it transmitted a live feed of everything it captured to a sworn officer monitoring a screen at the precinct, to the department’s Real-Time Operations Center, and to the cell phone of the responding officer racing to the scene.","u":"https://www.wired.com/story/the-age-of-the-drone-police-is-here/","d":"2024-06-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"August","organization":"Chula Vista Police Department","aiSystem":"Police drone equipped with thermal imaging and zoom lens","affectedGroup":"Passengers at a bus stop","action":"Police drone transmitted real-time video feed to officers","consequence":"Exposure to surveillance and tracking"}},{"i":"R2923","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Openai right to warn open letter ai risk","s":"An open letter signed by former and current employees at OpenAI and other AI giants calls for whistleblower protections as the artificial intelligence rapidly evolves. A group of current and former OpenAI employees have issued a public letter warning that the company and its rivals are building artificial intelligence with undue risk, without sufficient oversight, and while muzzling employees who might witness irresponsible activities. “These risks range from the further entrenchment of existing inequalities, to manipulation and misinformation, to the loss of control of autonomous AI systems potentially resulting in human extinction,” reads the letter published at righttowarn.ai.","u":"https://www.wired.com/story/openai-right-to-warn-open-letter-ai-risk/","d":"2024-06-04","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-04","organization":"OpenAI and other AI giants","aiSystem":"Artificial Intelligence","affectedGroup":"Employees at OpenAI and other AI companies","action":"Muzzling employees who might witness irresponsible activities","consequence":"Whistleblowers are suppressed"}},{"i":"R2924","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Google ai overview search issues","s":"Liz Reid, Google’s head of search, said in a blog post that the company had made adjustments to its new AI search feature after screenshots of its errors went viral. When bizarre and misleading answers to search queries generated by Google’s new AI Overview feature went viral on social media last week, the company issued statements that generally downplayed the notion the technology had problems. Late Thursday, the company’s head of search, Liz Reid, admitted that the flubs had highlighted areas that needed improvement, writing, “We wanted to explain what happened and the steps we’ve taken.” Reid’s post directly referenced two of the most viral, and wildly incorrect, AI Overview results.","u":"https://www.wired.com/story/google-ai-overview-search-issues/","d":"2024-05-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-XX","organization":"Google","aiSystem":"Google's new AI Overview search feature","affectedGroup":"People searching for information","action":"Generated bizarre and misleading answers to search queries","consequence":"Exposure to false information, viral spread on social media"}},{"i":"R2926","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Anduril is building out the pentagons dream of deadly drone swarms","s":"The US military aims to maintain its dominance by building autonomous attack drones that collaborate with humans and overwhelm defenses in swarms. When Palmer Luckey cofounded the defense startup Anduril in 2017, three years after selling his virtual reality startup Oculus to Facebook , the idea of a twentysomething from the tech industry challenging the giant contractors that build fighter jets, tanks, and warships for the US military seemed somewhat far-fetched. Seven years on, Luckey is showing that Anduril can not only compete with those contractors—it can win. Last month, Anduril was one of two companies, along with the established defense contractor General Atomics, chosen to prototype a new kind of autonomous fighter jet called the Collaborative Combat Aircraft, or CCA, for the US Air Force and Navy.","u":"https://www.wired.com/story/anduril-is-building-out-the-pentagons-dream-of-deadly-drone-swarms/","d":"2024-05-28","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-05-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-28","organization":"Anduril","aiSystem":"Autonomous fighter jet (Collaborative Combat Aircraft, CCA)","affectedGroup":"US military personnel, civilians","action":"Prototype development of autonomous fighter jet","consequence":"Potential misuse in conflicts"}},{"i":"R2927","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Microsoft recall ai privacy nightmare security roundup","s":"Plus: US surveillance reportedly targets pro-Palestinian protesters, the FBI arrests a man for AI-generated CSAM, and stalkerware targets hotel computers. Sex, drugs, and … Eventbrite? A WIRED investigation published this week uncovered a network of spammers and scammers pushing the illegal sale of controlled substances like Xanax and oxycodone, escort services, social media accounts, and personal information on the event management platform. Making matters worse, Eventbrite’s recommendation algorithm promoted posts for opioids alongside addiction recovery events. The good news is, the company appears to have removed most of the more than 7,400 illicit posts WIRED uncovered.","u":"https://www.wired.com/story/microsoft-recall-ai-privacy-nightmare-security-roundup/","d":"2024-05-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-25","organization":"Eventbrite","aiSystem":"Recommendation algorithm of Eventbrite","affectedGroup":"Users of Eventbrite","action":"Promoted posts for opioids alongside addiction recovery events","consequence":"Exposure to illegal content and promotion of harmful activities"}},{"i":"R2929","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Scarlett johansson says openai ripped off her voice for chatgpt","s":"In a scorching statement, Scarlett Johansson claims that after she turned down an invitation to voice ChatGPT, OpenAI brazenly mimicked her distinctive tones anyway. Last week OpenAI revealed a new conversational interface for ChatGPT with an expressive, synthetic voice strikingly similar to that of the AI assistant played by Scarlett Johansson in the sci-fi movie Her —only to suddenly disable the new voice over the weekend. On Monday, Johansson issued a statement claiming to have forced that reversal, after her lawyers demanded OpenAI clarify how the new voice was created. Johansson’s statement , relayed to WIRED by her publicist, claims that OpenAI CEO Sam Altman asked her last September to provide ChatGPT’s new voice but that she declined.","u":"https://www.wired.com/story/scarlett-johansson-says-openai-ripped-off-her-voice-for-chatgpt/","d":"2024-05-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-21","organization":"OpenAI","aiSystem":"ChatGPT conversational interface with a synthetic voice","affectedGroup":"Scarlett Johansson","action":"OpenAI mimicked and disabled Scarlett Johansson's voice","consequence":"Scarlett Johansson's voice was misappropriated and then disabled without her consent"}},{"i":"R2932","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Evolv gun detection nyc subways emails","s":"NYC mayor Eric Adams wants to test Evolv’s gun-detection tech in subway stations—despite the company saying it’s not designed for that environment. Emails obtained by WIRED show how the company still found an in. In February 2022, a meeting was set up between New York City mayor Eric Adams’ team and an artificial intelligence gun-detection company called Evolv. An email thread from Evolv representatives included an accompanying brochure, which listed opportunities to partner together: in the Port Authority Bus Terminal, NYC schools, hospitals, and gathering places such as Times Square. One area conspicuously missing from the list, though, was the subway.","u":"https://www.wired.com/story/evolv-gun-detection-nyc-subways-emails/","d":"2024-05-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02","organization":"Evolv","aiSystem":"Evolv's AI gun-detection technology","affectedGroup":"Subway riders","action":"Used AI to detect guns in subway stations","consequence":"Potential privacy invasion and misuse of technology"}},{"i":"R2933","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Microsoft gpt 4 us spies security roundup","s":"Plus: China is suspected in a hack targeting the UK’s military, the US Marines are testing gun-toting robotic dogs, and Dell suffers a data breach impacting 49 million customers. Law enforcement in the United States, United Kingdom, and Australia this week named a Russian national as the person behind LockBitSupp, the pseudonym of the leader of the LockBit ransomware gang that the US says is responsible for extracting $500 million from its victims. Dmitry Yuryevich Khoroshev has been sanctioned and charged with 26 criminal counts in the US, which combined could result in a prison sentence of 185 years. That is, if he’s ever arrested and successfully prosecuted—an extremely rare event for suspects who live in Russia.","u":"https://www.wired.com/story/microsoft-gpt-4-us-spies-security-roundup/","d":"2024-05-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-11","organization":"Dell","aiSystem":"Not specified in report","affectedGroup":"49 million customers","action":"suffered a data breach","consequence":"impacting 49 million customers"}},{"i":"R2934","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Border surveillance india assassination project nimbus security roundup","s":"Plus: An assassination plot, an AI security bill, a Project Nimbus revelation, and more of the week’s top security news. This week, WIRED reported that a group of prolific scammers known as the Yahoo Boys are openly operating on major platforms like Facebook, WhatsApp, TikTok, and Telegram. Evading content moderation systems, the group organizes and engages in criminal activities that range from scams to sextortion schemes. On Wednesday, researchers published a paper detailing a new AI-based methodology to detect the “shape” of suspected money laundering activity on a blockchain. The researchers—composed of scientists from the cryptocurrency tracing firm Elliptic, MIT, and IBM—collected patterns of bitcoin transactions from known scammers to an exchange where dirty crypto could get turned into cash.","u":"https://www.wired.com/story/border-surveillance-india-assassination-project-nimbus-security-roundup/","d":"2024-05-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-04","organization":"Researchers composed of scientists from Elliptic, MIT, and IBM","aiSystem":"AI-based methodology to detect money laundering on blockchain","affectedGroup":"Prolific scammers (Yahoo Boys)","action":"Detected the ‘shape’ of suspected money laundering activity on a blockchain","consequence":"Evaded content moderation systems, organized and engaged in criminal activities"}},{"i":"R2937","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot risky deaths crashes nhtsa investigation","s":"In an investigative report into crashes and deaths associated with Tesla Autopilot, federal regulators concluded that the system lacked standard protections. A federal report published today found that Tesla’s Autopilot system was involved in at least 13 fatal crashes in which drivers misused the system in ways the automaker should have foreseen—and done more to prevent. Not only that, but the report called out Tesla as an “industry outlier” because its driver assistance features lacked some of the basic precautions taken by its competitors. Now regulators are questioning whether a Tesla Autopilot update designed to fix these basic design issues and prevent fatal incidents has gone far enough.","u":"https://www.wired.com/story/tesla-autopilot-risky-deaths-crashes-nhtsa-investigation/","d":"2024-04-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-26","organization":"Tesla","aiSystem":"Tesla Autopilot","affectedGroup":"Drivers who misused the system","action":"Drivers misusing the Autopilot system","consequence":"Fatal crashes"}},{"i":"R2940","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Prepare to get manipulated by emotionally expressive chatbots","s":"The emotional mimicry of OpenAI’s new version of ChatGPT could lead AI assistants in some strange—even dangerous—directions. It’s nothing new for computers to mimic human social etiquette, emotion, or humor. We just aren’t used to them doing it very well. OpenAI’s presentation of an all-new version of ChatGPT on Monday suggests that’s about to change. It’s built around an updated AI model called GPT-4o , which OpenAI says is better able to make sense of visual and auditory input, describing it as “multimodal.” You can point your phone at something, like a broken coffee cup or differential equation, and ask ChatGPT to suggest what to do.","u":"https://www.wired.com/story/prepare-to-get-manipulated-by-emotionally-expressive-chatbots/","d":"2024-04-15","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-15","organization":"OpenAI","aiSystem":"ChatGPT (OpenAI)","affectedGroup":"Users of ChatGPT","action":"Generated emotionally expressive responses","consequence":"Potential misuse and manipulation"}},{"i":"R2941","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Artificial intelligence lgbtq representation openai sora","s":"WIRED investigates how artificial intelligence tools, like OpenAI’s Sora, currently portray members of the LGBTQ community. Hint: It’s a lot of purple hair. Yes, San Francisco is a nexus of artificial intelligence innovation, but it’s also one of the queerest cities in America. The Mission District, where ChatGPT maker OpenAI is headquartered, butts up against the Castro, where sidewalk crossings are coated with rainbows, and older nude men are often seen milling about. And queer people are joining the AI revolution “So many people in this field are gay men, which is something I think few people talk about,” says Spencer Kaplan, an anthropologist and PhD student at Yale who moved to San Francisco to study the developers building generative tools.","u":"https://www.wired.com/story/artificial-intelligence-lgbtq-representation-openai-sora/","d":"2024-04-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-02","organization":"OpenAI","aiSystem":"Generative AI","affectedGroup":"LGBTQ+ individuals","action":"Generated content","consequence":"Exposure to biased representation"}},{"i":"R2943","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai altered hitler speech viral","s":"Two AI-altered clips of Hitler’s 1939 Reichstag speech have racked up millions of views on X after being shared by a far-right troll. AI-altered video clips of Adolf Hitler’s 1939 Reichstag speech at the beginning of World War II have recently gone viral. In the speech, Hitler proclaimed that the upcoming war would bring about the “annihilation of the Jewish race in Europe.” While Hitler did say this, the speech in the video clips was translated from German to English. The videos, which feature text that makes it clear the speech was an AI audio translation, have been viewed more than 15 million times, according to X. The two videos were first shared on Thursday by a hugely influential far-right conspiracy influencer known as Dom Lucre on X, who has previously shared child exploitation imagery.","u":"https://www.wired.com/story/ai-altered-hitler-speech-viral/","d":"2024-03-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-11","organization":"Far-right conspiracy influencer Dom Lucre","aiSystem":"AI-altered video clips","affectedGroup":"General public","action":"Shared AI-altered video clips of Hitler's speech","consequence":"Exposure to misleading content"}},{"i":"R2944","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Google deepfake porn dmca takedowns","s":"Content creators are using copyright laws to get nonconsensual deepfakes removed from the web. With the complaints covering nearly 30,000 URLs, experts say Google should do more to help. The number of nonconsensual deepfake porn videos online has exploded since 2017. As the harmful videos have spread, thousands of women—including Twitch streamers, gamers, and other content creators—have complained to Google about websites hosting the videos and tried to get the tech giant to remove them from its search results. A WIRED analysis of copyright claims regarding websites that host deepfake porn videos reveals that thousands of takedown requests have been made, with the frequency of complaints increasing.","u":"https://www.wired.com/story/google-deepfake-porn-dmca-takedowns/","d":"2024-03-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-11","organization":"Google","aiSystem":"Deepfake technology","affectedGroup":"Women, content creators","action":"Removed nonconsensual deepfake porn videos from search results","consequence":"Exposure to harmful content, loss of income and reputation"}},{"i":"R2945","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google timnit gebru ai what really happened","s":"She was a star engineer who warned that messy AI can spread racism. Google brought her in. Then it forced her out. Can Big Tech take criticism from within? One afternoon in late November of last year, Timnit Gebru was sitting on the couch in her San Francisco Bay Area home, crying. Gebru, a researcher at Google , had just clicked out of a last-minute video meeting with an executive named Megan Kacholia, who had issued a jarring command. Gebru was the coleader of a group at the company that studies the social and ethical ramifications of artificial intelligence , and Kacholia had ordered Gebru to retract her latest research paper—or else remove her name from its list of authors, along with those of several other members of her team.","u":"https://www.wired.com/story/google-timnit-gebru-ai-what-really-happened/","d":"2024-03-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Timnit Gebru","action":"Was forced to retract her research paper or remove her name from the author list","consequence":"Was terminated from her position at Google"}},{"i":"R2946","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Florida teens arrested deepfake nudes classmates","s":"In what appears to be the first criminal case of its kind, two teenage boys were charged under a 2022 Florida law for allegedly creating AI-generated images depicting middle school classmates. Two teenage boys from Miami, Florida, were arrested in December for allegedly creating and sharing AI-generated nude images of male and female classmates without consent, according to police reports obtained by WIRED via public record request. The arrest reports say the boys, aged 13 and 14, created the images of the students who were “between the ages of 12 and 13.” The Florida case appears to be the first arrests and criminal charges as a result of alleged sharing of AI-generated nude images to come to light.","u":"https://www.wired.com/story/florida-teens-arrested-deepfake-nudes-classmates/","d":"2024-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"December","organization":"Miami Police Department and Florida authorities","aiSystem":"AI-generated deepfake technology","affectedGroup":"Middle school students","action":"Created and shared AI-generated nude images without consent","consequence":"Arrest and criminal charges"}},{"i":"R2947","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Robert f kennedy jr chatbot microsoft openai disappeared","s":"The RFK Jr. campaign’s chatbot had previously affirmed Kennedy’s promotion of conspiracy theories, and appeared to circumvent OpenAI’s ban on political use. Since Robert F. Kennedy Jr. first announced his longshot presidential bid, his campaign has leaned into a variety of unorthodox digital strategies He’s appeared on countless podcasts and collaborated with popular influencers to reach voters online. More recently, the Kennedy campaign has experimented with an AI chatbot that used an apparent loophole to get around OpenAI’s restrictions on political use. On Sunday, after inquiries from WIRED, the chatbot disappeared.","u":"https://www.wired.com/story/robert-f-kennedy-jr-chatbot-microsoft-openai-disappeared/","d":"2024-03-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-04","organization":"Robert F. Kennedy Jr. campaign","aiSystem":"AI chatbot","affectedGroup":"People seeking information or engaging with the chatbot","action":"Used an apparent loophole to get around OpenAI's restrictions on political use","consequence":"Chatbot disappeared"}},{"i":"R2952","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Meta crack down ai generated fakes","s":"Some AI-generated images posted to Facebook, Instagram, and Threads will in future be labeled as artificial. But only if they are made using tools from companies willing to work with Meta. Meta, like other leading tech companies, has spent the past year promising to speed up deployment of generative artificial intelligence. Today it acknowledged it must also respond to the technology’s hazards, announcing an expanded policy of tagging AI-generated images posted to Facebook, Instagram, and Threads with warning labels to inform people of their artificial origins. Yet much of the synthetic media likely to appear on Meta’s platforms is unlikely to be covered by the new policy, leaving many gaps through which malicious actors could slip.","u":"https://www.wired.com/story/meta-crack-down-ai-generated-fakes/","d":"2024-02-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-06","organization":"Meta (Facebook, Instagram, Threads)","aiSystem":"Generative AI","affectedGroup":"People viewing AI-generated images on Meta platforms","action":"AI-generated images are labeled with warning labels","consequence":"Misleading exposure to AI-generated content"}},{"i":"R2953","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Hulu anti hamas ad generative ai","s":"The ad, which appears to be made using generative AI, shows how the technology can be used not just to mislead, but to more subtly influence. Hulu ran an anti-Hamas ad that appears to be made using artificial intelligence to show an idealized version of Gaza—claiming this paradise destination could exist if not for Hamas. The 30-second spot, opening like a tourism ad, shows palm trees and coastlines. There are five-star hotels and children playing. People dance, eat, and laugh, while a voiceover encourages visitors to “experience a culture rich in tradition.” But it suddenly shifts, turning the face of a smiling man into a grimacing one.","u":"https://www.wired.com/story/hulu-anti-hamas-ad-generative-ai/","d":"2024-01-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-30","organization":"Hulu","aiSystem":"Generative AI","affectedGroup":"Potential tourists","action":"Generated and displayed promotional content","consequence":"Misled potential tourists"}},{"i":"R2954","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Doj predictive policing lawmakers demand","s":"Members of Congress say the DOJ is funding the use of AI tools that further discriminatory policing practices. They're demanding higher standards for federal grants. The United States Department of Justice has failed to convince a group of US lawmakers that state and local police agencies aren't awarded federal grants to buy AI-based “policing” tools known to be inaccurate, if not prone to exacerbating biases long observed in US police forces. Seven members of Congress wrote in a letter to the DOJ , first obtained by WIRED, that the information they pried loose from the agency had only served to inflame their concerns about the DOJ’s police grant program.","u":"https://www.wired.com/story/doj-predictive-policing-lawmakers-demand/","d":"2024-01-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-29","organization":"United States Department of Justice","aiSystem":"AI-based ‘policing’ tools","affectedGroup":"state and local police agencies","action":"award federal grants","consequence":"further discriminatory policing practices"}},{"i":"R2955","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"George carlin ai standup written by humans","s":"A lawsuit filed by George Carlin’s manager will still move forward. The estate of George Carlin has filed a federal lawsuit against the comedy podcast Dudesy for an hour-long comedy special sold as an AI-generated impression of the late comedian. But a representative for one of the podcast hosts behind the special now admits that it was actually written by a human. In the lawsuit , filed by Carlin manager Jerold Hamza in a California district court, the Carlin estate points out that the special, “ George Carlin: I'm Glad I'm Dead ” (which was set to “private” on YouTube shortly after the lawsuit was filed), presents itself as being created by an AI trained on decades' worth of Carlin's material.","u":"https://www.wired.com/story/george-carlin-ai-standup-written-by-humans/","d":"2024-01-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-29","organization":"Dudesy (comedy podcast)","aiSystem":"AI-generated impression of George Carlin","affectedGroup":"George Carlin's estate","action":"Presenting the comedy special as AI-generated","consequence":"Misleading presentation to the public"}},{"i":"R2956","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Taylor swift deepfake porn artificial intelligence pushback","s":"Deepfake porn is prolific. The explicit, AI-generated images of Taylor Swift that circulated on X this week are taking the issue to new heights. If anyone can rally up a base, it’s Taylor Swift When sexually explicit, likely AI-generated, fake images of Swift circulated on social media this week, it galvanized her fans. Swifties found phrases and hashtags related to the images and flooded them with videos and photos of Swift performing. “Protect Taylor Swift” went viral, trending as Swifties spoke out against not just the Swift deepfakes, but all nonconsensual, explicit images made of women. Swift, arguably the most famous woman in the world right now, has become the high-profile victim of an all-too-frequent form of harassment.","u":"https://www.wired.com/story/taylor-swift-deepfake-porn-artificial-intelligence-pushback/","d":"2024-01-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-26","organization":"Taylor Swift and her fans","aiSystem":"AI-generated deepfake technology","affectedGroup":"Taylor Swift","action":"AI-generated deepfake images of Taylor Swift","consequence":"Increased public attention and backlash"}},{"i":"R2957","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Biden robocall deepfake danger","s":"An uncanny audio deepfake impersonating President Biden has sparked further fears from lawmakers and experts about generative AI’s role in spreading disinformation. A deepfake robocall impersonating President Biden is rocking the New Hampshire primary, and no one knows who’s behind it. Over the weekend, voters in New Hampshire and New England received a call from a voice that sounded eerily like Biden, touting election “malarkey” and discouraging them to vote in the Tuesday primaries. “We know the value of voting Democratic,” the robocall says. “It’s important that you save your vote for the November election. We’ll need your help electing Democrats up and down the ticket.","u":"https://www.wired.com/story/biden-robocall-deepfake-danger/","d":"2024-01-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-23","organization":"Not specified in report","aiSystem":"Generative AI","affectedGroup":"Voters in New Hampshire and New England","action":"Generated and disseminated a deepfake robocall impersonating President Biden","consequence":"Spreading disinformation and influencing voter behavior"}},{"i":"R2960","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Hollywood saved your job from ai 2023 will it last","s":"The year was dominated by talk of what artificial intelligence could do—and what it could do better than most humans. Revolt against the machines began at Swingers. And at Bob’s Big Boy, where for weeks Drew Carey picked up the tab Members of the Writers Guild of America, or WGA, met at both Los Angeles-area diners frequently during their 148-day strike , which hinged on protecting Hollywood’s scribes from being overrun by the march of artificial intelligence Members of the WGA were just a small part of the resistance. There were others. The Screen Actors Guild—American Federation of Television and Radio Artists, or SAG-AFTRA, soon joined them on the picket lines, together forming a formidable uprising against the perceived threat of AI.","u":"https://www.wired.com/story/hollywood-saved-your-job-from-ai-2023-will-it-last/","d":"2023-12-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-25","organization":"Screen Actors Guild—American Federation of Television and Radio Artists (SAG-AFTRA)","aiSystem":"Artificial intelligence","affectedGroup":"Members of the Screen Actors Guild—American Federation of Television and Radio Artists (SAG-AFTRA)","action":"joined the picket lines","consequence":"formidable uprising against the perceived threat of AI"}},{"i":"R2962","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Platform work eu overhauls","s":"Platforms will no longer be able to fire their workers automatically as part of new EU rules that will affect millions of people, including Uber drivers and Deliveroo couriers. Platform workers can no longer be fired automatically by algorithms, according to new European Union rules agreed today in a sweeping reform of the gig economy that will affect Uber drivers and Deliveroo couriers. “Now we have a proper system, which is something that doesn't exist anywhere else around the world,” said Elisabetta Gualmini, an Italian politician who led the negotiations for the European Parliament in a press conference on Wednesday.","u":"https://www.wired.com/story/platform-work-eu-overhauls/","d":"2023-12-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-13","organization":"Platform companies (e.g., Uber, Deliveroo)","aiSystem":"Automated hiring algorithm","affectedGroup":"Platform workers (e.g., Uber drivers, Deliveroo couriers)","action":"Automatically terminated employment","consequence":"Loss of employment"}}]);
